//@ run-pass
//@ exit-code: 0
//@ description: stdlib/epistemic/affine — a partition of a shared-source quantity (two PK phases summing to 2D/CL) has NEGATIVE phase covariance and the affine sum recovers the exact form; the scalar ep_* chain over-states (RQ4, §8.4)
// Compact form of docs/research/sounio/rq4_vanco_two_compartment_flip.sio (one patient), written
// in small stage functions for readability.

use epistemic::affine::{
    af_measured, af_const, af_add, af_sub, af_scale, af_mul, af_div, af_sqrt,
    af_variance, af_cov, af_value, af_sources_disjoint,
}

fn near_rel(a: f64, b: f64) -> bool {
    let d = a - b
    let ad = if d < 0.0 { 0.0 - d } else { d }
    let ab = if b < 0.0 { 0.0 - b } else { b }
    ad <= 0.00000001 * (1.0 + ab)
}

// CL = 0.695·(75·w/(72·SCr)·0.06) + 0.05   (Cockcroft–Gault → Matzke)
fn cl_of(w: &Affine, sc: &Affine) -> Affine with Mut, Div, Panic {
    let w75 = af_scale(w, 75.0)
    let sc72 = af_scale(sc, 72.0)
    let crcl = af_div(&w75, &sc72)
    let renal = af_scale(&crcl, 0.06 * 0.695)
    let nr = af_const(0.05)
    af_add(&renal, &nr)
}

// α (which 0) / β (which 1) of the two-compartment system from k10, k12, k21
fn root_of(k10: &Affine, k12: &Affine, k21: &Affine, which: i64) -> Affine with Mut, Div, Panic {
    let s01 = af_add(k10, k12)
    let s = af_add(&s01, k21)
    let p = af_mul(k10, k21)
    let s2 = af_mul(&s, &s)
    let p4 = af_scale(&p, 4.0)
    let rad = af_sub(&s2, &p4)
    let disc = af_sqrt(&rad)
    if which == 0 { let spd = af_add(&s, &disc); return af_scale(&spd, 0.5) }
    let smd = af_sub(&s, &disc)
    af_scale(&smd, 0.5)
}

// 2·A/α (which 0) or 2·B/β (which 1) with A = (D/Vc)(α−k21)/(α−β), B = (D/Vc)(k21−β)/(α−β)
fn phase_of(dvc: &Affine, alpha: &Affine, beta: &Affine, k21: &Affine, which: i64) -> Affine with Mut, Div, Panic {
    let amb = af_sub(alpha, beta)
    if which == 0 {
        let amk = af_sub(alpha, k21)
        let ca = af_div(&amk, &amb)
        let a_ = af_mul(dvc, &ca)
        let aa = af_div(&a_, alpha)
        return af_scale(&aa, 2.0)
    }
    let kmb = af_sub(k21, beta)
    let cb = af_div(&kmb, &amb)
    let b_ = af_mul(dvc, &cb)
    let bb = af_div(&b_, beta)
    af_scale(&bb, 2.0)
}

fn main() -> i64 with IO, Mut, Div, Panic {
    var ok: i64 = 1
    // the paper's discriminating patient: 70 ± 1 kg, SCr 1.40 ± 0.14, Q 7 ± 1.4, Vp 35 ± 7, 500 mg q12h
    let w = af_measured(70.0, 1.0, 0)
    let sc = af_measured(1.40, 0.14, 1)
    let q = af_measured(7.0, 1.4, 2)
    let vp = af_measured(35.0, 7.0, 3)
    let cl = cl_of(&w, &sc)
    let vc = af_scale(&w, 0.5)                     // shares the weight source with CL
    let k10 = af_div(&cl, &vc)
    let k12 = af_div(&q, &vc)
    let k21 = af_div(&q, &vp)
    let alpha = root_of(&k10, &k12, &k21, 0)
    let beta = root_of(&k10, &k12, &k21, 1)
    let d = af_const(500.0)
    let dvc = af_div(&d, &vc)
    let pa = phase_of(&dvc, &alpha, &beta, &k21, 0)
    let pb = phase_of(&dvc, &alpha, &beta, &k21, 1)
    let auc = af_add(&pa, &pb)
    let d2 = af_const(1000.0)
    let direct = af_div(&d2, &cl)                  // the identity: AUC24 = 2·D/CL

    // (1) identity holds to first order, value AND variance (Q, Vp cancel exactly)
    if !near_rel(af_value(&auc), af_value(&direct)) { ok = 0 }
    if !near_rel(af_variance(&auc), af_variance(&direct)) { ok = 0 }
    // (2) the phases are NOT disjoint (E230 would reject pa + pb) and their covariance is negative
    if af_sources_disjoint(&pa, &pb) { ok = 0 }
    if !(af_cov(&pa, &pb) < 0.0) { ok = 0 }
    // (3) hence the independence-assuming add over-states: naive > true
    if !(af_variance(&pa) + af_variance(&pb) > af_variance(&auc)) { ok = 0 }
    // (4) and the paper's numbers: AUC ≈ 450, u ≈ 44 → lower 95 % bound below 400 (the WARN)
    let v = af_value(&auc)
    let u2 = 4.0 * af_variance(&auc)               // (2u)²
    if !(v > 440.0 && v < 460.0) { ok = 0 }
    if !((v - 400.0) * (v - 400.0) < u2) { ok = 0 }  // v − 2u < 400

    if ok == 1 { println("AFFINE_PHASE_PARTITION_IDENTITY PASS"); return 0 }
    println("AFFINE_PHASE_PARTITION_IDENTITY FAIL")
    1
}

//@ run-pass
//@ exit-code: 0
//@ description: stdlib/epistemic/affine — delta-method product: Var(a·b) = b²Var a + a²Var b + 2ab·Cov; x·x equals square (ep_mul understates by half); quotient and sqrt consistent
// Companion to formal/lean4/EpistemicEffectsNS.lean: trueVar_mul, x_times_x_understates.

use epistemic::affine::{
    af_measured, af_mul, af_div, af_square, af_sqrt, af_variance, af_cov, af_value,
}
use epistemic::knowledge::{ep_measured, ep_mul, ep_square, ep_variance}

fn close2(a: f64, b: f64) -> bool {
    let d = a - b
    let ad = if d < 0.0 { 0.0 - d } else { d }
    let ab = if b < 0.0 { 0.0 - b } else { b }
    ad <= 0.000001 * (1.0 + ab)
}

fn main() -> i64 with IO, Mut, Div, Panic {
    var ok: i64 = 1
    let x = af_measured(10.0, 1.0, 0)
    let y = af_measured(20.0, 2.0, 1)

    // Disjoint sources: delta method agrees with ep_mul: 20²·1 + 10²·4 = 800.
    let xy = af_mul(&x, &y)
    if !close2(af_variance(&xy), 800.0) { ok = 0 }
    let ex = ep_measured(10.0, 1.0)
    let ey = ep_measured(20.0, 2.0)
    let exy = ep_mul(&ex, &ey)
    if !close2(ep_variance(&exy), 800.0) { ok = 0 }

    // Shared source: x·x. True first-order Var = (2·10)²·1 = 400 = ep_square; ep_mul(x,x) = 200.
    let xx = af_mul(&x, &x)
    if !close2(af_variance(&xx), 400.0) { ok = 0 }
    let xsq = af_square(&x)
    if !close2(af_variance(&xsq), 400.0) { ok = 0 }
    let exsq = ep_square(&ex)
    if !close2(ep_variance(&exsq), 400.0) { ok = 0 }
    let exx = ep_mul(&ex, &ex)
    if !close2(ep_variance(&exx), 200.0) { ok = 0 }   // the two-formula defect, live

    // Var(a·b) = b²Var a + a²Var b + 2ab·Cov(a,b), checked on a = x, b = x + y (Cov = 1).
    let b = af_mul(&x, &x)              // reuse: b := x·x has Cov(x, b) = 2·10·1 = 20
    let cov = af_cov(&x, &b)
    if !close2(cov, 20.0) { ok = 0 }
    let xb = af_mul(&x, &b)             // x³: true Var = (3·100)²·1 = 90000
    let bv = af_value(&b)
    let xv = af_value(&x)
    let t1 = bv * bv * af_variance(&x)
    let t2 = xv * xv * af_variance(&b)
    let t3 = 2.0 * xv * bv * cov
    let predicted = t1 + t2 + t3
    if !close2(af_variance(&xb), predicted) { ok = 0 }
    if !close2(af_variance(&xb), 90000.0) { ok = 0 }

    // Quotient and root: y / y is exactly certain; sqrt(x)² recovers x's variance to first order.
    let yy = af_div(&y, &y)
    if !close2(af_variance(&yy), 0.0) { ok = 0 }
    if !close2(af_value(&yy), 1.0) { ok = 0 }
    let sx = af_sqrt(&x)
    let sx2 = af_square(&sx)
    if !close2(af_variance(&sx2), 1.0) { ok = 0 }

    if ok == 1 { println("AFFINE_PRODUCT_DELTA PASS"); return 0 }
    println("AFFINE_PRODUCT_DELTA FAIL")
    1
}

//@ run-pass
//@ exit-code: 0
//@ description: stdlib/epistemic/affine — x + x on one source gives Var 4 (ep_add reports 2); x + y on disjoint sources gives 5 in both; Lemma 1 gap = 2·Cov in both signs
// Companion to formal/lean4/EpistemicEffectsNS.lean: trueVar_append, naive_add_understates_iff,
// naive_add_conservative_of_cov_nonpos, naive_add_exact_iff — the same identities, executed.

use epistemic::affine::{
    af_measured, af_add, af_sub, af_scale, af_variance, af_cov, af_add_gap,
    af_naive_add_variance, af_sources_disjoint, af_value,
}
use epistemic::knowledge::{ep_measured, ep_add, ep_variance}

fn close2(a: f64, b: f64) -> bool {
    let d = a - b
    let ad = if d < 0.0 { 0.0 - d } else { d }
    ad < 0.000001
}

fn main() -> i64 with IO, Mut, Div, Panic {
    var ok: i64 = 1
    let x = af_measured(10.0, 1.0, 0)
    let y = af_measured(20.0, 2.0, 1)

    // x + x: true Var = 4 (one source, coefficient 2); the scalar add reports 1 + 1 = 2.
    let xx = af_add(&x, &x)
    if !close2(af_variance(&xx), 4.0) { ok = 0 }
    if !close2(af_naive_add_variance(&x, &x), 2.0) { ok = 0 }
    if !close2(af_add_gap(&x, &x), 2.0) { ok = 0 }              // 2·Cov = 2·1
    let ex = ep_measured(10.0, 1.0)
    let exx = ep_add(&ex, &ex)
    if !close2(ep_variance(&exx), 2.0) { ok = 0 }                // the shipped scalar add: 2, understated
    if af_sources_disjoint(&x, &x) { ok = 0 }                  // the E230 precondition fails on x + x

    // x + y on disjoint sources: 1 + 4 = 5 both ways; gap 0.
    let xy = af_add(&x, &y)
    if !close2(af_variance(&xy), 5.0) { ok = 0 }
    if !close2(af_add_gap(&x, &y), 0.0) { ok = 0 }
    if !af_sources_disjoint(&x, &y) { ok = 0 }
    if !close2(af_value(&xy), 30.0) { ok = 0 }

    // Negative covariance: x + (−x + y) — the naive add OVER-states (Cov < 0 ⇒ conservative).
    let nx = af_scale(&x, 0.0 - 1.0)
    let z = af_add(&nx, &y)                                    // z = -x + y: c = (-1, 2)
    if !close2(af_cov(&x, &z), 0.0 - 1.0) { ok = 0 }
    let xz = af_add(&x, &z)                                    // = y: true Var 4
    if !close2(af_variance(&xz), 4.0) { ok = 0 }
    if !(af_naive_add_variance(&x, &z) > af_variance(&xz)) { ok = 0 }   // 1 + 5 = 6 > 4
    if !close2(af_add_gap(&x, &z), 0.0 - 2.0) { ok = 0 }

    // Subtraction on a shared source: x − x is exactly certain.
    let zero = af_sub(&x, &x)
    if !close2(af_variance(&zero), 0.0) { ok = 0 }

    if ok == 1 { println("AFFINE_SHARED_SOURCE_ADD PASS"); return 0 }
    println("AFFINE_SHARED_SOURCE_ADD FAIL")
    1
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: AGGREGATE_NESTED_DEEP_COPY_OK
// Regression gate for #1479: binding an aggregate local must value-copy its
// AGGREGATE FIELDS too, not just its outer slots.
//
// #1475 fixed the outer copy: `var s2 = s1` stopped aliasing the struct handle,
// so a SCALAR field write to the copy was no longer visible through the source.
// That copy was FLAT, so a field holding an array or a nested struct still
// copied the 64-bit HANDLE — `s2.arr[0] = 99` was observed through `s1`, check
// passed, the ELF ran, exit 0, wrong answer. This file pins the deep copy.
//
// GATED TO MADAROS. lean_single INLINES an array-typed struct field
// (struct_like_nslots = st_total_size / 8) where Madaros holds it as a handle
// (lower_struct_literal_expr_ref, count_struct_fields * 8), so lean_single never
// exhibited this bug — but its own `[Struct; N]` and nested-struct handling is a
// separate representation with its own boundaries, and pinning both engines from
// one file would conflate them. That engine divergence is unchanged by #1479 and
// remains open.
//
// KNOWN COST, NOT YET RESOLVED — the deep copy ALLOCATES. A struct with k
// aggregate fields needs 1 + k handles per copy instead of 1. The native handle
// table is a fixed 1,048,576 entries that is never reclaimed
// (native_v2_handle_table_capacity_default, self-hosted/native/gc.sio:36; the
// slow path is fail-closed, "no empty-frame reset, live roots not precisely
// mapped", exit 182). tests/run-pass/dissertation_pbpk28_parity_ref_rapamycin.sio
// copies a 6-array-field struct on every one of its 30,000 CN steps. Measured by
// bisecting the step count, the handle ceiling for that program moves from ~110,000
// steps to ~26,800 (about 4.1x the handle pressure), leaving it roughly 12% past
// the ceiling. Its numbers are UNCHANGED — a reduced-horizon run of the same model
// is byte-identical under both compilers, exit 0 both — so the failure is resource
// exhaustion, not semantics. That gate is why this change is not landable as it
// stands.
//
// STILL DELIBERATELY NOT ASSERTED — an array-of-struct field (`[Inner; N]`).
// Copying that array yields fresh element SLOTS whose element handles still
// alias; a half-fix in aliasing is how a new miscompile class is born, so those
// fields keep the shared handle. Same carve-out #1475 made for `[Struct; N]`
// LOCALS.

struct S { arr: [i64; 4], n: i64 }

struct F { v: [f64; 4], k: f64 }

struct Inner { x: i64, y: i64 }

struct Outer { inner: Inner, tag: i64 }

struct L2 { z: i64 }

struct L1 { l2: L2, m: i64 }

struct L0 { l1: L1, n: i64 }

struct In { a: [i64; 3], t: i64 }

struct Out { i: In, u: i64 }

fn bump(s: S) -> i64 with Mut, Div, Panic, Alloc {
    var q = s
    q.arr[0] = 99
    q.arr[0] + s.arr[0]
}

fn main() -> i32 with IO, Mut, Div, Panic, Alloc {
    // 1. the headline shape: a word-scalar array field
    var s1 = S { arr: [1, 2, 3, 4], n: 7 }
    var s2 = s1
    s2.arr[0] = 99
    assert(s1.arr[0] == 1)
    assert(s2.arr[0] == 99)
    assert(s1.arr[3] == 4)
    assert(s2.arr[3] == 4)
    assert(s1.n == 7)

    // 2. the reverse direction — mutating the SOURCE must not leak into the copy
    var r1 = S { arr: [1, 2, 3, 4], n: 7 }
    var r2 = r1
    r1.arr[1] = 55
    assert(r2.arr[1] == 2)
    assert(r1.arr[1] == 55)

    // 3. f64 array field. Bit survival alone proves little — a GPR copy of an
    //    f64 pattern is bit-exact — so read the copy ARITHMETICALLY: an element
    //    misclassified as int makes the sum wrong, not merely imprecise.
    var f1 = F { v: [1.5, 2.25, 3.125, 4.0625], k: 9.5 }
    var f2 = f1
    let sum = f2.v[0] + f2.v[1]
    assert(sum > 3.7)
    assert(sum < 3.8)
    let prod = f2.v[2] * 2.0
    assert(prod > 6.2)
    assert(prod < 6.3)
    f2.v[0] = 99.75
    assert(f1.v[0] < 2.0)
    assert(f2.v[0] > 99.0)
    let after = f1.v[0] + f1.v[1]
    assert(after > 3.7)
    assert(after < 3.8)
    assert(f2.k > 9.0)

    // 4. nested struct field, one level
    var o1 = Outer { inner: Inner { x: 1, y: 2 }, tag: 5 }
    var o2 = o1
    o2.inner.x = 99
    assert(o1.inner.x == 1)
    assert(o2.inner.x == 99)
    assert(o1.inner.y == 2)
    o2.tag = 6
    assert(o1.tag == 5)

    // 5. two levels of struct nesting — the depth cap is 2, so this is the
    //    deepest shape the copy follows
    var a1 = L0 { l1: L1 { l2: L2 { z: 1 }, m: 2 }, n: 3 }
    var a2 = a1
    a2.l1.l2.z = 99
    assert(a1.l1.l2.z == 1)
    assert(a2.l1.l2.z == 99)
    a2.l1.m = 88
    assert(a1.l1.m == 2)

    // 6. an array reached THROUGH a nested struct
    var w1 = Out { i: In { a: [1, 2, 3], t: 4 }, u: 5 }
    var w2 = w1
    w2.i.a[0] = 99
    assert(w1.i.a[0] == 1)
    assert(w2.i.a[0] == 99)
    w2.i.t = 88
    assert(w1.i.t == 4)

    // 7. by-value struct param with an array field, copied inside the callee
    var p1 = S { arr: [1, 2, 3, 4], n: 7 }
    let bumped = bump(p1)
    assert(bumped == 100)
    assert(p1.arr[0] == 1)

    // 8. repeated copies in a loop stay independent and accumulate nothing
    var base = S { arr: [1, 2, 3, 4], n: 0 }
    var acc: i64 = 0
    var i: i64 = 0
    while i < 5 {
        var c = base
        c.arr[0] = c.arr[0] + i
        acc = acc + c.arr[0]
        i = i + 1
    }
    assert(base.arr[0] == 1)
    assert(acc == 15)

    // 9. the #1475 scalar-field fix must stay fixed
    var q1 = Inner { x: 1, y: 2 }
    var q2 = q1
    q2.x = 99
    assert(q1.x == 1)
    assert(q2.y == 2)

    // 10. previously-working plain array locals must stay working
    var b1: [i64; 4] = [1, 2, 3, 4]
    var b2 = b1
    b2[0] = 99
    assert(b1[0] == 1)

    println("AGGREGATE_NESTED_DEEP_COPY_OK")
    return 0
}

