//@ run-pass
// Test: 64-Entry GUM Uncertainty Budget
//
// Validates:
//   T1: Budget with 10 entries computes correct combined variance (385)
//   T2: All Type B entries produce infinite effective DOF
//   T3: Ranking identifies dominant source (entry 10, idx=9)
//   T4: Percent contributions sum to 100%
//   T5: Type A entries produce finite Welch-Satterthwaite DOF
//
// Uses flat arrays inlined in main to avoid &!Struct write-through limitations.

fn b64_abs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }

fn main() -> i64 with IO, Mut, Div, Panic {
    println("==============================================================")
    println("  64-Entry GUM Uncertainty Budget Tests")
    println("==============================================================")
    var n_pass = 0

    // ---- T1 + T2 + T3 + T4: 10-entry budget, all Type B ----
    // contributions[k-1] = sensitivity^2 * std_uncert^2 = 1^2 * k^2 = k^2
    // k=1..10: contributions = 1, 4, 9, 16, 25, 36, 49, 64, 81, 100
    // sum = 385

    var contributions: [f64; 64] = [0.0; 64]
    var dofs: [f64; 64] = [0.0; 64]
    var rank_indices: [i64; 64] = [0; 64]

    // Init dofs to 1e30 (Type B = infinite DOF)
    var ki = 0
    while ki < 64 { dofs[ki] = 1.0e30; ki = ki + 1 }

    var entry_count: i64 = 0
    var k = 1
    while k <= 10 {
        let kf = k as f64
        let idx = k - 1
        contributions[idx] = kf * kf   // sensitivity=1, std_uncert=k
        dofs[idx] = 1.0e30
        entry_count = entry_count + 1
        k = k + 1
    }

    // Compute combined variance
    var combined_variance = 0.0
    var i = 0
    while i < entry_count {
        combined_variance = combined_variance + contributions[i]
        i = i + 1
    }

    // ---- T1: Combined variance = 385 ----
    println("  T1: Combined variance = "); println(combined_variance)
    let var_err = b64_abs(combined_variance - 385.0)
    let t1 = var_err < 0.01
    if t1 { println("  PASS T1: 10-entry budget computes correctly") } else { println("  FAIL T1") }
    if t1 { n_pass = n_pass + 1 }

    // ---- T2: Effective DOF = infinity (all Type B) ----
    let u_c4 = combined_variance * combined_variance
    var denom = 0.0
    i = 0
    while i < entry_count {
        if dofs[i] < 1.0e20 {
            let c4 = contributions[i] * contributions[i]
            denom = denom + c4 / dofs[i]
        }
        i = i + 1
    }
    var effective_dof = 0.0
    if denom > 1.0e-15 { effective_dof = u_c4 / denom } else { effective_dof = 1.0e30 }
    let t2 = effective_dof > 1.0e20
    if t2 { println("  PASS T2: Type B entries -> infinite DOF") } else { println("  FAIL T2") }
    if t2 { n_pass = n_pass + 1 }

    // ---- T3: Dominant source is entry k=10 (idx=9) ----
    // Initialize rank_indices
    i = 0
    while i < entry_count { rank_indices[i] = i; i = i + 1 }
    // Insertion sort descending by contributions
    var ri = 1
    while ri < entry_count {
        let key_idx = rank_indices[ri]
        let key_val = contributions[key_idx]
        var j = ri - 1
        var done = false
        while j >= 0 && !done {
            let rj = rank_indices[j]
            if contributions[rj] < key_val {
                rank_indices[j + 1] = rank_indices[j]
                j = j - 1
            } else { done = true }
        }
        rank_indices[j + 1] = key_idx
        ri = ri + 1
    }
    let dom_idx: i64 = rank_indices[0]  // explicit kind: an inferred let of an indexed expr loses the scalar kind at print dispatch (#2354)
    let dom_pct = 100.0 * contributions[dom_idx] / combined_variance
    println("  T3: Dominant idx="); println(dom_idx); println(" pct="); println(dom_pct)
    // Entry k=10 has index 9, contribution=100, pct = 100/385 ≈ 25.974%
    let t3 = dom_idx == 9 && b64_abs(dom_pct - 25.974) < 1.0
    if t3 { println("  PASS T3: Correctly identified dominant source") } else { println("  FAIL T3") }
    if t3 { n_pass = n_pass + 1 }

    // ---- T4: Percent contributions sum to 100% ----
    var pct_sum = 0.0
    i = 0
    while i < entry_count {
        pct_sum = pct_sum + 100.0 * contributions[i] / combined_variance
        i = i + 1
    }
    println("  T4: Sum of percent contributions: "); println(pct_sum)
    let t4 = b64_abs(pct_sum - 100.0) < 0.1
    if t4 { println("  PASS T4: Contributions sum to 100%") } else { println("  FAIL T4") }
    if t4 { n_pass = n_pass + 1 }

    // ---- T5: Type A entries → finite Welch-Satterthwaite DOF ----
    // Entry 0: std=2, sens=1, n=10  → dof=9,  contrib = 1^2 * 2^2 = 4
    // Entry 1: std=3, sens=1, n=20  → dof=19, contrib = 1^2 * 3^2 = 9
    // total_var = 13, u_c4 = 169
    // denom = 4^2/9 + 9^2/19 = 16/9 + 81/19 ≈ 1.778 + 4.263 = 6.041
    // eff_dof = 169 / 6.041 ≈ 27.97  (should be in 5..100)
    let c0 = 4.0
    let d0 = 9.0
    let c1 = 9.0
    let d1 = 19.0
    let cv2 = c0 + c1
    let uc4_2 = cv2 * cv2
    let denom2 = c0 * c0 / d0 + c1 * c1 / d1
    let eff_dof2 = uc4_2 / denom2
    println("  T5: Effective DOF with Type A: "); println(eff_dof2)
    let t5 = eff_dof2 > 5.0 && eff_dof2 < 100.0
    if t5 { println("  PASS T5: Welch-Satterthwaite DOF computed") } else { println("  FAIL T5") }
    if t5 { n_pass = n_pass + 1 }

    println("")
    println("==============================================================")
    println("  RESULT: "); println(n_pass); println(" / 5 PASS")
    println("==============================================================")
    if n_pass == 5 { 0 } else { 1 }
}

//@ run-pass
//@ requires: madaros
//@ description: Tiny proof-logged at-most-two cardinality encoding gate

fn card_var(slot: i64) -> i64 {
    return slot + 1
}

fn card_valid_slot(n: i64, slot: i64) -> i64 {
    if slot < 0 { return 0 }
    if slot >= n { return 0 }
    return 1
}

fn card_at_most_two_clause_count(n: i64) -> i64 {
    if n < 3 { return 0 }
    return (n * (n - 1) * (n - 2)) / 6
}

fn card_at_most_two_clause_id(n: i64, a: i64, b: i64, c: i64) -> i64 {
    if card_valid_slot(n, a) == 0 { return 0 - 1 }
    if card_valid_slot(n, b) == 0 { return 0 - 1 }
    if card_valid_slot(n, c) == 0 { return 0 - 1 }
    if a == b { return 0 - 1 }
    if a == c { return 0 - 1 }
    if b == c { return 0 - 1 }

    var id: i64 = 1
    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            var k: i64 = j + 1
            while k < n {
                var hit: i64 = 0
                if i == a {
                    if j == b {
                        if k == c { hit = 1 }
                    }
                    if j == c {
                        if k == b { hit = 1 }
                    }
                }
                if i == b {
                    if j == a {
                        if k == c { hit = 1 }
                    }
                    if j == c {
                        if k == a { hit = 1 }
                    }
                }
                if i == c {
                    if j == a {
                        if k == b { hit = 1 }
                    }
                    if j == b {
                        if k == a { hit = 1 }
                    }
                }
                if hit == 1 { return id }
                id = id + 1
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return 0 - 1
}

fn card_at_most_two_clause_len(n: i64, clause_id: i64) -> i64 {
    if clause_id < 1 { return 0 }
    if clause_id <= card_at_most_two_clause_count(n) { return 3 }
    return 0
}

fn card_at_most_two_lit(n: i64, clause_id: i64, pos: i64) -> i64 {
    if pos < 0 { return 0 }
    if pos >= 3 { return 0 }
    if card_at_most_two_clause_len(n, clause_id) != 3 { return 0 }

    var id: i64 = 1
    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            var k: i64 = j + 1
            while k < n {
                if id == clause_id {
                    if pos == 0 { return 0 - card_var(i) }
                    if pos == 1 { return 0 - card_var(j) }
                    return 0 - card_var(k)
                }
                id = id + 1
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return 0
}

fn card_lit_matches_one3(clause_lit: i64, lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if clause_lit + lit_a == 0 { return 1 }
    if clause_lit + lit_b == 0 { return 1 }
    if clause_lit + lit_c == 0 { return 1 }
    return 0
}

fn card_verify_at_most_two_conflict(n: i64, clause_id: i64, lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if lit_a <= 0 { return 0 }
    if lit_b <= 0 { return 0 }
    if lit_c <= 0 { return 0 }
    if lit_a == lit_b { return 0 }
    if lit_a == lit_c { return 0 }
    if lit_b == lit_c { return 0 }

    let a = lit_a - 1
    let b = lit_b - 1
    let c = lit_c - 1
    if card_valid_slot(n, a) == 0 { return 0 }
    if card_valid_slot(n, b) == 0 { return 0 }
    if card_valid_slot(n, c) == 0 { return 0 }
    if card_at_most_two_clause_id(n, a, b, c) != clause_id { return 0 }

    let c0 = card_at_most_two_lit(n, clause_id, 0)
    let c1 = card_at_most_two_lit(n, clause_id, 1)
    let c2 = card_at_most_two_lit(n, clause_id, 2)
    if card_lit_matches_one3(c0, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(c1, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(c2, lit_a, lit_b, lit_c) == 0 { return 0 }
    return 1
}

fn main() -> i64 {
    if card_at_most_two_clause_count(2) != 0 { return 1 }
    if card_at_most_two_clause_count(3) != 1 { return 2 }
    if card_at_most_two_clause_count(4) != 4 { return 3 }

    if card_at_most_two_clause_id(4, 0, 1, 2) != 1 { return 4 }
    if card_at_most_two_clause_id(4, 0, 1, 3) != 2 { return 5 }
    if card_at_most_two_clause_id(4, 0, 2, 3) != 3 { return 6 }
    if card_at_most_two_clause_id(4, 1, 2, 3) != 4 { return 7 }
    if card_at_most_two_clause_id(4, 3, 1, 2) != 4 { return 8 }
    if card_at_most_two_clause_id(4, 1, 1, 2) != (0 - 1) { return 9 }

    if card_at_most_two_clause_len(4, 4) != 3 { return 10 }
    if card_at_most_two_clause_len(4, 5) != 0 { return 11 }
    if card_at_most_two_lit(4, 4, 0) != (0 - 2) { return 12 }
    if card_at_most_two_lit(4, 4, 1) != (0 - 3) { return 13 }
    if card_at_most_two_lit(4, 4, 2) != (0 - 4) { return 14 }
    if card_at_most_two_lit(4, 4, 3) != 0 { return 15 }

    if card_verify_at_most_two_conflict(4, 4, 2, 3, 4) != 1 { return 16 }
    if card_verify_at_most_two_conflict(4, 4, 4, 2, 3) != 1 { return 17 }
    if card_verify_at_most_two_conflict(4, 3, 2, 3, 4) != 0 { return 18 }
    if card_verify_at_most_two_conflict(4, 4, 2, 2, 4) != 0 { return 19 }
    if card_verify_at_most_two_conflict(4, 4, 2, 3, 0 - 4) != 0 { return 20 }
    if card_verify_at_most_two_conflict(4, 4, 2, 3, 5) != 0 { return 21 }

    return 0
}

//@ run-pass
//@ requires: madaros
//@ description: Tiny graph-colouring cardinality proof-log ID/literal smoke

fn card_exactly_one_clause_count(n: i64) -> i64 {
    if n <= 0 { return 0 }
    return 1 + (n * (n - 1)) / 2
}

fn card_var(slot: i64) -> i64 {
    return slot + 1
}

fn card_lit_abs(lit: i64) -> i64 {
    if lit < 0 { return 0 - lit }
    return lit
}

fn card_exactly_one_clause_len(n: i64, clause_id: i64) -> i64 {
    if n <= 0 { return 0 }
    if clause_id == 1 { return n }
    if clause_id >= 2 {
        if clause_id <= card_exactly_one_clause_count(n) { return 2 }
    }
    return 0
}

fn card_exactly_one_lit(n: i64, clause_id: i64, pos: i64) -> i64 {
    if n <= 0 { return 0 }
    if clause_id == 1 {
        if pos < 0 { return 0 }
        if pos >= n { return 0 }
        return card_var(pos)
    }
    if pos < 0 { return 0 }
    if pos >= 2 { return 0 }

    var id: i64 = 2
    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            if id == clause_id {
                if pos == 0 { return 0 - card_var(i) }
                return 0 - card_var(j)
            }
            id = id + 1
            j = j + 1
        }
        i = i + 1
    }
    return 0
}

fn card_colour_var(vertex: i64, colour_count: i64, colour: i64) -> i64 {
    if vertex < 0 { return 0 }
    if colour_count <= 0 { return 0 }
    if colour < 0 { return 0 }
    if colour >= colour_count { return 0 }
    return vertex * colour_count + colour + 1
}

fn card_colour_vertex_clause_count(colour_count: i64) -> i64 {
    return card_exactly_one_clause_count(colour_count)
}

fn card_colour_vertex_clause_id(vertex: i64, colour_count: i64, local_clause_id: i64) -> i64 {
    if vertex < 0 { return 0 - 1 }
    let per_vertex = card_colour_vertex_clause_count(colour_count)
    if per_vertex <= 0 { return 0 - 1 }
    if local_clause_id < 1 { return 0 - 1 }
    if local_clause_id > per_vertex { return 0 - 1 }
    return vertex * per_vertex + local_clause_id
}

fn card_colour_vertex_lit(vertex: i64, colour_count: i64, local_clause_id: i64, pos: i64) -> i64 {
    if vertex < 0 { return 0 }
    let local = card_exactly_one_lit(colour_count, local_clause_id, pos)
    if local == 0 { return 0 }
    let v = card_lit_abs(local)
    if v <= 0 { return 0 }
    let colour = v - 1
    let global = card_colour_var(vertex, colour_count, colour)
    if global == 0 { return 0 }
    if local < 0 { return 0 - global }
    return global
}

fn card_colour_edge_base_id(vertex_count: i64, colour_count: i64) -> i64 {
    if vertex_count < 0 { return 0 - 1 }
    let per_vertex = card_colour_vertex_clause_count(colour_count)
    if per_vertex <= 0 { return 0 - 1 }
    return vertex_count * per_vertex + 1
}

fn card_colour_edge_clause_id(vertex_count: i64, colour_count: i64, edge_index: i64, colour: i64) -> i64 {
    if edge_index < 0 { return 0 - 1 }
    if colour < 0 { return 0 - 1 }
    if colour >= colour_count { return 0 - 1 }
    let base = card_colour_edge_base_id(vertex_count, colour_count)
    if base < 1 { return 0 - 1 }
    return base + edge_index * colour_count + colour
}

fn card_colour_edge_lit(u: i64, v: i64, colour_count: i64, colour: i64, pos: i64) -> i64 {
    if u < 0 { return 0 }
    if v < 0 { return 0 }
    if u == v { return 0 }
    if pos == 0 {
        let vu = card_colour_var(u, colour_count, colour)
        if vu == 0 { return 0 }
        return 0 - vu
    }
    if pos == 1 {
        let vv = card_colour_var(v, colour_count, colour)
        if vv == 0 { return 0 }
        return 0 - vv
    }
    return 0
}

fn card_colour_edge_verify_conflict(u: i64, v: i64, colour_count: i64, colour: i64, lit_u: i64, lit_v: i64) -> i64 {
    if lit_u <= 0 { return 0 }
    if lit_v <= 0 { return 0 }
    let c0 = card_colour_edge_lit(u, v, colour_count, colour, 0)
    let c1 = card_colour_edge_lit(u, v, colour_count, colour, 1)
    if c0 + lit_u == 0 {
        if c1 + lit_v == 0 { return 1 }
    }
    if c0 + lit_v == 0 {
        if c1 + lit_u == 0 { return 1 }
    }
    return 0
}

fn main() -> i64 {
    let k: i64 = 3
    if card_colour_var(0, k, 0) != 1 { return 1 }
    if card_colour_var(0, k, 2) != 3 { return 2 }
    if card_colour_var(1, k, 0) != 4 { return 3 }
    if card_colour_var(1, k, 2) != 6 { return 4 }

    if card_colour_vertex_clause_count(k) != 4 { return 5 }
    if card_colour_vertex_clause_id(0, k, 1) != 1 { return 6 }
    if card_colour_vertex_clause_id(0, k, 4) != 4 { return 7 }
    if card_colour_vertex_clause_id(1, k, 1) != 5 { return 8 }
    if card_colour_vertex_clause_id(1, k, 4) != 8 { return 9 }

    if card_colour_vertex_lit(1, k, 1, 0) != 4 { return 10 }
    if card_colour_vertex_lit(1, k, 1, 2) != 6 { return 11 }
    if card_colour_vertex_lit(1, k, 4, 0) != (0 - 5) { return 12 }
    if card_colour_vertex_lit(1, k, 4, 1) != (0 - 6) { return 13 }

    if card_colour_edge_base_id(2, k) != 9 { return 14 }
    if card_colour_edge_clause_id(2, k, 0, 0) != 9 { return 15 }
    if card_colour_edge_clause_id(2, k, 0, 2) != 11 { return 16 }
    if card_colour_edge_lit(0, 1, k, 2, 0) != (0 - 3) { return 17 }
    if card_colour_edge_lit(0, 1, k, 2, 1) != (0 - 6) { return 18 }

    if card_colour_edge_verify_conflict(0, 1, k, 2, 3, 6) != 1 { return 19 }
    if card_colour_edge_verify_conflict(0, 1, k, 2, 3, 5) != 0 { return 20 }
    if card_colour_edge_verify_conflict(0, 0, k, 2, 3, 3) != 0 { return 21 }
    if card_colour_edge_clause_id(2, k, 0, 3) != (0 - 1) { return 22 }

    return 0
}

//@ run-pass
//@ requires: madaros
//@ description: Scalar graph-colouring LRAT header contract for K3/2-colour certificates

fn card_exactly_one_clause_count(n: i64) -> i64 {
    if n <= 0 { return 0 }
    return 1 + (n * (n - 1)) / 2
}

fn card_colour_vertex_block_count(vertex_count: i64, colour_count: i64) -> i64 {
    if vertex_count < 0 { return 0 - 1 }
    let per_vertex: i64 = card_exactly_one_clause_count(colour_count)
    if per_vertex <= 0 { return 0 - 1 }
    return vertex_count * per_vertex
}

fn card_colour_edge_base_id(vertex_count: i64, colour_count: i64) -> i64 {
    if vertex_count < 0 { return 0 - 1 }
    let per_vertex: i64 = card_exactly_one_clause_count(colour_count)
    if per_vertex <= 0 { return 0 - 1 }
    return vertex_count * per_vertex + 1
}

fn card_colour_edge_clause_count(edge_count: i64, colour_count: i64) -> i64 {
    if edge_count < 0 { return 0 - 1 }
    if colour_count <= 0 { return 0 - 1 }
    return edge_count * colour_count
}

fn card_colour_total_clause_count(vertex_count: i64, edge_count: i64, colour_count: i64) -> i64 {
    let vertex_block: i64 = card_colour_vertex_block_count(vertex_count, colour_count)
    if vertex_block < 0 { return 0 - 1 }
    let edge_block: i64 = card_colour_edge_clause_count(edge_count, colour_count)
    if edge_block < 0 { return 0 - 1 }
    return vertex_block + edge_block
}

fn card_colour_var_count(vertex_count: i64, colour_count: i64) -> i64 {
    if vertex_count < 0 { return 0 - 1 }
    if colour_count <= 0 { return 0 - 1 }
    return vertex_count * colour_count
}

fn card_colour_manifest_mix(acc: i64, value: i64) -> i64 {
    return ((acc * 1315423911) + value + 97) % 1000000007
}

fn card_colour_manifest_fingerprint(vertex_count: i64, edge_count: i64, colour_count: i64) -> i64 {
    let var_count: i64 = card_colour_var_count(vertex_count, colour_count)
    if var_count < 0 { return 0 - 1 }
    let vertex_block: i64 = card_colour_vertex_block_count(vertex_count, colour_count)
    if vertex_block < 0 { return 0 - 1 }
    let edge_base: i64 = card_colour_edge_base_id(vertex_count, colour_count)
