// MAIN
// ============================================================================

fn main() -> i64 with IO, Mut, Div, Panic {
    println("==============================================================")
    println("  Confidence Gate Tests")
    println("==============================================================")
    var n_pass = 0

    // ---- T1: All inputs meet threshold → PASS ----
    var confs: [f64; 64] = [0.0; 64]
    confs[0] = 0.95; confs[1] = 0.90; confs[2] = 0.88; confs[3] = 0.92
    let t1 = confidence_gate(&confs, 4, 0.85)
    if t1 { println("  PASS T1: Gate passes when all meet threshold") } else { println("  FAIL T1") }
    if t1 { n_pass = n_pass + 1 }

    // ---- T2: One input below threshold → FAIL ----
    confs[4] = 0.70  // Below 0.85
    let t2 = !confidence_gate(&confs, 5, 0.85)
    if t2 { println("  PASS T2: Gate fails when input below threshold") } else { println("  FAIL T2") }
    if t2 { n_pass = n_pass + 1 }

    // ---- T3: CV% gate catches high-uncertainty parameters ----
    // policy_cv: min_confidence=0.0, max_cv_percent=30.0
    // Check 0: value=100, std=10 → CV=10% (PASS)
    // Check 1: value=10, std=5 → CV=50% (FAIL, violation)
    var t3_n_violations: i64 = 0
    var t3_passed = true
    var t3_violation_idx: i64 = -1
    // Check 0: cv=10 < 30 → no violation
    let cv0 = 100.0 * 10.0 / cg_abs(100.0)  // = 10.0
    if cv0 > 30.0 { t3_n_violations = t3_n_violations + 1; t3_passed = false; t3_violation_idx = 0 }
    // Check 1: cv=50 > 30 → violation, param_idx=1
    let cv1 = 100.0 * 5.0 / cg_abs(10.0)  // = 50.0
    if cv1 > 30.0 { t3_n_violations = t3_n_violations + 1; t3_passed = false; t3_violation_idx = 1 }
    let t3 = !t3_passed && t3_n_violations == 1 && t3_violation_idx == 1
    if t3 { println("  PASS T3: CV% gate catches high-uncertainty param") } else { println("  FAIL T3") }
    if t3 { n_pass = n_pass + 1 }

    // ---- T4: Clinical policy (confidence + CV%) ----
    // policy_clin: min_confidence=0.90, max_cv_percent=40.0
    // Check 0: conf=0.95, CV=20% → no violations
    // Check 1: conf=0.80, CV=10% → confidence violation
    // Check 2: conf=0.95, CV=60% → CV violation
    var t4_n_violations: i64 = 0
    var t4_passed = true
    var t4_worst_conf = 1.0
    var t4_worst_idx: i64 = -1
    // Check 0
    let c0 = 0.95; let v0 = 50.0; let s0 = 10.0
    if c0 < t4_worst_conf { t4_worst_conf = c0; t4_worst_idx = 0 }
    if c0 < 0.90 { t4_n_violations = t4_n_violations + 1; t4_passed = false }
    let cv_0 = 100.0 * s0 / cg_abs(v0)
    if cv_0 > 40.0 { t4_n_violations = t4_n_violations + 1; t4_passed = false }
    // Check 1
    let c1 = 0.80; let v1 = 50.0; let s1 = 5.0
    if c1 < t4_worst_conf { t4_worst_conf = c1; t4_worst_idx = 1 }
    if c1 < 0.90 { t4_n_violations = t4_n_violations + 1; t4_passed = false }
    let cv_1 = 100.0 * s1 / cg_abs(v1)
    if cv_1 > 40.0 { t4_n_violations = t4_n_violations + 1; t4_passed = false }
    // Check 2
    let c2 = 0.95; let v2 = 10.0; let s2 = 6.0
    if c2 < t4_worst_conf { t4_worst_conf = c2; t4_worst_idx = 2 }
    if c2 < 0.90 { t4_n_violations = t4_n_violations + 1; t4_passed = false }
    let cv_2 = 100.0 * s2 / cg_abs(v2)
    if cv_2 > 40.0 { t4_n_violations = t4_n_violations + 1; t4_passed = false }
    let t4 = !t4_passed && t4_n_violations == 2
    if t4 { println("  PASS T4: Clinical policy enforces both criteria") } else { println("  FAIL T4") }
    if t4 { n_pass = n_pass + 1 }

    // ---- T5: Worst offender identification ----
    let t5 = t4_worst_conf < 0.81 && t4_worst_idx == 1
    println("  Worst confidence: "); println(t4_worst_conf); println(" at idx "); println(t4_worst_idx)
    if t5 { println("  PASS T5: Correctly identifies worst offender") } else { println("  FAIL T5") }
    if t5 { n_pass = n_pass + 1 }

    println("")
    println("==============================================================")
    println("  RESULT: "); println(n_pass); println(" / 5 PASS")
    println("==============================================================")
    if n_pass == 5 { 0 } else { 1 }
}

//@ run-pass
// Test: Box-Constrained Optimization
//
// T1: Unconstrained quadratic converges to (3,5)
// T2: Bounded optimization enforces lower bound
// T3: Positive-constrained optimization converges to origin
// T4: All solutions remain feasible (within bounds)
//
// Rewritten to avoid fn-reference parameters (unsupported in lean_single).
// Uses obj_id dispatch (0=quadratic, 1=sum_squares) instead.
// Uses global output arrays to avoid struct-with-array-field SRET issues.

fn co_abs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }
fn co_max(a: f64, b: f64) -> f64 { if a > b { a } else { b } }
fn co_sqrt(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

// ============================================================================
// Objective functions (obj_id: 0=quadratic, 1=sum_squares)
// ============================================================================

// Quadratic with minimum at (3, 5): f(x,y) = (x-3)² + (y-5)²
fn quadratic(x: &[f64; 64], n: i64) -> f64 {
    let a = x[0] - 3.0
    let b = x[1] - 5.0
    a * a + b * b
}

// Sum of squares: f(x) = sum(x_i²) — minimum at origin
fn sum_squares(x: &[f64; 64], n: i64) -> f64 with Mut {
    var s = 0.0
    var i: i64 = 0
    while i < n { s = s + x[i] * x[i]; i = i + 1 }
    s
}

fn eval_obj(obj_id: i64, x: &[f64; 64], n: i64) -> f64 with Mut {
    if obj_id == 0 { return quadratic(x, n) }
    return sum_squares(x, n)
}

// ============================================================================
// Global result storage (avoids struct-with-array SRET issues)
// ============================================================================

var G_PARAMS: [f64; 192] = [0.0; 192]  // 3 results * 64 params each
var G_VALUE:  [f64; 3]   = [0.0; 3]
var G_ITERS:  [i64; 3]   = [0; 3]
var G_CONV:   [i64; 3]   = [0; 3]

fn box_project(x: &![f64; 64], n: i64, lo: f64, hi: f64) with Mut {
    var i: i64 = 0
    while i < n {
        if x[i] < lo { x[i] = lo }
        if x[i] > hi { x[i] = hi }
        i = i + 1
    }
}

// Writes result into G_PARAMS[slot*64..], G_VALUE[slot], G_ITERS[slot], G_CONV[slot]
fn minimize_box(slot: i64, obj_id: i64, x0: &[f64; 64], n: i64, lo: f64, hi: f64,
                max_iter: i64, step_size: f64) with Mut, Div {
    var x:     [f64; 64] = [0.0; 64]
    var grad:  [f64; 64] = [0.0; 64]
    var x_pert:[f64; 64] = [0.0; 64]
    var x_trial:[f64;64] = [0.0; 64]

    var i: i64 = 0
    while i < n { x[i] = x0[i]; i = i + 1 }
    box_project(&!x, n, lo, hi)
    var f_val = eval_obj(obj_id, &x, n)
    var func_evals: i64 = 1
    var converged: i64 = 0

    var iter: i64 = 0
    while iter < max_iter {
        // Copy x into x_pert
        i = 0
        while i < n { x_pert[i] = x[i]; i = i + 1 }

        // Compute gradient via finite differences
        i = 0
        while i < n {
            let h = co_max(1.0e-7 * co_abs(x[i]), 1.0e-7)
            x_pert[i] = x[i] + h
            let fp = eval_obj(obj_id, &x_pert, n)
            x_pert[i] = x[i] - h
            let fm = eval_obj(obj_id, &x_pert, n)
            x_pert[i] = x[i]
            grad[i] = (fp - fm) / (2.0 * h)
            func_evals = func_evals + 2
            i = i + 1
        }

        // Projected gradient norm
        var grad_norm_sq = 0.0
        i = 0
        while i < n {
            var gi = grad[i]
            if x[i] <= lo + 1.0e-10 && gi > 0.0 { gi = 0.0 }
            if x[i] >= hi - 1.0e-10 && gi < 0.0 { gi = 0.0 }
            grad_norm_sq = grad_norm_sq + gi * gi
            i = i + 1
        }
        if co_sqrt(grad_norm_sq) < 1.0e-5 { converged = 1; break }

        // Backtracking line search with projection
        var alpha = step_size
        var ls: i64 = 0
        var stepped: i64 = 0
        while ls < 30 && stepped == 0 {
            i = 0
            while i < n { x_trial[i] = x[i] - alpha * grad[i]; i = i + 1 }
            box_project(&!x_trial, n, lo, hi)
            let ft = eval_obj(obj_id, &x_trial, n)
            func_evals = func_evals + 1
            if ft < f_val - 1.0e-4 * alpha * grad_norm_sq {
                i = 0
                while i < n { x[i] = x_trial[i]; i = i + 1 }
                f_val = ft
                stepped = 1
            } else {
                alpha = alpha * 0.5
            }
            ls = ls + 1
        }
        if stepped == 0 { break }
        iter = iter + 1
    }

    // Write results to globals
    let base = slot * 64
    i = 0
    while i < 64 { G_PARAMS[base + i] = x[i]; i = i + 1 }
    G_VALUE[slot] = f_val
    G_ITERS[slot] = iter
    G_CONV[slot] = converged
}

// ============================================================================
// MAIN
// ============================================================================

fn main() -> i64 with IO, Mut, Div, Panic {
    var n_pass: i64 = 0
    var x0: [f64; 64] = [0.0; 64]

    // ---- T1: Unconstrained quadratic, minimum at (3,5) ----
    minimize_box(0, 0, &x0, 2, 0.0 - 1.0e30, 1.0e30, 30, 0.5)
    let r1x = G_PARAMS[0]
    let r1y = G_PARAMS[1]
    let t1 = co_abs(r1x - 3.0) < 0.1 && co_abs(r1y - 5.0) < 0.1
    if t1 { n_pass = n_pass + 1 }

    // ---- T2: Lower-bound constraint: min x²+y² with x,y>=3 → (3,3) ----
    x0[0] = 0.0; x0[1] = 0.0
    minimize_box(1, 1, &x0, 2, 3.0, 1.0e30, 30, 0.5)
    let r2x = G_PARAMS[64]
    let r2y = G_PARAMS[65]
    let t2 = co_abs(r2x - 3.0) < 0.5 && co_abs(r2y - 3.0) < 0.5
    if t2 { n_pass = n_pass + 1 }

    // ---- T3: Positive constraint: min sum(xi²) with xi>=0 → origin ----
    x0[0] = 5.0; x0[1] = 5.0; x0[2] = 5.0
    minimize_box(2, 1, &x0, 3, 0.0, 1.0e30, 30, 0.5)
    let r3x = G_PARAMS[128]
    let r3y = G_PARAMS[129]
    let r3z = G_PARAMS[130]
    let t3 = co_abs(r3x) < 0.1 && co_abs(r3y) < 0.1 && co_abs(r3z) < 0.1
    if t3 { n_pass = n_pass + 1 }

    // ---- T4: All solutions within bounds ----
    let t4 = r2x >= 2.5 && r2y >= 2.5
          && r3x >= 0.0 - 0.01 && r3y >= 0.0 - 0.01 && r3z >= 0.0 - 0.01
    if t4 { n_pass = n_pass + 1 }

    if n_pass == 4 { return 0 } else { return 1 }
}

//@ run-pass
//@ expect-stdout: CONTEXTUAL_KEYWORD_IDENTS_OK
// Regression (#1454, #1194): item-introducer keywords must still be usable as
// ordinary identifiers in expression and pattern position.
//
// `expect_ident` already tolerated keywords, so a parameter DECLARATION like
// `fn f(policy: P)` parsed. Every later USE failed, because the expression
// parser and the pattern parser each carried their own ad-hoc allow-list of
// "keywords usable as identifiers" and neither included this family.
//
// Three positions are exercised for each name: binding (`let policy = ...`),
// bare expression use, and field access on a parameter.

struct Cfg {
    x: i64,
}

fn take_policy(policy: Cfg) -> i64 {
    // expression position: field access on a keyword-named parameter
    policy.x
}

// `policy` is the one member of the family that also appears in
// `at_item_start` (parser.sio), so pin that a bare use as the FIRST statement
// of a block is still parsed as an expression, not as an attempted item.
fn echo_policy(policy: i64) -> i64 {
    policy
}

fn main() -> i32 with IO, Mut, Div, Panic {
    // binding position (pattern parser)
    let policy = 1
    let acquisition_policy = 2
    let recourse_policy = 3
    let transition_policy = 4
    let transition_protocol = 5
    let monitoring_policy = 6
    let alternative_policy = 7
    let alternative_frontier = 8
    let decision_policy = 9
    let deferral_policy = 10
    let models = 11
    let validation = 12

    // `contest` and `audit` are intentionally absent: `contest` has a real
    // expression form (`contest { ... }`) and `audit` is an infix operator
    // (`expr audit name`). Both stay hard keywords — see tk_is_contextual_ident.

    // bare expression position
    let part1 = policy + acquisition_policy + recourse_policy + transition_policy
    let part2 = transition_protocol + monitoring_policy + alternative_policy
    let part3 = alternative_frontier + decision_policy + deferral_policy
    let part4 = models + validation
    let total = part1 + part2 + part3 + part4
    if total != 78 {
        println("FAIL: contextual keyword expression use")
        return 1
    }

    if echo_policy(policy) != 1 {
        println("FAIL: policy as first statement of a block")
        return 3
    }

    let cfg = Cfg { x: 42 }
    if take_policy(cfg) != 42 {
        println("FAIL: keyword-named parameter field access")
        return 2
    }

    println("CONTEXTUAL_KEYWORD_IDENTS_OK")
    return 0
}

//@ run-pass
//@ expect-stdout: ALL PASS
//
// L0 acceptance for correlated equality (stdlib/epistemic/correlation.sio):
// eq_prob_correlated computes P(|a−b|<ε) with FULL shared-source covariance,
// so provenance-sharing operands cancel — a==a yields P=1 exactly (the identity
// solution), deterministic offsets resolve as booleans, and partial correlation
// is honored (independence assumption would be off by 41.5% relative on T5).
// All expected values triple-verified (python math.erf, 10⁷ Monte Carlo, and a
// compiled self-contained build).

use epistemic::correlation::{CorrelatedValue, correlated_from_source, correlated_independent, covariance, eq_prob_correlated, add_correlated, sub_correlated, scale_correlated}

fn approx(x: f64, y: f64) -> bool {
    let d = if x > y { x - y } else { y - x }
    d < 0.0001
}

fn main() with Mut, Div, Panic {
    var ok = true
    let x = correlated_from_source(10.0, 1, 2.0, 0.9)     // measurement, VarID 1, sd 2
    let x2 = correlated_from_source(10.0, 2, 2.0, 0.9)    // independent twin, VarID 2

    // T1 — IDENTITY: same provenance → Var(a−b)=0 → P=1 exactly. a==a solved.
    if approx(eq_prob_correlated(x, x, 0.5), 1.0) { print("T1 identity a==a -> 1: PASS") }
    else { print("T1: FAIL"); ok = false }

    // T2 — independent twins: no shared sources → V=8 → fresh-draw answer
    if approx(eq_prob_correlated(x, x2, 0.5), 0.1403162) { print("T2 indep twins -> 0.1403: PASS") }
    else { print("T2: FAIL"); ok = false }

    // T3 — deterministic offset: same VarID, mean+1 → V=0, boolean at any eps.
    // Construct a fresh value (do not `var y = x; y.value = …`): Madaros
    // multimodule currently aliases large struct copies, so field mutation on
    // the copy would corrupt `x` and poison T4/T5.
    let y = correlated_from_source(11.0, 1, 2.0, 0.9)
    if approx(eq_prob_correlated(x, y, 0.5), 0.0) { print("T3 offset eps=0.5 -> 0: PASS") }
    else { print("T3a: FAIL"); ok = false }
    if approx(eq_prob_correlated(x, y, 2.0), 1.0) { print("T3 offset eps=2 -> 1: PASS") }
    else { print("T3b: FAIL"); ok = false }

    // T4 — certain vs measured (anti-footgun trio member)
    let c = correlated_independent(10.0, 0.0, 1.0)
    if approx(eq_prob_correlated(c, x, 0.5), 0.1974127) { print("T4 certain vs measured -> 0.1974: PASS") }
    else { print("T4: FAIL"); ok = false }

    // T5 — partial correlation: y2 = 0.5·x + w (VarID 3), cov(x,y2)=2, V=2
    // y2 = 0.5·x + w built via the OPS — exercises combine_correlated's source
    // merging (the right operand's source must survive into the result).
    let w = correlated_from_source(5.0, 3, 1.0, 0.9)
    let y2 = add_correlated(scale_correlated(x, 0.5), w)
    if y2.source_count == 2 { print("T5 ops-built y2 has both sources: PASS") }
    else { print("T5src: FAIL"); ok = false }
    if approx(covariance(x, y2), 2.0) { print("T5 cov(x,y2)=2: PASS") }
    else { print("T5cov: FAIL"); ok = false }
    if approx(covariance(y2, w), 1.0) { print("T5 cov(y2,w)=1 (right operand tracked): PASS") }
    else { print("T5covw: FAIL"); ok = false }
    if approx(eq_prob_correlated(x, y2, 0.5), 0.2763264) { print("T5 partial-corr -> 0.2763: PASS") }
    else { print("T5: FAIL"); ok = false }

    // T5b — sub cancellation bookkeeping: shared-source difference keeps ZERO
    // sources, so downstream covariance through it is honestly zero.
    let a1 = correlated_from_source(15.0, 100, 1.0, 0.9)
    let b1 = correlated_from_source(10.0, 100, 1.0, 0.9)
    let dd = sub_correlated(a1, b1)
    if dd.source_count == 0 { print("T5b sub-cancel sources=0: PASS") }
    else { print("T5b src: FAIL"); ok = false }
    if approx(covariance(dd, correlated_from_source(7.0, 100, 1.0, 0.9)), 0.0) { print("T5b cov(d,ref)=0: PASS") }
    else { print("T5b cov: FAIL"); ok = false }

    // T6 — residual-independent self: correlated_independent is fresh-draw BY
    // DEFINITION (uncertainty in residual, no VarID) → V=2u², NOT identity.
    let r = correlated_independent(10.0, 2.0, 0.9)
    if approx(eq_prob_correlated(r, r, 0.5), 0.1403162) { print("T6 independent self = fresh-draw 0.1403: PASS") }
    else { print("T6: FAIL"); ok = false }

    if ok { print("ALL PASS") } else { print("SOME FAIL") }
}

