    var u1: [f64; 8] = [0.0; 8]
    var u2: [f64; 8] = [0.0; 8]
    var u3: [f64; 8] = [0.0; 8]
    var u4: [f64; 8] = [0.0; 8]
    traj_turn_oct(&tb, 0, &!u1)
    traj_turn_oct(&tb, 1, &!u2)
    traj_turn_oct(&tb, 2, &!u3)
    traj_turn_oct(&tb, 3, &!u4)
    var t12: [f64; 8] = [0.0; 8]
    var t123: [f64; 8] = [0.0; 8]
    var nested: [f64; 8] = [0.0; 8]
    oct_mul(&u1, &u2, &!t12)
    oct_mul(&t12, &u3, &!t123)
    oct_mul(&t123, &u4, &!nested)
    var same: bool = true
    var k2: i64 = 0
    while k2 < 8 {
