    v_gut: f64,
    v_kidney: f64,
    v_lung: f64,
    v_heart: f64,
    v_brain: f64,
    v_muscle: f64,
    v_skin: f64,
    v_fat: f64,
    v_spleen: f64,
    v_bone: f64,
