        print_int(tag)
        print(" old=")
        print_int(old_id)
        print(" expected=")
        print_int(expected)
        print("\n")
        return 1
    }
    if new_id != expected {
        print("ENUM_MISMATCH tag=")
        print_int(tag)
        print(" new=")
        print_int(new_id)
        print(" expected=")
        print_int(expected)
        print("\n")
        return 1
    }
    if old_id != new_id {
        print("OLD_NE_NEW tag=")
        print_int(tag)
        print(" old=")
        print_int(old_id)
        print(" new=")
        print_int(new_id)
        print("\n")
        return 1
    }
    0
}

