//@ run-pass
//@ description: R7 fusion — mixed origins become 0; (a+b)+a does not see shared a.

use eisa::core::*

fn main() -> i32 with IO, Mut, Div, Panic {
    if eisa_fuse_origin(1, 1) != 1 {
        println("EISA_ORIGIN_FUSION FAIL 1,1")
        return 1
    }
    if eisa_fuse_origin(1, 2) != 0 {
        println("EISA_ORIGIN_FUSION FAIL 1,2")
        return 1
    }
    if eisa_fuse_origin(0, 1) != 0 {
        println("EISA_ORIGIN_FUSION FAIL 0,1")
        return 1
    }
    if eisa_fuse_origin(1, 0) != 0 {
        println("EISA_ORIGIN_FUSION FAIL 1,0")
        return 1
    }
    if eisa_fuse_origin(0, 0) != 0 {
        println("EISA_ORIGIN_FUSION FAIL 0,0")
        return 1
    }
    if eisa_origins_correlated(0, 0) != 0 {
        println("EISA_ORIGIN_FUSION FAIL 0,0 must not fire")
        return 1
    }

    let a = ereg_origin(1.0, 3.0, 1)
    let b = ereg_origin(2.0, 4.0, 2)
    let ab = eadd(a, b)
    if ab.origin != 0 {
        println("EISA_ORIGIN_FUSION FAIL a+b origin")
        return 1
    }
    let aba = eadd(ab, a)
    if aba.origin != 0 {
        println("EISA_ORIGIN_FUSION FAIL (a+b)+a origin")
        return 1
    }
    // Silent miss: (a+b)+a does not fire, so u is RSS of {5-ish, 3}, not 2*3.
    // Do not require a tight u here — the origin sentinel is the contract.
    if eisa_origins_correlated(ab.origin, a.origin) != 0 {
        println("EISA_ORIGIN_FUSION FAIL (a+b)+a fired")
        return 1
    }

    // Constants cannot correlate.
    let c = ereg_exact(2.0)
    if c.origin != 0 {
        println("EISA_ORIGIN_FUSION FAIL exact origin")
        return 1
    }
    let cx = eadd(c, a)
    if cx.origin != 0 {
        println("EISA_ORIGIN_FUSION FAIL exact+measured origin")
        return 1
    }

    // Negative id is not legitimate — stored as 0.
    let bad = ereg_origin(1.0, 1.0, 0 - 1)
    if bad.origin != 0 {
        println("EISA_ORIGIN_FUSION FAIL negative id stored")
        return 1
    }

    println("EISA_ORIGIN_FUSION OK")
    0
}

//@ run-pass
//@ description: R7 negative control — distinct origins must NOT fire. 3-4-5 RSS.
//
// Oracle (integers only, no floating point):
//   ua = 3, ub = 4, origin 1 != origin 2
//   => do not fire
//   => origin' = 0
//   => u'^2 = ua*ua + ub*ub = 9+16 = 25
//   => u' = 5  (3-4-5 triple; the integer identity is on the square)
// If this test starts accepting u'=7, the detector is signalling everything
// and must not ship.

use eisa::core::*

fn main() -> i32 with IO, Mut, Div, Panic {
    let ua: i64 = 3
    let ub: i64 = 4
    let expected_u2: i64 = ua * ua + ub * ub

    let a = ereg_origin(1.0, 3.0, 1)
    let b = ereg_origin(2.0, 4.0, 2)
    let z = eadd(a, b)

    if z.origin != 0 {
        println("EISA_ORIGIN_INDEP_ADD FAIL origin not 0")
        return 1
    }
    if expected_u2 != 25 {
        println("EISA_ORIGIN_INDEP_ADD FAIL integer oracle 3^2+4^2")
        return 1
    }
    // Runtime lands on the integer 5 of the 3-4-5 triple. Window matches W2.
    if !(z.u > 4.999999999 && z.u < 5.000000001) {
        println("EISA_ORIGIN_INDEP_ADD FAIL u not 5")
        print("u=")
        print_f64(z.u)
        println("")
        return 1
    }
    // Mandatory: must NOT be the correlated envelope 3+4=7.
    if z.u > 6.9 {
        println("EISA_ORIGIN_INDEP_ADD FAIL false fire (u~7)")
        return 1
    }
    println("EISA_ORIGIN_INDEP_ADD OK u=5 origin=0 no-fire")
    0
}

//@ run-pass
// Smoke test: measured/asserted edge coefficients → E-KAN → output conf ≤ 0.965

fn sqrt_t(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x; var i = 0
    while i < 10 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}
fn abs_t(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }

fn hat(x: f64, k: i64) -> f64 with Mut, Div, Panic {
    let c = (k as f64) * 0.25
    let d = abs_t(x - c) / 0.25
    if d >= 1.0 { return 0.0 }
    1.0 - d
}

struct Ev { val: f64, unc: f64, conf: f64 }
fn edge_eval(coeffs: &[f64; 5], unc: &[f64; 5], e_conf: f64, x: f64) -> Ev with Mut, Div, Panic {
    var val = 0.0; var vs = 0.0; var k = 0
    while k < 5 {
        let b = hat(x, k)
        val = val + coeffs[k as usize] * b
        vs  = vs  + b*b * unc[k as usize]*unc[k as usize]
        k = k + 1
    }
    Ev { val: val, unc: sqrt_t(vs), conf: e_conf }
}

fn main() -> i32 with IO, Mut, Div, Panic {
    // Single edge: asserted (conf=0.965)
    let c: [f64; 5] = [0.1, 0.5, 0.0 - 0.3, 0.8, 0.2]
    let u: [f64; 5] = [0.01, 0.02, 0.01, 0.03, 0.01]
    let ev_meas   = edge_eval(&c, &u, 0.985, 0.5)  // measured
    let ev_assert = edge_eval(&c, &u, 0.965, 0.5)  // asserted

    // Min-propagation: output conf = min(measured, asserted) = 0.965
    var min_c = ev_meas.conf
    if ev_assert.conf < min_c { min_c = ev_assert.conf }

    if ev_meas.unc > 0.0 && abs_t(min_c - 0.965) < 0.001 {
        println("ekan_knowledge_basic: PASS")
        return 0
    }
    println("ekan_knowledge_basic: FAIL")
    return 1
}

