fn print_drug_summary(name_tag: i64, d: EpDrug) -> i64 with IO, Mut {
    if name_tag == 0 {
        print("  Rapamycin  5mg IV   ")
    }
    if name_tag == 1 {
        print("  Caffeine   200mg PO ")
    }
    if name_tag == 2 {
        print("  Metformin  500mg PO ")
    }
    print_f64_3(d.cmax)
    print("     ")
