    var sum_inclusive = 0
    for i in 0..=5 {
        sum_inclusive = sum_inclusive + i
    }
    // sum_inclusive = 0 + 1 + 2 + 3 + 4 + 5 = 15

    // 3. Array iteration: for item in array
    let arr = [10, 20, 30]
    var arr_sum = 0
    for x in arr {
        arr_sum = arr_sum + x
    }
    // arr_sum = 60

    // 4. Vec iteration: for item in vec
    let vec = [1, 2, 3, 4]
    var vec_sum = 0
    for v in vec {
        vec_sum = vec_sum + v
    }
    // vec_sum = 10

    // 5. Nested for loops
    var matrix_sum = 0
    for i in 0..3 {
        for j in 0..3 {
            matrix_sum = matrix_sum + i * 3 + j
        }
    }
    // matrix_sum = sum of 0..9 = 36

    // 6. Range with variables
    let n = 5
    var var_range_sum = 0
    for i in 0..n {
        var_range_sum = var_range_sum + i
    }
