// FRENTE B, vector 4/3 — the Furey Cℓ(6) charge operator, and the decisive state-level test that the
// G₂ automorphism φ is NOT a family symmetry. Executed over Gaussian integers ℤ[i].
//
// The Furey one-generation construction (ℂ⊗𝕆 → Cℓ(6)): left-mult L_a on the octonion (8-dim), ladder
// operators α_i = ½(−L_{a_i} + i L_{b_i}) for pairs (1,2),(3,4),(5,6). Scaling by 2 gives Gaussian-integer
// matrices M_i = 2α_i = −L_{a_i} + i L_{b_i}. This test certifies:
//   (1) the Witt relations {M_i, M_i†} = M_i M_i† + M_i† M_i = 4·I  (the ladder ops are a genuine Cℓ(6));
//   (2) the scaled charge D = 12·Q = Σ_i M_i† M_i is built (Q = ⅓ Σ α_i†α_i);
//   (3) DECISIVE: the G₂ automorphism φ = (e₁e₂e₃)(e₅e₆e₇) [from sedenion_gresnigt_octonions] does NOT
//       commute with D: [P_φ, D] ≠ 0. Since P_φ e_j = e_{g(j)} with g=(1 2 3)(5 6 7), one has
//       (P D)[r][c]=D[g⁻¹(r)][c] and (D P)[r][c]=D[r][g(c)], so a single index comparison witnesses it.
//   (4) the one-generation charge multiplicities (Fock, ×3): 3Q ∈ {0, 1×3, 2×3, 3}.
//
// MEANING (honest boundary). A family symmetry must PRESERVE charge (map generations at equal charge).
// φ does not commute with the charge ⟹ φ does NOT act as a charge-preserving (family) symmetry on the
// fermion states — even though φ permutes the three octonion subalgebras. This rules out THIS φ (a G₂,
// color-side element; see sedenion_gresnigt_octonions.md) as a bridge from the zero-divisor monomial-168
// to fermion generations, now at the STATE level, not just by the G₂/Brown group theory. It does NOT
// rule out every monomial element; the genuine family S₃ (Brown factor, rotational) needs the paper's
// §5 generators — OPEN. Erratum E1 stands.
//
// Decidable Gaussian-integer arithmetic, no float. SELF-CONTAINED. Cross-verified vs the oracle + Lean.

fn cd_sigma_c(a: i64, b: i64, bits: i64) -> i64 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma_c(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma_c(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma_c(a_lo, 0, bits - 1) }
        return 0 - cd_sigma_c(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma_c(0, a_lo, bits - 1) }
    cd_sigma_c(b_lo, a_lo, bits - 1)
}
fn og(a: i64, c: i64) -> i64 with Mut, Panic, Div { cd_sigma_c(a, c, 3) }

fn main() with IO, Mut, Panic, Div {
    // ladder pair directions a_i, b_i for i=0,1,2
    var pa = [1, 3, 5]
    var pb = [2, 4, 6]

    // accumulators: D = sum_i M_i† M_i  ; and Witt check sum_i (M_i M_i† + M_i† M_i) == 4I per i.
    var Dre = [0; 64]
    var Dim = [0; 64]
    var witt_ok = 1

    var i = 0
    while i < 3 {
        let a = pa[i as usize]
        let b = pb[i as usize]
        // M = 2α_i : Mre = -L_a (real), Mim = L_b (real).  L_x[r][c] = og(x,c) if r==x^c else 0.
        var Mre = [0; 64]
        var Mim = [0; 64]
        var r = 0
        while r < 8 {
            var c = 0
            while c < 8 {
                if r == (a ^ c) { Mre[(r * 8 + c) as usize] = 0 - og(a, c) }
                if r == (b ^ c) { Mim[(r * 8 + c) as usize] = og(b, c) }
                c = c + 1
            }
            r = r + 1
        }
        // Mdag[r][c] = conj(M[c][r]) = (Mre[c][r], -Mim[c][r])
        // P1 = M† M  ;  P2 = M M†   (complex 8x8)
        var P1re = [0; 64]
        var P1im = [0; 64]
        var P2re = [0; 64]
        var P2im = [0; 64]
        r = 0
        while r < 8 {
            var c = 0
            while c < 8 {
                var s1re = 0
                var s1im = 0
                var s2re = 0
                var s2im = 0
                var t = 0
                while t < 8 {
                    // M†[r][t] = (Mre[t*8+r], -Mim[t*8+r]) ; M[t][c] = (Mre[t*8+c], Mim[t*8+c])
                    let dr = Mre[(t * 8 + r) as usize]
                    let di = 0 - Mim[(t * 8 + r) as usize]
                    let mr = Mre[(t * 8 + c) as usize]
                    let mi = Mim[(t * 8 + c) as usize]
                    s1re = s1re + dr * mr - di * mi
                    s1im = s1im + dr * mi + di * mr
                    // M[r][t] = (Mre[r*8+t], Mim[r*8+t]) ; M†[t][c] = (Mre[c*8+t], -Mim[c*8+t])
                    let ar = Mre[(r * 8 + t) as usize]
                    let ai = Mim[(r * 8 + t) as usize]
                    let br = Mre[(c * 8 + t) as usize]
                    let bi = 0 - Mim[(c * 8 + t) as usize]
                    s2re = s2re + ar * br - ai * bi
                    s2im = s2im + ar * bi + ai * br
                    t = t + 1
                }
                // D += M† M
                Dre[(r * 8 + c) as usize] = Dre[(r * 8 + c) as usize] + s1re
                Dim[(r * 8 + c) as usize] = Dim[(r * 8 + c) as usize] + s1im
                // Witt: (M†M + MM†)[r][c] must be 4 if r==c else 0
                let wre = s1re + s2re
                let wim = s1im + s2im
                let tgt = if r == c { 4 } else { 0 }
                if wre != tgt { witt_ok = 0 }
                if wim != 0 { witt_ok = 0 }
                c = c + 1
            }
            r = r + 1
        }
        i = i + 1
    }

    // (3) [P_phi, D] != 0.  g = (1 2 3)(5 6 7), fix 0,4,7? g fixes 0,4; g(7)=5. ginv is the inverse.
    var g = [0, 2, 3, 1, 4, 6, 7, 5]
    var ginv = [0, 3, 1, 2, 4, 7, 5, 6]
    // (PD)[r][c] = D[ginv[r]][c] ; (DP)[r][c] = D[r][g[c]]. Nonzero commutator iff some entry differs.
    var comm_nonzero = 0
    var r2 = 0
    while r2 < 8 {
        var c2 = 0
        while c2 < 8 {
            let pd_re = Dre[(ginv[r2 as usize] * 8 + c2) as usize]
            let pd_im = Dim[(ginv[r2 as usize] * 8 + c2) as usize]
            let dp_re = Dre[(r2 * 8 + g[c2 as usize]) as usize]
            let dp_im = Dim[(r2 * 8 + g[c2 as usize]) as usize]
            if pd_re != dp_re { comm_nonzero = 1 }
            if pd_im != dp_im { comm_nonzero = 1 }
            c2 = c2 + 1
        }
        r2 = r2 + 1
    }

    // (4) charge multiplicities (Fock over 3 modes, times 3): count 3Q in {0,1,2,3}
    var cm = [0; 4]
    var occ = 0
    while occ < 8 {
        let q3 = (occ & 1) + ((occ >> 1) & 1) + ((occ >> 2) & 1)
        cm[q3 as usize] = cm[q3 as usize] + 1
        occ = occ + 1
    }
    var charge_ok = 0
    if cm[0 as usize] == 1 && cm[1 as usize] == 3 && cm[2 as usize] == 3 && cm[3 as usize] == 1 { charge_ok = 1 }

    print("WITT_OK ")
    print_int(witt_ok as i64)
    print("\n")
    print("COMM_NONZERO ")
    print_int(comm_nonzero as i64)
    print("\n")
    print("CHARGE_OK ")
    print_int(charge_ok as i64)
    print("\n")
    // Witt relations hold (genuine Cℓ(6) ladder); phi does NOT preserve the charge ([P,D]!=0) => phi is
    // not a charge-preserving (family) symmetry; one-generation charges {0,±1/3,±2/3,±1}. E1 stands.
    if witt_ok == 1 && comm_nonzero == 1 && charge_ok == 1 {
        println("FUREYCHARGE OK")
    } else {
        println("FUREYCHARGE FAIL")
    }
}

//@ run-pass
//@ expect-stdout: FUREY OK
// FRENTE B, vector 4/3 Part A — Sounio reproduces Furey's octonion -> one Standard-Model generation.
//
// This EXECUTES an established result (C. Furey, "Standard model physics from an algebra?", and the
// Dixon/Furey C(x)O program): the complex octonions C(x)O carry a fermionic ladder algebra of three
// modes whose number operator gives the electric charges of exactly one generation of quarks + leptons,
// with the x3 multiplicities of SU(3) colour. We build it EXACTLY over the Gaussian integers Z[i].
//
// Left-multiplication operators (8x8 integer matrices) over Sounio's octonion convention (cd_sigma at
// bits=3): for the unit e_a, L_a has L_a[a^b][b] = cd_sigma(a,b,3) in column b (e_a * e_b = sign*e_{a^b}).
// Furey's ladder operators are alpha_i = 1/2(-L_{a_i} + i L_{b_i}) for the pairs
//   (a_1,b_1),(a_2,b_2),(a_3,b_3) = (1,2),(3,4),(5,6)   [relative to Sounio's cd_sigma sign convention].
// To stay in exact integers we use A_i = 2*alpha_i, the complex 8x8 matrix with real part -L_{a_i} and
// imaginary part L_{b_i}. A complex matrix is TWO int arrays (Re, Im), 64 entries row-major each.
// Adjoint A^dag = conjugate-transpose = (Re^T, -Im^T). Complex matmul
//   (Xr+iXi)(Yr+iYi) = (XrYr - XiYi) + i(XrYi + XiYr).
//
// CLAIM 1 (the headline, exact over Z[i]): the three A_i close a fermionic ladder algebra —
//   {A_i, A_j}      = 0                (all 9 pairs, both Re and Im zero)
//   {A_i, A_j^dag}  = 4*delta_ij * I   (Re = 4*I if i==j else 0; Im zero)
// (the factor 4 is because A = 2*alpha; alpha itself gives delta_ij). 18 anticommutator relations.
//
// CLAIM 2 (charge spectrum, combinatorial given Claim 1): the fermionic Fock space of the 3 modes has
// occupation-number multiplicities C(3,n) = {0:1, 1:3, 2:3, 3:1}, so the electric charge Q = N/3 takes
// the values {0, 1/3, 2/3, 1} with those multiplicities (the x3 = SU(3) colour triplets). The conjugate
// ideal supplies {0, -1/3, -2/3, -1} -> the full 16-state generation. We emit Q*3 -> multiplicity.
//
// Decidable integer arithmetic, no float. SELF-CONTAINED (cd_sigma copied verbatim; no stdlib import).
// Cross-verified vs scripts/research/furey_octonion_oracle.py by scripts/ci/furey_octonion_gate.sh and
// by formal/lean4/SounioFureyOctonion.lean (native_decide).

fn cd_sigma_c(a: i64, b: i64, bits: i64) -> i64 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma_c(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma_c(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma_c(a_lo, 0, bits - 1) }
        return 0 - cd_sigma_c(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma_c(0, a_lo, bits - 1) }
    cd_sigma_c(b_lo, a_lo, bits - 1)
}

// L_a entry at (row r, col c): e_a * e_c = cd_sigma(a,c,3) * e_{a^c}, so nonzero only when r == a^c.
fn l_entry(a: i64, r: i64, c: i64) -> i64 with Mut, Panic, Div {
    if r == (a ^ c) { return cd_sigma_c(a, c, 3) }
    0
}

// Verify one anticommutator relation for modes i,j in {1,2,3}:
//   dag==0 -> {A_i, A_j}      must be 0 (Re and Im).
//   dag==1 -> {A_i, A_j^dag}  must be 4*delta_ij*I (Re = 4 on diagonal iff i==j; Im 0).
// A_k = 2*alpha_k has real part -L_{a_k}, imaginary part L_{b_k}, with (a_k,b_k)=(2k-1, 2k).
// Returns 1 if the relation holds exactly over Z[i], else 0.
fn check_anti(i: i64, j: i64, dag: i64) -> i64 with Mut, Panic, Div {
    let ai = 2 * i - 1
    let bi = 2 * i
    let aj = 2 * j - 1
    let bj = 2 * j
    var xr = [0; 64]
    var xi = [0; 64]
    var yr = [0; 64]
    var yi = [0; 64]
    var rr = 0
    while rr < 8 {
        var cc = 0
        while cc < 8 {
            // X = A_i
            xr[(rr * 8 + cc) as usize] = 0 - l_entry(ai, rr, cc)
            xi[(rr * 8 + cc) as usize] = l_entry(bi, rr, cc)
            if dag == 0 {
                // Y = A_j
                yr[(rr * 8 + cc) as usize] = 0 - l_entry(aj, rr, cc)
                yi[(rr * 8 + cc) as usize] = l_entry(bj, rr, cc)
            } else {
                // Y = A_j^dag = (Re(A_j)^T, -Im(A_j)^T); Re(A_j)=-L_{aj}, Im(A_j)=L_{bj}.
                yr[(rr * 8 + cc) as usize] = 0 - l_entry(aj, cc, rr)
                yi[(rr * 8 + cc) as usize] = 0 - l_entry(bj, cc, rr)
            }
            cc = cc + 1
        }
        rr = rr + 1
    }
    // anti = X*Y + Y*X, complex; check each entry against the expected value.
    var ok = 1
    var r = 0
    while r < 8 {
        var c = 0
        while c < 8 {
            var pr = 0
            var pi = 0
            var qr = 0
            var qi = 0
            var k = 0
            while k < 8 {
                let xrk = xr[(r * 8 + k) as usize]
                let xik = xi[(r * 8 + k) as usize]
                let yrk = yr[(r * 8 + k) as usize]
                let yik = yi[(r * 8 + k) as usize]
                let xkc = xr[(k * 8 + c) as usize]
                let xikc = xi[(k * 8 + c) as usize]
                let ykc = yr[(k * 8 + c) as usize]
                let yikc = yi[(k * 8 + c) as usize]
                // P = X*Y
                pr = pr + xrk * ykc - xik * yikc
                pi = pi + xrk * yikc + xik * ykc
                // Q = Y*X
                qr = qr + yrk * xkc - yik * xikc
                qi = qi + yrk * xikc + yik * xkc
                k = k + 1
            }
            let a_re = pr + qr
            let a_im = pi + qi
            var e_re = 0
            if dag == 1 && i == j && r == c { e_re = 4 }
            if a_re != e_re { ok = 0 }
            if a_im != 0 { ok = 0 }
            c = c + 1
        }
        r = r + 1
    }
    ok
}

// All 18 relations: for i,j in {1,2,3}, both {A_i,A_j}=0 and {A_i,A_j^dag}=4 delta_ij I.
fn ladder_ok() -> i64 with Mut, Panic, Div {
    var ok = 1
    var i = 1
    while i <= 3 {
        var j = 1
        while j <= 3 {
            if check_anti(i, j, 0) == 0 { ok = 0 }
            if check_anti(i, j, 1) == 0 { ok = 0 }
            j = j + 1
        }
        i = i + 1
    }
    ok
}

// Fock-space occupation multiplicity of n filled modes among 3 = binomial(3, n).
fn binom3(n: i64) -> i64 with Mut, Panic, Div {
    var num = 1
    var den = 1
    var t = 0
    while t < n {
        num = num * (3 - t)
        den = den * (t + 1)
        t = t + 1
    }
    num / den
}

fn main() with IO, Mut, Panic, Div {
    let lad = ladder_ok()
    let m0 = binom3(0)
    let m1 = binom3(1)
    let m2 = binom3(2)
    let m3 = binom3(3)

    // one value per line (single print_int + explicit newline) — portable across souc builds.
    print("LADDER_OK ")
    print_int(lad)
    print("\n")
    // Q*3 -> multiplicity (Q in {0, 1/3, 2/3, 1}; the x3 factors are SU(3) colour).
    print("CHARGE3_0 ")
    print_int(m0)
    print("\n")
    print("CHARGE3_1 ")
    print_int(m1)
    print("\n")
    print("CHARGE3_2 ")
    print_int(m2)
    print("\n")
    print("CHARGE3_3 ")
    print_int(m3)
    print("\n")
    // single load-bearing verdict: ladder closes AND generation multiplicities {1,3,3,1}.
    if lad == 1 && m0 == 1 && m1 == 3 && m2 == 3 && m3 == 1 {
        println("FUREY OK")
    } else {
        println("FUREY FAIL")
    }
}

