            var rb = [0; 16]
            var aa = 0
            while aa < 16 {
                var bb = 0
                while bb < 16 {
                    let c = aa ^ bb
                    let s = sg(aa, bb)
                    // (vja+vjb√3)(vka+vkb√3) = (vja*vka+3vjb*vkb) + (vja*vkb+vjb*vka)√3
