// Test 10: Solve SPD system via Cholesky
fn test_cholesky_solve() -> bool with Mut, Panic, Div {
    // SPD: A = [[4, 2, 0], [2, 5, 1], [0, 1, 3]]
    let A = make_3x3(
        4.0, 2.0, 0.0,
        2.0, 5.0, 1.0,
        0.0, 1.0, 3.0
    )
    let n = 3
    var b = zeros8()
    b[0] = 6.0
    b[1] = 8.0
    b[2] = 4.0

    let ch = cholesky_factorize(A, n)

    var y = zeros8()
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + mat_get(ch.L, n, i, j) * y[j]
            j = j + 1
        }
        y[i] = (b[i] - sum) / mat_get(ch.L, n, i, i)
        i = i + 1
    }

    var x = zeros8()
    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + mat_get(ch.L, n, j, i) * x[j]
            j = j + 1
        }
        x[i] = (y[i] - sum) / mat_get(ch.L, n, i, i)
        i = i - 1
    }

    var err = 0.0
    i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < n {
            sum = sum + mat_get(A, n, i, j) * x[j]
            j = j + 1
        }
        let diff = sum - b[i]
        err = err + diff * diff
        i = i + 1
    }
    err = sqrt_f64(err)

    return err < 1e-10
}

// Test 11: Non-SPD matrix returns success = false
fn test_cholesky_not_spd() -> bool with Mut, Panic, Div {
    // A = [[1, 2], [2, 1]] has eigenvalues 3, -1 (not positive definite)
    let A = make_2x2(1.0, 2.0, 2.0, 1.0)
    let n = 2
    cholesky_factorize_into(&!CH_W, A, n)
    return CH_W.success == false
}

// Test 12: Determinant via Cholesky vs LU
fn test_cholesky_determinant() -> bool with Mut, Panic, Div {
    // SPD: A = [[4, 2, 0], [2, 5, 1], [0, 1, 3]]
    let A = make_3x3(
        4.0, 2.0, 0.0,
        2.0, 5.0, 1.0,
        0.0, 1.0, 3.0
    )
    let n = 3

    let ch = cholesky_factorize(A, n)
    var det_ch = 1.0
    var i = 0
    while i < n {
        let d = mat_get(ch.L, n, i, i)
        det_ch = det_ch * d * d
        i = i + 1
    }

    let lu = lu_factorize(A, n)
    var det_lu = 1.0
    i = 0
    while i < n {
        det_lu = det_lu * mat_get(lu.U, n, i, i)
        i = i + 1
    }
    if LU_SWAP_W % 2 == 1 {
        det_lu = 0.0 - det_lu
    }

    return abs_f64(det_ch - det_lu) < 1e-10
}

// Test 13: LDL of SPD 3x3, verify L*D*L^T = A
fn test_ldl_3x3() -> bool with Mut, Panic, Div {
    // SPD: A = [[4, 2, 0], [2, 5, 1], [0, 1, 3]]
    let A = make_3x3(
        4.0, 2.0, 0.0,
        2.0, 5.0, 1.0,
        0.0, 1.0, 3.0
    )
    let n = 3
    let ldl = ldl_factorize(A, n)

    var sum_sq = 0.0
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            var sum = 0.0
            var k = 0
            while k < n {
                sum = sum + mat_get(ldl.L, n, i, k) * ldl.D[k] * mat_get(ldl.L, n, j, k)
                k = k + 1
            }
            let diff = mat_get(A, n, i, j) - sum
            sum_sq = sum_sq + diff * diff
            j = j + 1
        }
        i = i + 1
    }
    let err = sqrt_f64(sum_sq)
    return err < 1e-10
}

// Test 14: LDL solve matches LU solve
fn test_ldl_solve() -> bool with Mut, Panic, Div {
    let A = make_3x3(
        4.0, 2.0, 0.0,
        2.0, 5.0, 1.0,
        0.0, 1.0, 3.0
    )
    let n = 3
    var b = zeros8()
    b[0] = 1.0
    b[1] = 2.0
    b[2] = 3.0

    let ldl = ldl_factorize(A, n)

    var z = zeros8()
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + mat_get(ldl.L, n, i, j) * z[j]
            j = j + 1
        }
        z[i] = b[i] - sum
        i = i + 1
    }

    var y = zeros8()
    i = 0
    while i < n {
        y[i] = z[i] / ldl.D[i]
        i = i + 1
    }

    var x_ldl = zeros8()
    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + mat_get(ldl.L, n, j, i) * x_ldl[j]
            j = j + 1
        }
        x_ldl[i] = y[i] - sum
        i = i - 1
    }

    let lu = lu_factorize(A, n)

    var pb = zeros8()
    i = 0
    while i < n {
        pb[i] = b[lu.perm[i]]
        i = i + 1
    }

    var ylu = zeros8()
    i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + mat_get(lu.L, n, i, j) * ylu[j]
            j = j + 1
        }
        ylu[i] = pb[i] - sum
        i = i + 1
    }

    var x_lu = zeros8()
    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + mat_get(lu.U, n, i, j) * x_lu[j]
            j = j + 1
        }
        x_lu[i] = (ylu[i] - sum) / mat_get(lu.U, n, i, i)
        i = i - 1
    }

    var err = 0.0
    i = 0
    while i < n {
        let diff = x_ldl[i] - x_lu[i]
        err = err + diff * diff
        i = i + 1
    }
    err = sqrt_f64(err)

    return err < 1e-10
}

