    assign = 0 - 1
    // Negate -x, i.e. assign x=true.
    if assign == (0 - 1) { return 1 }
    return 0
}

fn main() -> i64 {
    if lrat_tiny_active(1, 0) != 1 { return 1 }
    if lrat_tiny_active(2, 0) != 1 { return 2 }
    if lrat_tiny_active(2, 1) != 0 { return 3 }
    if lrat_tiny_active(42, 0) != 0 { return 4 }

    if lrat_tiny_check_empty(1, 2, 2, 0) != 1 { return 5 }
    if lrat_tiny_check_empty(2, 1, 2, 0) != 1 { return 6 }
    if lrat_tiny_check_empty(1, 0, 1, 0) != 0 { return 7 }
    if lrat_tiny_check_empty(42, 0, 1, 0) != 0 { return 8 }
    if lrat_tiny_check_empty(1, 2, 2, 1) != 0 { return 9 }

    if lrat_tiny_check_tautology() != 1 { return 10 }
    return 0
}

//@ run-pass
// Verifies cross-module completion: Mod:: prefix returns non-empty list
//
// Simulates the lsp_completions_from_module bridge table logic inline,
// without importing compiler internals.  Registers test symbols in a
// mod-symbol table and verifies that prefix-matched lookups return the
// correct counts and symbol hashes.

// ---- Module-symbol bridge table ----

struct ModSymEntry {
    mod_hash:  i64,
    sym_hash:  i64,
    kind:      i64,
    detail_id: i64,
}

fn mod_sym_entry_new(mh: i64, sh: i64, k: i64, d: i64) -> ModSymEntry {
    ModSymEntry { mod_hash: mh, sym_hash: sh, kind: k, detail_id: d }
}

// ---- Flat completion result list (avoids nested-struct ABI limitations) ----

struct CompResult {
    sym_hashes:  [i64; 32],
    kinds:       [i64; 32],
    detail_ids:  [i64; 32],
    count:       i64,
}

fn comp_result_new() -> CompResult {
    CompResult {
        sym_hashes:  [0; 32],
        kinds:       [0; 32],
        detail_ids:  [0; 32],
        count:       0,
    }
}

fn comp_result_add(result: &! CompResult, sym: i64, kind: i64, det: i64) with Mut, Panic {
    if result.count < 32 {
        let n = result.count
        result.sym_hashes[n as usize] = sym
        result.kinds[n as usize] = kind
        result.detail_ids[n as usize] = det
        result.count = n + 1
    }
}

// completions_from_module: scan bridge table for entries matching mod_hash.
// prefix_hash == 0 means no filter; otherwise only entries with
// sym_hash == prefix_hash are included.
// Appends matched entries to result in place.
// Returns the number of items added.
fn completions_from_module(
    table: &[ModSymEntry; 16],
    table_count: i64,
    mod_hash: i64,
    prefix_hash: i64,
    result: &! CompResult
) -> i64 with Mut, Div, Panic {
    var added: i64 = 0
    var i: i64 = 0
    while i < table_count {
        let e_mod  = table[i as usize].mod_hash
        let e_sym  = table[i as usize].sym_hash
        let e_kind = table[i as usize].kind
        let e_det  = table[i as usize].detail_id
        if e_mod == mod_hash {
            let match_prefix = prefix_hash == 0 || e_sym == prefix_hash
            if match_prefix {
                comp_result_add(result, e_sym, e_kind, e_det)
                added = added + 1
            }
        }
        i = i + 1
    }
    added
}

fn main() -> i32 with IO, Mut, Div, Panic {
    var passed: i32 = 0
    var failed: i32 = 0

    // Build bridge table:
    //   mod=1: sym=10 (fn, kind=3), sym=20 (struct, kind=7), sym=30 (var, kind=6)
    //   mod=2: sym=40 (fn, kind=3), sym=50 (const, kind=21)
    var tbl: [ModSymEntry; 16] = [ModSymEntry { mod_hash: 0, sym_hash: 0, kind: 0, detail_id: 0 }; 16]
    tbl[0] = mod_sym_entry_new(1, 10, 3, 0)
    tbl[1] = mod_sym_entry_new(1, 20, 7, 1)
    tbl[2] = mod_sym_entry_new(1, 30, 6, 0)
    tbl[3] = mod_sym_entry_new(2, 40, 3, 0)
    tbl[4] = mod_sym_entry_new(2, 50, 21, 0)
    let count: i64 = 5

    // T1: mod=1 with no prefix filter → all 3 entries, added count=3
    var res1 = comp_result_new()
    let added1 = completions_from_module(&tbl, count, 1, 0, &! res1)
    if added1 == 3 && res1.count == 3 {
        passed = passed + 1
    } else {
        println("T1 FAIL")
        failed = failed + 1
    }

    // T2: mod=2 with no prefix filter → 2 entries, added count=2
    var res2 = comp_result_new()
    let added2 = completions_from_module(&tbl, count, 2, 0, &! res2)
    if added2 == 2 && res2.count == 2 {
        passed = passed + 1
    } else {
        println("T2 FAIL")
        failed = failed + 1
    }

    // T3: mod=1, prefix=10 → exactly 1 entry with sym_hash=10
    var res3 = comp_result_new()
    let added3 = completions_from_module(&tbl, count, 1, 10, &! res3)
    if added3 == 1 && res3.count == 1 && res3.sym_hashes[0] == 10 {
        passed = passed + 1
    } else {
        println("T3 FAIL")
        failed = failed + 1
    }

    // T4: mod=99 (unknown) → empty, added=0
    var res4 = comp_result_new()
    let added4 = completions_from_module(&tbl, count, 99, 0, &! res4)
    if added4 == 0 && res4.count == 0 {
        passed = passed + 1
    } else {
        println("T4 FAIL")
        failed = failed + 1
    }

    // T5: mod=2, prefix=50 → 1 entry with kind=21 (const)
    var res5 = comp_result_new()
    let added5 = completions_from_module(&tbl, count, 2, 50, &! res5)
    if added5 == 1 && res5.count == 1 && res5.kinds[0] == 21 {
        passed = passed + 1
    } else {
        println("T5 FAIL")
        failed = failed + 1
    }

    // T6: append: start from mod=2 results, then mod=1 results → total 5
    var res6 = comp_result_new()
    let a6a = completions_from_module(&tbl, count, 2, 0, &! res6)
    let a6b = completions_from_module(&tbl, count, 1, 0, &! res6)
    let _ = a6a
    let _ = a6b
    if res6.count == 5 {
        passed = passed + 1
    } else {
        println("T6 FAIL")
        failed = failed + 1
    }

    if failed == 0 { println("lsp_completion_qualified: PASS") }
    else { println("lsp_completion_qualified: FAIL") }
    failed as i32
}

//@ run-pass
// Verifies lsp_hover_qualified: bridge table lookup for qualified names
//
// Simulates the module resolver bridge inline (no imports from compiler
// internals).  Tests that a bridge lookup for a qualified name (mod_hash +
// sym_hash → def_id) produces the correct def_id, and that the hover
// placeholder string is formatted as "(qualified symbol, def_id=N)".

// ---- Minimal bridge table ----

struct QBridgeEntry {
    mod_hash: i64,
    sym_hash: i64,
    def_id:   i64,
}

fn qbridge_lookup(
    table: &[QBridgeEntry; 8],
    count: i64,
    mod_hash: i64,
    sym_hash: i64
) -> i64 with Panic, Mut {
    var i: i64 = 0
    while i < count {
        let e = table[i as usize]
        if e.mod_hash == mod_hash && e.sym_hash == sym_hash {
            return e.def_id
        }
        i = i + 1
    }
    return 0 - 1
}

// ---- Minimal hover result buffer ----

struct HoverBuf {
    buf: [i8; 128],
    len: i64,
}

fn hover_buf_new() -> HoverBuf {
    HoverBuf { buf: [0; 128], len: 0 }
}

fn hover_buf_append(buf: &! HoverBuf, b: i8) with Mut, Panic {
    if buf.len < 128 {
        buf.buf[buf.len as usize] = b
        buf.len = buf.len + 1
    }
}

fn hover_buf_append_i64(buf: &! HoverBuf, val: i64) with Mut, Div, Panic {
    if val == 0 {
        hover_buf_append(buf, 48)
        return
    }
    var n = val
    if n < 0 {
        hover_buf_append(buf, 45)
        n = 0 - n
    }
    var digits: [i8; 24] = [0; 24]
    var dlen: i64 = 0
    while n > 0 {
        digits[dlen as usize] = (48 + (n % 10)) as i8
        n = n / 10
        dlen = dlen + 1
    }
    var i = dlen - 1
    while i >= 0 {
        hover_buf_append(buf, digits[i as usize])
        i = i - 1
    }
}

// hover_qualified: simulate lsp_hover_qualified behaviour.
// Returns 1 if def_id >= 0 (hover was filled), 0 otherwise.
fn hover_qualified(result: &! HoverBuf, def_id: i64) -> i64 with Mut, Div, Panic {
    if def_id < 0 {
        return 0
    }
    result.len = 0
    // "(qualified symbol, def_id="
    hover_buf_append(result, 40)   // (
    hover_buf_append(result, 113)  // q
    hover_buf_append(result, 117)  // u
    hover_buf_append(result, 97)   // a
    hover_buf_append(result, 108)  // l
    hover_buf_append(result, 105)  // i
    hover_buf_append(result, 102)  // f
    hover_buf_append(result, 105)  // i
    hover_buf_append(result, 101)  // e
    hover_buf_append(result, 100)  // d
    hover_buf_append(result, 32)   // space
    hover_buf_append(result, 115)  // s
    hover_buf_append(result, 121)  // y
    hover_buf_append(result, 109)  // m
    hover_buf_append(result, 98)   // b
    hover_buf_append(result, 111)  // o
    hover_buf_append(result, 108)  // l
    hover_buf_append(result, 44)   // ,
    hover_buf_append(result, 32)   // space
    hover_buf_append(result, 100)  // d
    hover_buf_append(result, 101)  // e
    hover_buf_append(result, 102)  // f
    hover_buf_append(result, 95)   // _
    hover_buf_append(result, 105)  // i
    hover_buf_append(result, 100)  // d
    hover_buf_append(result, 61)   // =
    hover_buf_append_i64(result, def_id)
    hover_buf_append(result, 41)   // )
    1
}

fn main() -> i32 with IO, Mut, Div, Panic {
    var passed: i32 = 0
    var failed: i32 = 0

    // Build bridge: mod=10,sym=100→def=1  mod=10,sym=200→def=2
    //               mod=20,sym=300→def=3  mod=20,sym=400→def=4
    var tbl: [QBridgeEntry; 8] = [QBridgeEntry { mod_hash: 0, sym_hash: 0, def_id: 0 }; 8]
    tbl[0] = QBridgeEntry { mod_hash: 10, sym_hash: 100, def_id: 1 }
    tbl[1] = QBridgeEntry { mod_hash: 10, sym_hash: 200, def_id: 2 }
    tbl[2] = QBridgeEntry { mod_hash: 20, sym_hash: 300, def_id: 3 }
    tbl[3] = QBridgeEntry { mod_hash: 20, sym_hash: 400, def_id: 4 }
    let count: i64 = 4

    var result: HoverBuf = hover_buf_new()

    // T1: known mod+sym → correct def_id, hover returns 1
    let d1 = qbridge_lookup(&tbl, count, 10, 100)
    let ok1 = hover_qualified(&! result, d1)
    if d1 == 1 && ok1 == 1 && result.len > 0 {
        passed = passed + 1
    } else {
        println("T1 FAIL")
        failed = failed + 1
    }

    // T2: second symbol in same module → def_id=2
    let d2 = qbridge_lookup(&tbl, count, 10, 200)
    let ok2 = hover_qualified(&! result, d2)
    if d2 == 2 && ok2 == 1 {
        passed = passed + 1
    } else {
        println("T2 FAIL")
        failed = failed + 1
    }

    // T3: cross-module symbol → def_id=3
    let d3 = qbridge_lookup(&tbl, count, 20, 300)
    let ok3 = hover_qualified(&! result, d3)
    if d3 == 3 && ok3 == 1 {
        passed = passed + 1
    } else {
        println("T3 FAIL")
        failed = failed + 1
    }

    // T4: miss (unknown mod+sym) → def_id=-1, hover returns 0, buf not touched
    result.len = 0
    let d4 = qbridge_lookup(&tbl, count, 99, 999)
    let ok4 = hover_qualified(&! result, d4)
    if d4 == 0 - 1 && ok4 == 0 && result.len == 0 {
        passed = passed + 1
    } else {
        println("T4 FAIL")
        failed = failed + 1
    }

    // T5: hover buffer starts with '(' when def_id is valid
    let d5 = qbridge_lookup(&tbl, count, 20, 400)
    let ok5 = hover_qualified(&! result, d5)
    let first_byte = result.buf[0]
    if d5 == 4 && ok5 == 1 && first_byte == 40 {
        passed = passed + 1
    } else {
        println("T5 FAIL")
        failed = failed + 1
    }

    // T6: hover buffer ends with ')' and contains def_id digits
    let d6 = qbridge_lookup(&tbl, count, 10, 100)
    let ok6 = hover_qualified(&! result, d6)
    let last_byte = result.buf[(result.len - 1) as usize]
    if d6 == 1 && ok6 == 1 && last_byte == 41 {
        passed = passed + 1
    } else {
        println("T6 FAIL")
        failed = failed + 1
    }

    if failed == 0 { println("lsp_hover_qualified: PASS") }
    else { println("lsp_hover_qualified: FAIL") }
    failed as i32
}

