//@ run-pass
//@ requires: madaros
//@ expect-stdout: MADAROS_CORRELATE_PER_FUNCTION_PASS

// A correlation declared in one function must not reach another.
//
// FO_COV_RHO is a module global and channel ids restart at 0 in every
// function, so before the per-function reset a `correlate(a, b, 1.0)` in the
// first function silently supplied rho to the second one, which had never
// mentioned correlation at all. That is worse than losing a correlation:
// losing one returns the old, wrong-but-familiar number, while this invents a
// dependence no source line asked for -- in a system whose entire claim is
// that the independence assumption is deniable rather than ambient.
//
// pair_correlated MUST run first. It is the contaminating call.
//
//   correlated:   Var(a+b) = 0.01 + 0.09 + 2*0.1*0.3*1.0 = 0.16
//   independent:  Var(c+d) = 0.01 + 0.09                 = 0.10
//
// Before the fix the second function also read 0.16.

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn pair_correlated() -> f64 with IO, Mut, Div, Epistemic {
    let ka: Knowledge<f64> = measure(1.0, uncertainty: 0.1)
    let kb: Knowledge<f64> = measure(2.0, uncertainty: 0.3)
    let a = ka.value
    let b = kb.value
    let _r = correlate(a, b, 1.0)
    return variance_of(a + b)
}

fn pair_independent() -> f64 with IO, Mut, Div, Epistemic {
    let kc: Knowledge<f64> = measure(1.0, uncertainty: 0.1)
    let kd: Knowledge<f64> = measure(2.0, uncertainty: 0.3)
    let c = kc.value
    let d = kd.value
    return variance_of(c + d)
}

fn main() with IO, Mut, Div, Epistemic {
    let v_cor = pair_correlated()
    let v_ind = pair_independent()

    print("v_cor="); print_f64(v_cor); print("\n")
    print("v_ind="); print_f64(v_ind); print("\n")

    let ok = abs_f(v_cor - 0.16) < 1.0e-12 && abs_f(v_ind - 0.10) < 1.0e-12
    if ok {
        print("MADAROS_CORRELATE_PER_FUNCTION_PASS\n")
    } else {
        print("MADAROS_CORRELATE_PER_FUNCTION_FAIL\n")
    }
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: MADAROS_CORRELATE_NEGATIVE_RHO_PASS

// A negative correlation coefficient.
//
// This dialect writes a negative literal as `0.0 - 0.5`, an ExprBinary. The
// lowerer folded only ExprFloatLit, so every negative rho fell through to the
// initialiser 0.0 -- silently asserting independence in the one case the
// builtin exists for. Anticorrelation is not an edge case in GUM; it is where
// the correction changes sign.
//
//   sigma_x = 0.1, sigma_y = 0.3
//   rho = +1.0 : 0.01 + 0.09 + 2*0.03 = 0.16
//   rho =  0.0 : 0.01 + 0.09          = 0.10
//   rho = -1.0 : 0.01 + 0.09 - 2*0.03 = 0.04
//   rho = -0.5 : 0.01 + 0.09 - 0.03   = 0.07

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn v_with_rho_neg_one() -> f64 with IO, Mut, Div, Epistemic {
    let kx: Knowledge<f64> = measure(1.0, uncertainty: 0.1)
    let ky: Knowledge<f64> = measure(2.0, uncertainty: 0.3)
    let x = kx.value
    let y = ky.value
    let _r = correlate(x, y, 0.0 - 1.0)
    return variance_of(x + y)
}

fn v_with_rho_neg_half() -> f64 with IO, Mut, Div, Epistemic {
    let kx: Knowledge<f64> = measure(1.0, uncertainty: 0.1)
    let ky: Knowledge<f64> = measure(2.0, uncertainty: 0.3)
    let x = kx.value
    let y = ky.value
    let _r = correlate(x, y, 0.0 - 0.5)
    return variance_of(x + y)
}

fn v_with_rho_plus_one() -> f64 with IO, Mut, Div, Epistemic {
    let kx: Knowledge<f64> = measure(1.0, uncertainty: 0.1)
    let ky: Knowledge<f64> = measure(2.0, uncertainty: 0.3)
    let x = kx.value
    let y = ky.value
    let _r = correlate(x, y, 1.0)
    return variance_of(x + y)
}

fn main() with IO, Mut, Div, Epistemic {
    let v_neg1 = v_with_rho_neg_one()
    let v_neghalf = v_with_rho_neg_half()
    let v_pos1 = v_with_rho_plus_one()

    print("v_neg1="); print_f64(v_neg1); print("\n")
    print("v_neghalf="); print_f64(v_neghalf); print("\n")
    print("v_pos1="); print_f64(v_pos1); print("\n")

    let ok = abs_f(v_neg1 - 0.04) < 1.0e-12
        && abs_f(v_neghalf - 0.07) < 1.0e-12
        && abs_f(v_pos1 - 0.16) < 1.0e-12
    if ok {
        print("MADAROS_CORRELATE_NEGATIVE_RHO_PASS\n")
    } else {
        print("MADAROS_CORRELATE_NEGATIVE_RHO_FAIL\n")
    }
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: MADAROS_GUM_FO_CORRELATE_PASS
//@ sabotage: correlate-rho

// Correlated FO: off-diagonal Hessian × Cov in Var and E₂.
// Independent: E₂[(x+y)²] = 9 + σx² + σy² = 9.05
// Fully correlated ρ=1: E₂ = 9 + σx² + σy² + 2 Cov = 9.09
//   Cov = ρ σx σy = 0.02
// Var(x+y) indep = 0.05; ρ=1 → (σx+σy)² = 0.09

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() with IO, Mut, Div, Epistemic {
    let kx: Knowledge<f64> = measure(1.0, uncertainty: 0.1)
    let ky: Knowledge<f64> = measure(2.0, uncertainty: 0.2)
    let x = kx.value
    let y = ky.value

    // Independent baseline
    let m2_ind = second_order_mean((x + y) * (x + y))
    let v_ind = variance_of(x + y)
    let m2_prod_ind = second_order_mean(x * y)
    let v_prod_ind = variance_of(x * y)

    // Correlate fully (ρ=1)
    let _r = correlate(x, y, 1.0)
    let m2_cor = second_order_mean((x + y) * (x + y))
    let v_cor = variance_of(x + y)
    let m2_prod_cor = second_order_mean(x * y)
    let v_prod_cor = variance_of(x * y)

    print("m2_ind="); print_f64(m2_ind); print("\n")
    print("m2_cor="); print_f64(m2_cor); print("\n")
    print("v_ind="); print_f64(v_ind); print("\n")
    print("v_cor="); print_f64(v_cor); print("\n")
    print("m2_prod_ind="); print_f64(m2_prod_ind); print("\n")
    print("m2_prod_cor="); print_f64(m2_prod_cor); print("\n")
    print("v_prod_ind="); print_f64(v_prod_ind); print("\n")
    print("v_prod_cor="); print_f64(v_prod_cor); print("\n")

    // Analytic (σx=0.1, σy=0.2, Cov=ρ·σx·σy)
    // (x+y)²: μ=3, Hxx=Hyy=2, Hxy=2
    //   E2 ind = 9 + σx²+σy² = 9.05
    //   E2 cor ρ=1 = 9.05 + 2·0.02 = 9.09
    //   Var(x+y) ind = 0.05; ρ=1 → 0.09
    // product xy: Hxy=1; E2 ind=2; E2 cor=2+0.02=2.02
    //   Var ind = y²σx²+x²σy² = 0.08
    //   Var cor = 0.08 + 2·s_x·s_y·Cov = 0.08 + 2·2·1·0.02 = 0.16

    let ok = abs_f(m2_ind - 9.05) < 1.0e-6
        && abs_f(v_ind - 0.05) < 1.0e-9
        && abs_f(m2_cor - 9.09) < 1.0e-6
        && abs_f(v_cor - 0.09) < 1.0e-9
        && abs_f(m2_prod_ind - 2.0) < 1.0e-9
        && abs_f(m2_prod_cor - 2.02) < 1.0e-9
        && abs_f(v_prod_ind - 0.08) < 1.0e-9
        && abs_f(v_prod_cor - 0.16) < 1.0e-9
    if ok {
        print("MADAROS_GUM_FO_CORRELATE_PASS\n")
    } else {
        print("MADAROS_GUM_FO_CORRELATE_FAIL\n")
    }
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: MADAROS_GUM_FO_CORRELATE_LATENT_PASS
//@ sabotage: correlate-rho

// Distinct measures that share a latent — use correlate(a,b,ρ).
// Independent measure(0, σ) ×2 stay 2-channel until correlate; ρ=1 makes
// Var(a+b)=(σ+σ)² and matches shared-peel Var(η+η).
// Science path for two CL factors sharing η without a single peel.

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() with IO, Mut, Div, Epistemic {
    // Two independent measures of the same physical latent η
    let e1: Knowledge<f64> = measure(0.0, uncertainty: 0.1)
    let e2: Knowledge<f64> = measure(0.0, uncertainty: 0.1)
    let a = e1.value
    let b = e2.value

    let v_indep = variance_of(a + b)
    let _r = correlate(a, b, 1.0)
    let v_corr = variance_of(a + b)

    // Shared peel (single measure used twice)
    let e: Knowledge<f64> = measure(0.0, uncertainty: 0.1)
    let eta = e.value
    let v_shared = variance_of(eta + eta)

    // PK-shaped: CL0·exp(η1) * V0·exp(η2) with ρ=1 on η
    let kCL: Knowledge<f64> = measure(5.0, uncertainty: 0.0)
    let kV: Knowledge<f64> = measure(50.0, uncertainty: 0.0)
    let cl0 = kCL.value
    let v0 = kV.value
    let e3: Knowledge<f64> = measure(0.0, uncertainty: 0.1)
    let e4: Knowledge<f64> = measure(0.0, uncertainty: 0.1)
    let n1 = e3.value
    let n2 = e4.value
    let v_prod_ind = variance_of((cl0 * exp(n1)) * (v0 * exp(n2)))
    let _r2 = correlate(n1, n2, 1.0)
    let v_prod_cor = variance_of((cl0 * exp(n1)) * (v0 * exp(n2)))
    // Shared η peel product
    let v_prod_shared = variance_of((cl0 * exp(eta)) * (v0 * exp(eta)))

    print("v_indep="); print_f64(v_indep); print("\n")
    print("v_corr="); print_f64(v_corr); print("\n")
    print("v_shared="); print_f64(v_shared); print("\n")
    print("v_prod_ind="); print_f64(v_prod_ind); print("\n")
    print("v_prod_cor="); print_f64(v_prod_cor); print("\n")
    print("v_prod_shared="); print_f64(v_prod_shared); print("\n")

    // σ=0.1: indep Var(a+b)=0.02; ρ=1 → 0.04 = shared
    // product CL·V·exp(η1+η2): at ρ=1 matches shared η
    let ok = abs_f(v_indep - 0.02) < 1.0e-9
        && abs_f(v_corr - 0.04) < 1.0e-9
        && abs_f(v_shared - 0.04) < 1.0e-9
        && abs_f(v_corr - v_shared) < 1.0e-9
        && abs_f(v_prod_cor - v_prod_shared) < 1.0e-6
        && v_prod_cor > v_prod_ind
        && v_prod_ind > 0.0
    if ok {
        print("MADAROS_GUM_FO_CORRELATE_LATENT_PASS\n")
    } else {
        print("MADAROS_GUM_FO_CORRELATE_LATENT_FAIL\n")
    }
}

//@ run-pass
//@ expect-stdout: MADAROS_GUM_FO_DEEP_FIELD_PASS
//@ requires: madaros
// Madaros PASSES this as of the call-result FO work on #1706; lean_single does
// not. The annotation names a real engine boundary rather than hiding a failure:
// the fix lives in self-hosted/ir/lower.sio, and CI's suite compiles with
// souc-stage2, built from self-hosted/compiler/lean_single.sio -- a separate
// compiler that shares none of it.

// Deep call-result field FO — nests beyond the historical mid1/mid2 ceiling.
// Residual was make().c.b.a.x → FO 0 (three intermediate fields + leaf).
// Ident-rooted chains of any depth already peeled; this gate freezes Call paths.

struct A {
    x: f64
}

struct B {
    a: A
}

struct C {
