//@ run-pass
// medlang_pk_model.sio - One-compartment PK model simulation and verification
//
// This test builds and simulates a simple one-compartment pharmacokinetic model:
//   - Defines a drug with physicochemical properties (MW, logP, fu)
//   - Defines a one-compartment IV bolus model (CL, V -> ke)
//   - Simulates 100 mg IV bolus dose over 24 hours using Euler integration
//   - Verifies exponential decay of concentration
//   - Checks mass balance: eliminated + remaining = dose

// ============================================================================
// Math helpers (self-contained, no stdlib dependency)
// ============================================================================

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

fn exp_approx(x: f64) -> f64 with Panic, Mut, Div {
    // Taylor series approximation of exp(x) with range reduction
    let ln2 = 0.6931471805599453
    var v = x
    if v > 700.0 { v = 700.0 }
    if v < 0.0 - 700.0 { return 0.0 }
    let k = (v / ln2) as i64
    let r = v - (k as f64) * ln2
    var result = 1.0
    var term = 1.0
    var i: i64 = 1
    while i <= 15 {
        term = term * r / (i as f64)
        result = result + term
        i = i + 1
    }
    if k >= 0 {
        var j: i64 = 0
        while j < k { result = result * 2.0; j = j + 1 }
    } else {
        var j: i64 = 0
        while j < 0 - k { result = result / 2.0; j = j + 1 }
    }
    result
}

// ============================================================================
// Drug definition
// ============================================================================

struct Drug {
    mw: f64,       // molecular weight (g/mol)
    logp: f64,     // lipophilicity
    fu: f64,       // fraction unbound (0-1)
}

fn drug_theophylline() -> Drug {
    Drug {
        mw: 180.16,
        logp: 0.02,
        fu: 0.4,
    }
}

// ============================================================================
// One-compartment PK model
// ============================================================================

struct OneCompModel {
    cl: f64,    // clearance (L/h)
    v: f64,     // volume of distribution (L)
    ke: f64,    // elimination rate constant (1/h)
}

fn one_comp_model(cl: f64, v: f64) -> OneCompModel with Panic {
    OneCompModel {
        cl: cl,
        v: v,
        ke: cl / v,
    }
}

// ============================================================================
// Simulation state
// ============================================================================

struct SimState {
    amount: f64,            // drug amount in central compartment (mg)
    concentration: f64,     // concentration (mg/L)
    time: f64,              // current time (h)
    eliminated: f64,        // cumulative amount eliminated (mg)
}

fn sim_state_new() -> SimState {
    SimState {
        amount: 0.0,
        concentration: 0.0,
        time: 0.0,
        eliminated: 0.0,
    }
}

// ============================================================================
// Euler integration for one-compartment elimination
// ============================================================================

// dA/dt = -ke * A
// Eliminated per step = ke * A * dt
fn euler_step(state: SimState, model: OneCompModel, dt: f64) -> SimState with Panic {
    let dAdt = 0.0 - model.ke * state.amount
    let elim_this_step = model.ke * state.amount * dt
    let new_amount = state.amount + dAdt * dt

    SimState {
        amount: new_amount,
        concentration: new_amount / model.v,
        time: state.time + dt,
        eliminated: state.eliminated + elim_this_step,
    }
}

// ============================================================================
// Simulation result storage
// ============================================================================

struct SimResult {
    times: [f64; 250],
    concentrations: [f64; 250],
    amounts: [f64; 250],
    n_points: i64,
}

fn sim_result_new() -> SimResult {
    SimResult {
        times: [0.0; 250],
        concentrations: [0.0; 250],
        amounts: [0.0; 250],
        n_points: 0,
    }
}

// ============================================================================
// Main simulation
// ============================================================================

fn simulate_iv_bolus(
    dose: f64,
    model: OneCompModel,
    t_end: f64,
    dt: f64
) -> SimResult with Panic, Mut, Div {
    var result = sim_result_new()

    // Initialize: IV bolus at t=0
    var state = sim_state_new()
    state.amount = dose
    state.concentration = dose / model.v
    state.time = 0.0
    state.eliminated = 0.0

    var idx: i64 = 0

    while state.time <= t_end && idx < 250 {
        result.times[idx as usize] = state.time
        result.concentrations[idx as usize] = state.concentration
        result.amounts[idx as usize] = state.amount
        idx = idx + 1

        state = euler_step(state, model, dt)
    }

    result.n_points = idx
    result
}

// ============================================================================
// Verification functions
// ============================================================================

fn verify_exponential_decay(result: SimResult) -> bool with Panic, Mut, Div {
    // Concentration should be monotonically decreasing
    if result.n_points < 10 {
        return false
    }

    var i: i64 = 1
    while i < result.n_points {
        if result.concentrations[i as usize] > result.concentrations[(i - 1) as usize] + 1e-10 {
            // Concentration increased -- not exponential decay
            return false
        }
        i = i + 1
    }

    // First concentration should be highest
    let c_max = result.concentrations[0]
    if c_max <= 0.0 {
        return false
    }

    // Last concentration should be much lower
    let c_last = result.concentrations[(result.n_points - 1) as usize]
    if c_last >= c_max {
        return false
    }

    true
}

fn verify_initial_concentration(result: SimResult, dose: f64, v: f64) -> bool with Panic {
    // C(0) = dose / V
    let expected_c0 = dose / v
    let actual_c0 = result.concentrations[0]
    abs_f64(actual_c0 - expected_c0) < 0.01
}

fn verify_half_life(result: SimResult, ke: f64, dt: f64) -> bool with Panic {
    // t_half = ln(2) / ke
    let t_half = 0.693147 / ke

    // Find concentration at approximately t_half
    let idx_half = (t_half / dt) as i64
    if idx_half <= 0 || idx_half >= result.n_points {
        return false
    }

    let c0 = result.concentrations[0]
    let c_half = result.concentrations[idx_half as usize]

    // At t_half, concentration should be approximately C0/2
    // Allow 5% tolerance due to Euler discretization
    let ratio = c_half / c0
    abs_f64(ratio - 0.5) < 0.05
}

fn verify_mass_balance(result: SimResult, dose: f64, model: OneCompModel, dt: f64) -> bool with Panic, Mut, Div {
    // Recompute to track elimination
    var state = sim_state_new()
    state.amount = dose
    state.time = 0.0
    state.eliminated = 0.0

    var steps: i64 = 0
    let max_steps = result.n_points

    while steps < max_steps {
        state = euler_step(state, model, dt)
        steps = steps + 1
    }

    // Mass balance: remaining + eliminated should equal dose
    let total = state.amount + state.eliminated
    let error = abs_f64(total - dose)

    // Allow small numerical drift from Euler integration
    error < 0.5
}

fn verify_analytical_solution(result: SimResult, dose: f64, model: OneCompModel, dt: f64) -> bool with Panic, Mut, Div {
    // Compare numerical solution against analytical: C(t) = (dose/V) * exp(-ke * t)
    var max_rel_error = 0.0
    var i: i64 = 1
    while i < result.n_points && i < 100 {
        let t = result.times[i as usize]
        let c_numerical = result.concentrations[i as usize]
        let c_analytical = (dose / model.v) * exp_approx(0.0 - model.ke * t)

        if c_analytical > 0.01 {
            let rel_error = abs_f64(c_numerical - c_analytical) / c_analytical
            if rel_error > max_rel_error {
                max_rel_error = rel_error
            }
        }
        i = i + 1
    }

    // Euler with dt=0.1 should be within 2% of analytical
    max_rel_error < 0.02
}

// ============================================================================
// Entry point
// ============================================================================

fn main() -> i32 with IO, Panic, Mut, Div {
    // Define drug: Theophylline-like
    let drug = drug_theophylline()

    // Define one-compartment model
    // CL = 2.8 L/h, V = 25 L -> ke = 0.112 /h, t1/2 ~ 6.2 h
    let model = one_comp_model(2.8, 25.0)

    // Dose: 100 mg IV bolus
    let dose: f64 = 100.0

    // Simulate for 24 hours with dt = 0.1 h
    let t_end = 24.0
    let dt = 0.1
    let result = simulate_iv_bolus(dose, model, t_end, dt)

    // Verification 1: Check we got enough data points
    if result.n_points < 200 {
        print_int(1)
        return 1
    }

    // Verification 2: Concentration starts high and decays exponentially
    if !verify_exponential_decay(result) {
        print_int(2)
        return 2
    }

    // Verification 3: Initial concentration = dose / V = 100 / 25 = 4.0 mg/L
    if !verify_initial_concentration(result, dose, model.v) {
        print_int(3)
        return 3
    }

    // Verification 4: Half-life check
    if !verify_half_life(result, model.ke, dt) {
        print_int(4)
        return 4
    }

    // Verification 5: Mass balance (eliminated + remaining = dose)
    if !verify_mass_balance(result, dose, model, dt) {
        print_int(5)
        return 5
    }

    // Verification 6: Numerical vs analytical solution agreement
    if !verify_analytical_solution(result, dose, model, dt) {
        print_int(6)
        return 6
    }

    // Verification 7: Drug properties are sensible
    if drug.mw <= 0.0 {
        print_int(7)
        return 7
    }
    if drug.fu <= 0.0 || drug.fu > 1.0 {
        print_int(8)
        return 8
    }

    // All checks passed
    print_int(0)
    0
}

//@ run-pass
// tests/run-pass/mercyful_chemo_sequencing.sio
//
// Mercyful Learning x cancer chemotherapy sequencing benchmark (Sounio native).
//
// Synthetic chemotherapy-sequencing graph: a toxicity suffering field over
// treatment states with remission as the anti-Goodhart target. Demonstrates:
//   - Hazard A: watch-and-wait trap (s = 0 forever, never reaches remission)
//   - Hazard B: dose-reduced under-treatment (low toxicity, cannot reach
//     remission -- the RDI literature's survival-cost hazard, structurally)
//   - Peak-vs-integral trade-off: dose-dense (integral 48, peak 8) vs
//     OPTIMOX-style stop-and-go (integral 81, peak 5), crossover mu* = 11
//   - G_GCSF gate: the high-FN-risk dose-dense route is topologically absent
//     without mandated growth-factor support
//   - Budgetary necessity: minimal attainable peak drops from 8 to 5 when the
//     declared budget extends from 10 to 30 weeks
//
// Spec: docs/research/mercyful_chemo_sequencing_spec_2026-07-26.md
// Gate: scripts/ci/mercyful_chemo_sequencing_gate.sh
// Python twin (H1..H8): scripts/research/mercyful_chemo_contract.py
//
// Clinical warning: synthetic graph, synthetic regimens, synthetic suffering
// values. This is not medical guidance and carries no clinical claim.

use clinical::mercyful::*

// State indices:
//   0 DIAG     s=0.0  untreated at diagnosis (Goodhart trap A)
//   1 REDUCED  s=1.5  dose-reduced chemo, RDI ~60% (Goodhart trap B)
//   2 DD_A     s=8.0  dose-dense block 1 (G-CSF-supported)
//   3 DD_B     s=8.0  dose-dense block 2
//   4 STD_A    s=5.0  standard q3w block 1
//   5 STD_B    s=5.0  standard q3w block 2
//   6 CFI      s=1.0  chemo-free interval (stop-and-go break)
//   7 RECH     s=5.0  rechallenge after break
//   8 CONT_C   s=8.0  continuous block 3 (cumulative neuropathy)
//   9 REM      s=0.0  TARGET: remission
//
// Edge lengths are weeks.
fn build_chemo_graph(gcsf: bool) -> MercyGraph with Mut, Panic {
    var g = mercy_graph_new()
    g = mercy_add_state(g, 0.0)  // 0 DIAG
    g = mercy_add_state(g, 1.5)  // 1 REDUCED
    g = mercy_add_state(g, 8.0)  // 2 DD_A
    g = mercy_add_state(g, 8.0)  // 3 DD_B
    g = mercy_add_state(g, 5.0)  // 4 STD_A
    g = mercy_add_state(g, 5.0)  // 5 STD_B
    g = mercy_add_state(g, 1.0)  // 6 CFI
    g = mercy_add_state(g, 5.0)  // 7 RECH
    g = mercy_add_state(g, 8.0)  // 8 CONT_C
    g = mercy_add_state(g, 0.0)  // 9 REM
    g = mercy_add_edge(g, 0, 0, 1.0)  // watch-and-wait trap
    g = mercy_add_edge(g, 0, 1, 2.0)  // start dose-reduced
    g = mercy_add_edge(g, 1, 1, 2.0)  // continue reduced: dead end
    g = mercy_add_edge(g, 0, 4, 3.0)
    g = mercy_add_edge(g, 4, 5, 6.0)
    g = mercy_add_edge(g, 5, 6, 6.0)
    g = mercy_add_edge(g, 6, 7, 6.0)
    g = mercy_add_edge(g, 7, 9, 3.0)  // stop-and-go completes
    g = mercy_add_edge(g, 5, 8, 6.0)
    g = mercy_add_edge(g, 8, 9, 3.0)  // continuous course completes
    // G_GCSF: high-FN-risk dose-dense route admitted only with support.
    if gcsf {
        g = mercy_add_edge(g, 0, 2, 2.0)
        g = mercy_add_edge(g, 2, 3, 4.0)
        g = mercy_add_edge(g, 3, 9, 2.0)
    }
    g
}

// H2 variant: only the dose-reduced route exists. It can never reach REM.
fn build_reduced_only_graph() -> MercyGraph with Mut, Panic {
    var g = mercy_graph_new()
    g = mercy_add_state(g, 0.0)  // 0 DIAG
    g = mercy_add_state(g, 1.5)  // 1 REDUCED
    g = mercy_add_state(g, 0.0)  // 2 REM
    g = mercy_add_edge(g, 0, 0, 1.0)
    g = mercy_add_edge(g, 0, 1, 2.0)
    g = mercy_add_edge(g, 1, 1, 2.0)
    g
}

fn main() -> i32 with IO, Mut, Panic {
    var failures = 0

    // Infeasibility sentinel threshold: mercyful.sio leaves best_cost at its
    // 1e100 initial value when a path exists but none fits the budget, and
    // returns all zeros when the target is unreachable. Any total above this
    // threshold means INFEASIBLE.
    let INF_COST: f64 = 1e90

    // H1: baseline (G-CSF on, mu=1, L0=30): dose-dense route selected with
    // exact metrics length 8, integral 48, peak 8, total 56.
    // Integral is left-endpoint quadrature over edges 0->2->3->9:
    // s(DIAG)*2 + s(DD_A)*4 + s(DD_B)*2 = 0*2 + 8*4 + 8*2 = 48
    // (the first 2 weeks accrue at DIAG's zero suffering, not at s=8).
    // NOTE: found-ness is read off the cost tuple (lean_single mistypes bools
    // destructured from heterogeneous tuples): infeasible returns all zeros,
    // and every feasible path here has total > 0.
    let g = build_chemo_graph(true)
    let (f1, l1, i1, p1, t1) = mercyful_schedule(&g, 0, 9, 1.0, 30.0)
    println(l1)
    println(i1)
    println(p1)
    println(t1)
    if l1 == 8.0 && i1 == 48.0 && p1 == 8.0 && t1 == 56.0 {
        println("H1_BASELINE PASS")
    } else {
        println("H1_BASELINE FAIL")
        failures = failures + 1
    }

    // H2: anti-Goodhart. The unconstrained raw minimizer loops DIAG at cost 0
    // (strictly below the min feasible integral 48, recomputed here so this
    // clause is independent of H1), and the dose-reduced route structurally
    // cannot reach remission.
    let g2 = build_reduced_only_graph()
    let (f2, l2, i2, p2, t2) = mercyful_schedule(&g2, 0, 2, 1.0, 30.0)
    let (f2b, l2b, i2b, p2b, t2b) = mercyful_schedule(&g, 0, 9, 1.0, 30.0)
    if i2b > 0.0 && t2 == 0.0 {
        println("H2_ANTI_GOODHART PASS")
    } else {
        println("H2_ANTI_GOODHART FAIL")
        failures = failures + 1
    }

    // H3: mu-crossover at mu* = 11. mu=0 selects dose-dense (total 48);
    // mu=20 selects stop-and-go (total 81 + 20*5 = 181).
    let (f3a, l3a, i3a, p3a, t3a) = mercyful_schedule(&g, 0, 9, 0.0, 30.0)
    let (f3b, l3b, i3b, p3b, t3b) = mercyful_schedule(&g, 0, 9, 20.0, 30.0)
    if t3a == 48.0 && p3a == 8.0 && t3b == 181.0 && p3b == 5.0 {
        println("H3_MU_CROSSOVER PASS")
    } else {
        println("H3_MU_CROSSOVER FAIL")
        failures = failures + 1
    }

    // H5: G_GCSF causality. Without support the dose-dense route is absent;
