//
// `(*o).field.method()` -- a method whose receiver is a field whose OWNER is a
// deref. expr_receiver_struct_type_ref resolved an ident, an index and a field
// base, but had no ExprUnary arm, so the owner came back empty, the field's type
// with it, and the call was emitted against the BARE method name. That invents a
// function with no body, and native_v2 emits `ud2` for it rather than
// prologue+ret, which would let the call read rax and fabricate a value.
//
// Before the fix this program compiled, printed `via_value=42`, then DIED at
// `via_ref` with exit 132 -- 128+4, SIGILL, the ud2 executing. Two refusals were
// reported for it. After, both lines print 42.
//
// `via_value` is the control: the same call through a by-value parameter, which
// took the ident path and always worked. If a fix breaks THAT, it broke ordinary
// field typing rather than the deref owner.

struct Inner { n: i64 }
struct Outer { inner: Inner, tag: i64 }

impl Inner {
    fn get(self) -> i64 with Mut, Panic, Div { self.n }
}

fn via_ref(o: &! Outer) -> i64 with Mut, Panic, Div, Alloc {
    (*o).inner.get()
}

fn via_value(o: Outer) -> i64 with Mut, Panic, Div, Alloc {
    o.inner.get()
}

fn main() -> i64 with IO, Mut, Panic, Div, Alloc {
    var ou = Outer { inner: Inner { n: 42 }, tag: 7 }
    print("via_value=") println(via_value(ou))
    print("via_ref=") println(via_ref(&! ou))
    println("PASS")
    0
}

//@ run-pass
// Regression test: method receiver inference uses declared signature, not heuristics.
//
// Bug (pre-fix): infer_method_receiver_use used string-prefix heuristics to decide
// whether a method call borrows &T, mutably borrows &!T, or moves T.  Methods whose
// names did not match the heuristic patterns were treated as moves even when the
// declared first parameter was &!Self, producing false-positive ownership errors or
// silent miscompilation.
//
// Fix: the method call handler now calls scan_fnsig_param_type(FN_SIG[mfi], 0) to
// read the actual declared receiver type.  If SCAN_TY==10 and ref_hash_mut!=0 the
// receiver is an exclusive borrow (&!Self): borrow conflict checks are enforced and
// the borrow is released after the call.  No heuristic string matching is used.
//
// This test verifies:
//   1. A struct method declared with &!Self can mutate state without a false positive.
//   2. The ownership checker permits a second &!Self call on the same variable after
//      the first call's ephemeral borrow has been released.
//   3. A &Self (shared) method may be called while no exclusive borrow is active.
//   4. main() returns 0 (success) when all mutations produce the expected values.

struct Counter {
    value: i64
}

fn increment(c: &! Counter) with Mut, Panic {
    // &!Self receiver: mutates the Counter in place
    c.value = c.value + 1
}

fn add_n(c: &! Counter, n: i64) with Mut, Panic {
    // &!Self receiver with additional argument
    c.value = c.value + n
}

fn read_value(c: &Counter) -> i64 with Panic {
    // &Self (shared) receiver: read-only access
    return c.value
}

fn main() -> i32 with IO, Mut, Panic {
    var ctr: Counter = Counter { value: 0 }

    // First exclusive-borrow call — ephemeral &! is taken and released.
    increment(&! ctr)

    // Second exclusive-borrow call on the same variable — must succeed because
    // the first call's borrow was released after return.
    increment(&! ctr)

    // Exclusive-borrow call with extra arg.
    add_n(&! ctr, 10)

    // Shared-borrow read — permitted because no exclusive borrow is active.
    let v = read_value(&ctr)

    // Expected: 0 + 1 + 1 + 10 = 12
    if v == 12 {
        println("method_receiver_correct: PASS")
        return 0
    }
    println("method_receiver_correct: FAIL")
    return 1
}

//@ run-pass
// Module-level `let` constants with EXPRESSION initializers must carry the folded value.
// Found 2026-09-01 through the e-graph Q-certificate self-tests: the lean_single seed read
// `0 - 1` as 0 (dropping everything after the first literal), which made EG_INVALID == 0 in
// every source-built Madaros and silently discarded the first node of every small e-graph;
// Madaros' own folder lacked shifts (`1 << 3` -> BSS zero). Every case below is checked
// against an in-function computation of the same expression.
let C_NEG: i64 = 0 - 1
let C_NEGLIT: i64 = -1
let C_SUM: i64 = 1 + 1
let C_MULP: i64 = (2 + 3) * 4
let C_PREC: i64 = 2 + 3 * 4
let C_SHL: i64 = 1 << 3
let C_SHR: i64 = 256 >> 4
let C_REM: i64 = 7 % 4
let C_AND: i64 = 6 & 3
let C_OR: i64 = 6 | 1
let C_XOR: i64 = 6 ^ 3
let C_BIG: i64 = 0 - 800001
let C_CHAIN: i64 = 0 - 1 - 1

fn main() -> i32 with IO {
    var bad: i64 = 0
    if C_NEG != 0 - 1 { println("FAIL C_NEG"); bad = bad + 1 }
    if C_NEGLIT != 0 - 1 { println("FAIL C_NEGLIT"); bad = bad + 1 }
    if C_SUM != 2 { println("FAIL C_SUM"); bad = bad + 1 }
    if C_MULP != 20 { println("FAIL C_MULP"); bad = bad + 1 }
    if C_PREC != 14 { println("FAIL C_PREC"); bad = bad + 1 }
    if C_SHL != 8 { println("FAIL C_SHL"); bad = bad + 1 }
    if C_SHR != 16 { println("FAIL C_SHR"); bad = bad + 1 }
    if C_REM != 3 { println("FAIL C_REM"); bad = bad + 1 }
    if C_AND != 2 { println("FAIL C_AND"); bad = bad + 1 }
    if C_OR != 7 { println("FAIL C_OR"); bad = bad + 1 }
    if C_XOR != 5 { println("FAIL C_XOR"); bad = bad + 1 }
    if C_BIG != 0 - 800001 { println("FAIL C_BIG"); bad = bad + 1 }
    if C_CHAIN != 0 - 2 { println("FAIL C_CHAIN"); bad = bad + 1 }
    // The e-graph consequence, in miniature: an id of 0 must NOT compare equal to the sentinel.
    let id: i64 = 0
    if id == C_NEG { println("FAIL sentinel: 0 == C_NEG"); bad = bad + 1 }
    if bad == 0 { println("module_let_const_expr: OK") }
    bad as i32
}

