//@ run-pass
// PBPK Validation: 2-compartment Euler model vs analytical Bateman equation
//
// Model: Dose → Gut (absorption) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dCentral/dt = ka * Gut - ke * Central
//
// Analytical (Bateman equation):
//   Gut(t)     = Dose * exp(-ka * t)
//   Central(t) = Dose * ka / (ka - ke) * (exp(-ke * t) - exp(-ka * t))
//   AUC(0→∞)   = Dose / ke  (for complete absorption)
//
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.1h, 240 steps (24h)

struct PBPKState {
    t: f64,
    gut: f64,
    central: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn euler_step(s: PBPKState, dt: f64) -> PBPKState with Mut {
    let ka = 1.0
    let ke = 0.1
    let d_gut = -ka * s.gut
    let d_central = ka * s.gut - ke * s.central
    let new_central = s.central + d_central * dt

    // Track Cmax/Tmax
    let new_t = s.t + dt
    var cmax = s.cmax
    var tmax = s.tmax
    if new_central > s.cmax {
        cmax = new_central
        tmax = new_t
    }

    PBPKState {
        t: new_t,
        gut: s.gut + d_gut * dt,
        central: new_central,
        auc: s.auc + s.central * dt,
        cmax: cmax,
        tmax: tmax
    }
}

fn main() -> i32 with IO, Div, Mut {
    var s = PBPKState {
        t: 0.0, gut: 500.0, central: 0.0,
        auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.1
    var i = 0

    while i < 240 {
        s = euler_step(s, dt)
        i = i + 1
    }

    // Print results for validation
    println(s.t)
    println(s.gut)
    println(s.central)
    println(s.auc)
    println(s.cmax)
    println(s.tmax)

    // Validate against analytical expectations:
    //
    // 1. Time should be 24.0h
    if s.t < 23.9 { return 1 }
    if s.t > 24.1 { return 2 }

    // 2. Gut should be ~0 (exp(-24) ≈ 1.9e-11)
    if s.gut > 0.01 { return 3 }

    // 3. Central: Bateman at t=24h
    //    C(24) = 500 * 1.0/(1.0-0.1) * (exp(-0.1*24) - exp(-1.0*24))
    //          = 555.56 * (exp(-2.4) - exp(-24))
    //          = 555.56 * (0.0907 - ~0)
    //          = ~50.4 mg
    //    Euler with dt=0.1 will be close but not exact
    if s.central < 30.0 { return 4 }
    if s.central > 70.0 { return 5 }

    // 4. AUC should be substantial (analytical AUC_0-inf = Dose/ke = 5000)
    //    But we only integrate to 24h, so expect ~4000-5000
    if s.auc < 3000.0 { return 6 }
    if s.auc > 6000.0 { return 7 }

    // 5. Cmax should be ~200-300 mg (depends on ka/ke ratio)
    //    Analytical Cmax at tmax = ln(ka/ke)/(ka-ke) = ln(10)/0.9 ≈ 2.56h
    //    Cmax = 500*(1.0/0.9)*(0.1^(0.1/0.9) - 0.1^(1.0/0.9))
    //    Euler approximation: should be in ballpark
    if s.cmax < 100.0 { return 8 }
    if s.cmax > 400.0 { return 9 }

    // 6. Tmax should be near 2.56h (analytical)
    if s.tmax < 1.5 { return 10 }
    if s.tmax > 4.0 { return 11 }

    return 0
}

//@ run-pass
// PBPK Validation: 3-compartment RK2 model with higher-order accuracy
//
// Model: Gut → Liver (first-pass) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dLiver/dt   = ka * Gut * fa - (Q_h/V_h) * Liver - CL_h * Liver
//   dCentral/dt = (Q_h/V_h) * Liver - ke * Central
//
// Uses RK2 (midpoint method) for 2nd-order accuracy
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.05h, 480 steps (24h)

struct Conc {
    gut: f64,
    liver: f64,
    central: f64
}

struct SimState {
    state: Conc,
    t: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn derivatives(s: Conc) -> Conc {
    let ka = 1.0
    let fa = 0.8
    let q_h = 0.5
    let cl_h = 0.3
    let ke = 0.1
    Conc {
        gut: -ka * s.gut,
        liver: ka * s.gut * fa - q_h * s.liver - cl_h * s.liver,
        central: q_h * s.liver - ke * s.central
    }
}

fn rk2_step(s: Conc, dt: f64) -> Conc {
    // k1 = f(y_n)
    let k1 = derivatives(s)

    // midpoint: y_mid = y_n + 0.5*dt*k1
    let mid = Conc {
        gut: s.gut + 0.5 * dt * k1.gut,
        liver: s.liver + 0.5 * dt * k1.liver,
        central: s.central + 0.5 * dt * k1.central
    }

    // k2 = f(y_mid)
    let k2 = derivatives(mid)

    // y_{n+1} = y_n + dt * k2
    Conc {
        gut: s.gut + dt * k2.gut,
        liver: s.liver + dt * k2.liver,
        central: s.central + dt * k2.central
    }
}

fn main() -> i32 with IO, Div, Mut {
    var sim = SimState {
        state: Conc { gut: 500.0, liver: 0.0, central: 0.0 },
        t: 0.0, auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.05
    var i = 0

    while i < 480 {
        let new_state = rk2_step(sim.state, dt)
        let new_t = sim.t + dt

        // Trapezoidal AUC
        let auc_increment = 0.5 * (sim.state.central + new_state.central) * dt

        var cmax = sim.cmax
        var tmax = sim.tmax
        if new_state.central > sim.cmax {
            cmax = new_state.central
            tmax = new_t
        }

        sim = SimState {
            state: new_state,
            t: new_t,
            auc: sim.auc + auc_increment,
            cmax: cmax,
            tmax: tmax
        }
        i = i + 1
    }

    // Print results
    println(sim.t)
    println(sim.state.gut)
    println(sim.state.liver)
    println(sim.state.central)
    println(sim.auc)
    println(sim.cmax)
    println(sim.tmax)

    // Validate:
    // 1. Time = 24.0h
    if sim.t < 23.9 { return 1 }

    // 2. Gut fully absorbed (exp(-24) ≈ 0)
    if sim.state.gut > 0.01 { return 2 }

    // 3. AUC should be positive and substantial
    if sim.auc < 100.0 { return 3 }

    // 4. Cmax > 0 (drug reached central compartment)
    if sim.cmax < 10.0 { return 4 }

    // 5. Tmax in physiological range (1-8h for oral absorption)
    if sim.tmax < 0.5 { return 5 }
    if sim.tmax > 12.0 { return 6 }

    // 6. All concentrations non-negative (conservation of mass)
    if sim.state.gut < 0.0 { return 7 }
    if sim.state.liver < 0.0 { return 8 }
    if sim.state.central < 0.0 { return 9 }

    // 7. 480 iterations completed
    if i != 480 { return 10 }

    return 0
}

//@ run-pass
//@ expect-stdout: ALL PASS
//
// L0 acceptance for the perturbation DAG (stdlib/epistemic/perturbation_graph.sio):
// binary chaining of uncertain octonion products is ORDER-SAFE — the structural
// (non-associativity) variance is accumulated automatically regardless of how the
// product is parenthesized, so ((a·b)·c) and (a·(b·c)) agree, and both match the
// explicit mul3.
//
// Operands: unit basis octonions (norm²=1), σ=0.5 (var=0.25), κ=1.
//   non-Fano (e1,e2,e4): measurement 0.75 + κ·‖α‖²(=4) = 4.75 (either association)
//   Fano     (e1,e2,e3): measurement 0.75 + 0              = 0.75
// The order-naive value-only binary would drop the structural term → 0.75 (wrong).

use epistemic::perturbation_graph::{PerturbGraph, pg_new, pg_leaf, pg_mul, pg_variance}
use algebra::octonion::oct_basis

fn approx(x: f64, y: f64) -> bool {
    let d = if x > y { x - y } else { y - x }
    d < 0.0001
}

fn main() with Mut, Div, Panic, NonAssoc {
    var ok = true
    let e1 = oct_basis(1)
    let e2 = oct_basis(2)
    let e3 = oct_basis(3)
    let e4 = oct_basis(4)

    // non-Fano, LEFT-associated: (a·b)·c
    var g = pg_new()
    let a  = pg_leaf(&!g, &e1, 0.5)
    let b  = pg_leaf(&!g, &e2, 0.5)
    let c  = pg_leaf(&!g, &e4, 0.5)
    let ab  = pg_mul(&!g, a, b, 1.0)
    let abc = pg_mul(&!g, ab, c, 1.0)
    let v_left = pg_variance(&!g, abc)
    if approx(v_left, 4.75) { print("LEFT (ab)c = 4.75: PASS") }
    else { print("LEFT: FAIL"); ok = false }

    // non-Fano, RIGHT-associated: a·(b·c) — must match
    var g2 = pg_new()
    let a2 = pg_leaf(&!g2, &e1, 0.5)
    let b2 = pg_leaf(&!g2, &e2, 0.5)
    let c2 = pg_leaf(&!g2, &e4, 0.5)
    let bc   = pg_mul(&!g2, b2, c2, 1.0)
    let abc2 = pg_mul(&!g2, a2, bc, 1.0)
    let v_right = pg_variance(&!g2, abc2)
    if approx(v_right, 4.75) { print("RIGHT a(bc) = 4.75: PASS") }
    else { print("RIGHT: FAIL"); ok = false }

    if approx(v_left, v_right) { print("order-safe: left == right: PASS") }
    else { print("order-safe: FAIL"); ok = false }

    // Fano triple pays nothing
    var g3 = pg_new()
    let fa = pg_leaf(&!g3, &e1, 0.5)
    let fb = pg_leaf(&!g3, &e2, 0.5)
    let fc = pg_leaf(&!g3, &e3, 0.5)
    let fab  = pg_mul(&!g3, fa, fb, 1.0)
    let fabc = pg_mul(&!g3, fab, fc, 1.0)
    if approx(pg_variance(&!g3, fabc), 0.75) { print("Fano chain = 0.75: PASS") }
    else { print("Fano: FAIL"); ok = false }

    if ok { print("ALL PASS") } else { print("SOME FAIL") }
}

//@ run-pass
// PK Domain Uncertainty Plugin Test Suite
//
// Validates WS2 Track 5 — PK-specific uncertainty analysis:
//   1.  Clearance dominance detection (CL contributes >70%)
//   2.  Volume dominance detection (V contributes most)
//   3.  Balanced contributions (no single dominant)
//   4.  SCr as proxy for clearance (Cockcroft-Gault scenario)
//   5.  Sensitivity index S_Ti > 0.7 triggers clearance dominance flag
//   6.  PK recommendations: clearance dominant -> TDM
//   7.  PK recommendations: absorption dominant -> bioequivalence
//   8.  Clinical significance: uncertainty > therapeutic window
//   9.  Clinical significance: uncertainty < therapeutic window
//  10.  Edge case: single parameter is 100% dominant
//  11.  Recommendation for SCr dominant -> cystatin C
//  12.  Sensitivity indices sum to 1.0
//
// Reference: Saltelli et al. (2008), FDA PopPK Guidance (2022)

// ============================================================================
// HELPERS
// ============================================================================

fn abs_val(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn sqrt_val(x: f64) -> f64 with Mut, Div {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    if guess < 0.001 { guess = 0.001 }
    var i = 0
    while i < 30 {
        guess = (guess + x / guess) / 2.0
        i = i + 1
    }
    return guess
}

// ============================================================================
// FLAT PKProfile STRUCT
// No nested structs — all parameter data in flat arrays.
// ============================================================================

struct PKProfile {
    n_params: i64,
    p_code: [i64; 8],
    p_value: [f64; 8],
    p_std_uncert: [f64; 8],
    p_sensitivity: [f64; 8],
    p_contribution: [f64; 8],
    p_source_type: [i64; 8],
    combined_variance: f64,
    combined_std_uncert: f64,
    clearance_contribution: f64,
    volume_contribution: f64,
    absorption_contribution: f64,
    is_cl_dominant: i64,
    dominant_idx: i64,
    dominant_pct: f64,
    r0: i64,
    r1: i64,
    r2: i64,
    r3: i64,
    n_rec: i64
}

fn empty_profile() -> PKProfile {
    PKProfile {
        n_params: 0,
        p_code: [0; 8],
        p_value: [0.0; 8],
        p_std_uncert: [0.0; 8],
        p_sensitivity: [0.0; 8],
        p_contribution: [0.0; 8],
        p_source_type: [0; 8],
        combined_variance: 0.0,
        combined_std_uncert: 0.0,
        clearance_contribution: 0.0,
        volume_contribution: 0.0,
        absorption_contribution: 0.0,
        is_cl_dominant: 0,
        dominant_idx: 0,
        dominant_pct: 0.0,
        r0: 0, r1: 0, r2: 0, r3: 0,
        n_rec: 0
    }
}

fn set_param(profile: PKProfile, idx: i64, code: i64, value: f64, std_uncert: f64, sensitivity: f64, source_type: i64) -> PKProfile with Mut {
    var r = profile
    let contrib = sensitivity * sensitivity * std_uncert * std_uncert
    r.p_code[idx as usize] = code
    r.p_value[idx as usize] = value
    r.p_std_uncert[idx as usize] = std_uncert
    r.p_sensitivity[idx as usize] = sensitivity
    r.p_contribution[idx as usize] = contrib
    r.p_source_type[idx as usize] = source_type
    return r
}

// ============================================================================
// FLAT PKSens STRUCT
// ============================================================================

struct PKSens {
    s_ti: [f64; 8],
    s_i: [f64; 8],
    n_params: i64,
    dom_idx: i64,
    dom_s_ti: f64,
    cl_dominant: i64
}

fn empty_sens() -> PKSens {
    PKSens {
        s_ti: [0.0; 8],
        s_i: [0.0; 8],
        n_params: 0,
        dom_idx: 0,
        dom_s_ti: 0.0,
        cl_dominant: 0
    }
}

// ============================================================================
// PARAMETER CLASSIFICATION
// ============================================================================

fn is_cl(code: i64) -> bool {
    if code == 0 { return true }
    if code == 3 { return true }
    if code == 7 { return true }
    if code == 6 { return true }
    return false
}

fn is_vol(code: i64) -> bool {
    if code == 1 { return true }
    if code == 6 { return true }
    return false
}

fn is_abs(code: i64) -> bool {
    if code == 2 { return true }
    if code == 4 { return true }
    return false
}

// ============================================================================
// ANALYSIS FUNCTIONS
// ============================================================================

fn compute_contributions(profile: PKProfile, n: i64) -> PKProfile with Mut, Div {
    var r = profile
    r.n_params = n

    var total: f64 = 0.0
    var i = 0
    while i < n {
        total = total + r.p_contribution[i as usize]
        i = i + 1
    }

    r.combined_variance = total
    r.combined_std_uncert = sqrt_val(total)

    if total < 1.0e-15 {
        return r
    }

    var cl: f64 = 0.0
    var v: f64 = 0.0
    var ab: f64 = 0.0
    var best_idx = 0
    var best_pct: f64 = 0.0

    i = 0
    while i < n {
        let contrib = r.p_contribution[i as usize]
        let code = r.p_code[i as usize]
        let pct = 100.0 * contrib / total

        if pct > best_pct {
            best_pct = pct
            best_idx = i
        }
        if is_cl(code) { cl = cl + pct }
        if is_vol(code) { v = v + pct }
        if is_abs(code) { ab = ab + pct }

        i = i + 1
    }

    r.clearance_contribution = cl
    r.volume_contribution = v
    r.absorption_contribution = ab
    r.dominant_idx = best_idx
    r.dominant_pct = best_pct

    if cl > 70.0 {
        r.is_cl_dominant = 1
    } else {
        r.is_cl_dominant = 0
    }

    return r
}

fn compute_sensitivity(profile: PKProfile, n: i64) -> PKSens with Mut, Div {
    var r = empty_sens()
    r.n_params = n

    var total: f64 = 0.0
    var i = 0
    while i < n {
        total = total + profile.p_contribution[i as usize]
        i = i + 1
    }

    if total < 1.0e-15 {
        return r
    }

    var best_idx = 0
    var best_s_ti: f64 = 0.0

    i = 0
    while i < n {
        let s_ti = profile.p_contribution[i as usize] / total
        r.s_ti[i as usize] = s_ti
        r.s_i[i as usize] = s_ti
        if s_ti > best_s_ti {
            best_s_ti = s_ti
            best_idx = i
        }
        i = i + 1
    }

    r.dom_idx = best_idx
    r.dom_s_ti = best_s_ti

    var cl_total: f64 = 0.0
    i = 0
    while i < n {
        if is_cl(profile.p_code[i as usize]) {
            cl_total = cl_total + profile.p_contribution[i as usize] / total
        }
        i = i + 1
    }

    if cl_total > 0.7 {
        r.cl_dominant = 1
    } else {
        r.cl_dominant = 0
    }

    return r
}

fn generate_rec(profile: PKProfile) -> PKProfile with Mut, Div {
    var r = profile
    var n_rec = 0

    if profile.is_cl_dominant != 0 {
        if n_rec == 0 { r.r0 = 10 }
        else if n_rec == 1 { r.r1 = 10 }
        else if n_rec == 2 { r.r2 = 10 }
        else if n_rec == 3 { r.r3 = 10 }
        n_rec = n_rec + 1
    }

    if profile.volume_contribution > 50.0 {
        if n_rec == 0 { r.r0 = 11 }
        else if n_rec == 1 { r.r1 = 11 }
        else if n_rec == 2 { r.r2 = 11 }
        else if n_rec == 3 { r.r3 = 11 }
        n_rec = n_rec + 1
    }

    if profile.absorption_contribution > 50.0 {
        if n_rec == 0 { r.r0 = 12 }
        else if n_rec == 1 { r.r1 = 12 }
        else if n_rec == 2 { r.r2 = 12 }
        else if n_rec == 3 { r.r3 = 12 }
        n_rec = n_rec + 1
    }

    if profile.is_cl_dominant != 0 {
        var scr_pct: f64 = 0.0
        var i = 0
        while i < profile.n_params {
            if profile.p_code[i as usize] == 7 {
                if profile.combined_variance > 1.0e-15 {
                    scr_pct = 100.0 * profile.p_contribution[i as usize] / profile.combined_variance
                }
            }
            i = i + 1
        }
        if scr_pct > 20.0 {
            if n_rec < 4 {
                if n_rec == 0 { r.r0 = 13 }
                else if n_rec == 1 { r.r1 = 13 }
                else if n_rec == 2 { r.r2 = 13 }
                else if n_rec == 3 { r.r3 = 13 }
                n_rec = n_rec + 1
            }
        }
    }

    if profile.combined_std_uncert > 0.0 {
        let dom_val = profile.p_value[profile.dominant_idx as usize]
        if abs_val(dom_val) > 1.0e-15 {
            let rel_uncert = 100.0 * profile.combined_std_uncert / abs_val(dom_val)
            if rel_uncert > 30.0 {
                if n_rec < 4 {
                    if n_rec == 0 { r.r0 = 14 }
                    else if n_rec == 1 { r.r1 = 14 }
                    else if n_rec == 2 { r.r2 = 14 }
                    else if n_rec == 3 { r.r3 = 14 }
                    n_rec = n_rec + 1
                }
            }
        }
    }

    if n_rec > 4 { r.n_rec = 4 } else { r.n_rec = n_rec }
    return r
}

fn pk_analyze(profile: PKProfile, n: i64) -> PKProfile with Mut, Div {
    var r = compute_contributions(profile, n)
    r = generate_rec(r)
    return r
}

fn is_clinically_sig(profile: PKProfile, tw: f64) -> i64 with Div {
    if tw <= 1.0 { return 1 }
    let half_width = 2.0 * profile.combined_std_uncert
    let dom_val = profile.p_value[profile.dominant_idx as usize]
    if abs_val(dom_val) < 1.0e-15 { return 1 }
    let rel_half = half_width / abs_val(dom_val)
    let margin = 1.0 - 1.0 / tw
    if rel_half > margin { return 1 }
    return 0
}

