fn scatter3d_add_point(s: &!Scatter3D, xv: f64, yv: f64, zv: f64) with Mut {
    if s.n < 512 {
        s.x[s.n as usize] = xv
        s.y[s.n as usize] = yv
        s.z[s.n as usize] = zv
