    let n = 1000
    let upper = 10.0
    let h = upper / (n as f64)
    var sum = 0.0
    var i = 0
    while i <= n {
        let x = (i as f64) * h
        let fx = x * exponential_pdf(d, x)
        if i == 0 || i == n {
            sum = sum + 0.5 * fx
        } else {
            sum = sum + fx
        }
        i = i + 1
    }
    let integral = sum * h
    let expected = 1.0 / 2.0
    print("  integral=")
    println(integral)
    print("  expected=")
    println(expected)
    return approx_eq(integral, expected, 0.01)
}

