//@ run-pass
//@ description: effectful call fused with an array read in one let evaluates ONCE (#1569)
// #1569: the legacy scalar-variance algebra in lower_expr_variance_ref
// re-lowered operand VALUES to feed emit_variance_independent_product/div.
// When the operand held an effectful call, the call ran TWICE per
// evaluation, so `let d = W[k] * (rng_next() % 10000)` advanced the PRNG
// twice per iteration on Madaros and the stream diverged from lean_single.
// The fix skips the value re-lowering whenever an operand subtree may
// contain a call (variance of a call result is untracked anyway).
//
// Witness: the same computation runs fused (the #1569 shape) and hoisted
// (call in its own let); the two sequences must match element for element.
// Integer arithmetic only, so the pin is exact on every engine. The global
// array is zero-initialised and runtime-assigned on purpose — a separate,
// pre-existing lean_single defect reads literal-initialised GLOBAL arrays
// as element 0 in fused expressions (out of scope here; see the #1569
// discussion), so a literal initialiser would pin the WRONG value on lean.

var RNG_A: i64 = 0
var RNG_B: i64 = 0
var W: [i64; 7] = [0; 7]

fn rng_seed(a: i64, b: i64) with Mut {
    RNG_A = a
    RNG_B = b
}

fn rng_next() -> i64 with Mut {
    var x = RNG_A
    let y = RNG_B
    RNG_A = y
    x = x ^ (x << 23)
    x = x ^ (x >> 17)
    x = x ^ (y ^ (y >> 26))
    RNG_B = x
    let r = x + y
    if r < 0 { 0 - r } else { r }
}

fn fill_w() with Mut {
    W[0] = 10
    W[1] = 20
    W[2] = 30
    W[3] = 40
    W[4] = 50
    W[5] = 60
    W[6] = 70
}

fn main() -> i64 with Mut, Div {
    fill_w()
    var F: [i64; 7] = [0; 7]
    var G: [i64; 7] = [0; 7]

    // pass 1 (fused mul): the exact #1569 shape
    rng_seed(314159265, 271828182)
    var k: i64 = 0
    while k < 7 {
        let d = W[k] * (rng_next() % 10000)
        F[k] = d
        k = k + 1
    }
    // pass 2 (hoisted mul): same stream, call in its own statement
    rng_seed(314159265, 271828182)
    k = 0
    while k < 7 {
        let u = rng_next() % 10000
        let d = W[k] * u
        if d != F[k] { return 10 + k }
        k = k + 1
    }

    // pass 3 (fused div): the OpDiv arm of the same defect
    rng_seed(314159265, 271828182)
    k = 0
    while k < 7 {
        let q = 1000000 / (1 + rng_next() % 1000)
        G[k] = q
        k = k + 1
    }
    // pass 4 (hoisted div)
    rng_seed(314159265, 271828182)
    k = 0
    while k < 7 {
        let u = rng_next() % 1000
        let q = 1000000 / (1 + u)
        if q != G[k] { return 100 + k }
        k = k + 1
    }
    return 0
}

//@ run-pass
// root_finding.sio - Integration tests for root-finding algorithms
//
// Self-contained test suite validating bisection, Newton-Raphson, secant,
// fixed-point iteration, Brent's method, and Halley's method.
// All structs and algorithms are inlined since tests cannot import.
//
// References:
//   Numerical Recipes (Press et al.), Burden & Faires "Numerical Analysis"

// ============================================================================
// PURE HELPERS (must precede callers)
// ============================================================================

fn abs_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x < 0.0 { 0.0 - x } else { x }
}

fn sqrt_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    var g = x / 2.0
    if g < 1.0 { g = 1.0 }
    var i = 0
    while i < 60 { g = (g + x / g) / 2.0; i = i + 1 }
    g
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool with Mut, Panic, Div {
    abs_f64(a - b) < tol
}

// ============================================================================
// TRIGONOMETRIC HELPERS (pure implementations)
// ============================================================================

fn floor_f64(x: f64) -> f64 with Mut, Panic, Div {
    let i = x as i32
    let f = i as f64
    if x < 0.0 && f != x { f - 1.0 } else { f }
}

fn sin_f64(x: f64) -> f64 with Mut, Panic, Div {
    let pi = 3.141592653589793
    let two_pi = 6.283185307179586
    var t = x - floor_f64(x / two_pi) * two_pi
    if t > pi { t = t - two_pi }
    if t < 0.0 - pi { t = t + two_pi }
    var sum = t
    var term = t
    var n = 1
    while n <= 20 {
        term = 0.0 - term * t * t / (((2 * n) as f64) * ((2 * n + 1) as f64))
        sum = sum + term
        n = n + 1
    }
    sum
}

fn cos_f64(x: f64) -> f64 with Mut, Panic, Div {
    sin_f64(x + 1.5707963267948966)
}

// ============================================================================
// DATA STRUCTURE
// ============================================================================

struct RootResult {
    root: f64,
    iterations: i32,
    converged: bool,
    function_value: f64,
}

fn root_success(root: f64, iterations: i32, fval: f64) -> RootResult with Mut, Panic {
    RootResult { root: root, iterations: iterations, converged: true, function_value: fval }
}

fn root_failure(root: f64, iterations: i32, fval: f64) -> RootResult with Mut, Panic {
    RootResult { root: root, iterations: iterations, converged: false, function_value: fval }
}

// ============================================================================
// BISECTION METHOD
// ============================================================================

fn bisection(a: f64, b: f64, tol: f64, max_iter: i32, f: fn(f64) -> f64) -> RootResult with Mut, Panic, Div {
    var lo = a
    var hi = b
    var f_lo = f(lo)
    var f_hi = f(hi)

    // Check if endpoints bracket a root
    if f_lo * f_hi > 0.0 {
        return root_failure((lo + hi) / 2.0, 0, f_lo)
    }

    // Handle case where endpoint is already a root
    if f_lo == 0.0 {
        return root_success(lo, 0, 0.0)
    }
    if f_hi == 0.0 {
        return root_success(hi, 0, 0.0)
    }

    var iter = 0
    var mid = (lo + hi) / 2.0
    var f_mid = f(mid)

    while iter < max_iter {
        if abs_f64(hi - lo) < tol {
            return root_success(mid, iter, f_mid)
        }

        mid = (lo + hi) / 2.0
        f_mid = f(mid)

        if abs_f64(f_mid) < tol {
            return root_success(mid, iter + 1, f_mid)
        }

        if f_lo * f_mid < 0.0 {
            hi = mid
            f_hi = f_mid
        } else {
            lo = mid
            f_lo = f_mid
        }

        iter = iter + 1
    }

    root_failure(mid, iter, f_mid)
}

// ============================================================================
// NEWTON-RAPHSON METHOD
// ============================================================================

fn newton_raphson(x0: f64, tol: f64, max_iter: i32, f: fn(f64) -> f64, df: fn(f64) -> f64) -> RootResult with Mut, Panic, Div {
    var x = x0
    var iter = 0

    while iter < max_iter {
        let fx = f(x)

        if abs_f64(fx) < tol {
            return root_success(x, iter, fx)
        }

        let dfx = df(x)

        // Check for zero derivative
        if dfx == 0.0 {
            return root_failure(x, iter, fx)
        }

        x = x - fx / dfx
        iter = iter + 1
    }

    let final_fx = f(x)
    root_failure(x, iter, final_fx)
}

// ============================================================================
// SECANT METHOD
// ============================================================================

fn secant(x0: f64, x1: f64, tol: f64, max_iter: i32, f: fn(f64) -> f64) -> RootResult with Mut, Panic, Div {
    var x_prev = x0
    var x_curr = x1
    var f_prev = f(x_prev)
    var f_curr = f(x_curr)
    var iter = 0

    while iter < max_iter {
        if abs_f64(f_curr) < tol {
            return root_success(x_curr, iter, f_curr)
        }

        let denom = f_curr - f_prev
        if denom == 0.0 {
            return root_failure(x_curr, iter, f_curr)
        }

        let x_next = x_curr - f_curr * (x_curr - x_prev) / denom

        x_prev = x_curr
        f_prev = f_curr
        x_curr = x_next
        f_curr = f(x_curr)

        iter = iter + 1
    }

    root_failure(x_curr, iter, f_curr)
}

// ============================================================================
// FIXED-POINT ITERATION
// ============================================================================

fn fixed_point(x0: f64, tol: f64, max_iter: i32, g: fn(f64) -> f64) -> RootResult with Mut, Panic, Div {
    var x = x0
    var iter = 0

    while iter < max_iter {
        let x_new = g(x)

        if abs_f64(x_new - x) < tol {
            return root_success(x_new, iter + 1, x_new - g(x_new))
        }

        x = x_new
        iter = iter + 1
    }

    root_failure(x, iter, x - g(x))
}

// ============================================================================
// BRENT'S METHOD
// ============================================================================

fn brent(a: f64, b: f64, tol: f64, max_iter: i32, f: fn(f64) -> f64) -> RootResult with Mut, Panic, Div {
    var lo = a
    var hi = b
    var f_lo = f(lo)
    var f_hi = f(hi)

    // Check bracket
    if f_lo * f_hi > 0.0 {
        return root_failure((lo + hi) / 2.0, 0, f_lo)
    }

    // Ensure |f(lo)| >= |f(hi)|
    if abs_f64(f_lo) < abs_f64(f_hi) {
        // Swap
        let tmp = lo
        lo = hi
        hi = tmp
        let tmp_f = f_lo
        f_lo = f_hi
        f_hi = tmp_f
    }

    var c = lo
    var f_c = f_lo
    var d = hi - lo
    var e = d

    var iter = 0
    while iter < max_iter {
        if abs_f64(f_hi) < tol {
            return root_success(hi, iter, f_hi)
        }

        if abs_f64(hi - lo) < tol {
            return root_success(hi, iter, f_hi)
        }

        var use_bisection = true
        var s = 0.0

        // Try inverse quadratic interpolation if we have 3 distinct points
        if f_lo != f_c && f_hi != f_c {
            // Inverse quadratic interpolation
            let r = f_hi / f_c
            let q = f_lo / f_c
            let p = f_hi / f_lo
            s = p * (q * (r - q) * (c - hi) - (1.0 - r) * (hi - lo)) / ((q - 1.0) * (r - 1.0) * (p - 1.0))
            s = hi + s
            use_bisection = false
        } else if f_lo != f_hi {
            // Secant method
            s = hi - f_hi * (hi - lo) / (f_hi - f_lo)
            use_bisection = false
        }

        // Check if interpolation is acceptable
        if !use_bisection {
            let cond1 = if lo < hi { s < lo || s > hi } else { s < hi || s > lo }
            let cond2 = abs_f64(s - hi) >= abs_f64(e) / 2.0
            if cond1 || cond2 {
                use_bisection = true
            }
        }

        if use_bisection {
            s = (lo + hi) / 2.0
            e = hi - lo
            d = e
        } else {
            e = d
            d = s - hi
        }

        // Update points
        c = hi
        f_c = f_hi

        let f_s = f(s)

        if f_lo * f_s < 0.0 {
            hi = s
            f_hi = f_s
        } else {
            lo = s
            f_lo = f_s
        }

        // Ensure |f(lo)| >= |f(hi)|
        if abs_f64(f_lo) < abs_f64(f_hi) {
            let tmp = lo
            lo = hi
            hi = tmp
            let tmp_f = f_lo
            f_lo = f_hi
            f_hi = tmp_f
        }

        iter = iter + 1
    }

    root_failure(hi, iter, f_hi)
}

// ============================================================================
// HALLEY'S METHOD
// ============================================================================

fn halley(x0: f64, tol: f64, max_iter: i32, f: fn(f64) -> f64, df: fn(f64) -> f64, d2f: fn(f64) -> f64) -> RootResult with Mut, Panic, Div {
    var x = x0
    var iter = 0

    while iter < max_iter {
        let fx = f(x)

        if abs_f64(fx) < tol {
            return root_success(x, iter, fx)
        }

        let dfx = df(x)
        let d2fx = d2f(x)

        let denom = 2.0 * dfx * dfx - fx * d2fx
        if denom == 0.0 {
            return root_failure(x, iter, fx)
        }

        x = x - 2.0 * fx * dfx / denom
        iter = iter + 1
    }

    let final_fx = f(x)
    root_failure(x, iter, final_fx)
}

