fn res_mix(acc: i64, value: i64, salt: i64) -> i64 with Mod {
    return ((acc * 16777619) + value + salt) % 1000000007
}

fn lit_abs(lit: i64) -> i64 {
    if lit < 0 { return 0 - lit }
    return lit
}

fn lit_complement(a: i64, b: i64) -> i64 {
    if a + b == 0 {
        if a != 0 { return 1 }
    }
    return 0
}

fn active_clause(id: i64, added5: i64, added6: i64, added7: i64) -> i64 {
    if id == 1 { return 1 } // x OR y
    if id == 2 { return 1 } // -x OR z
    if id == 3 { return 1 } // -y
    if id == 4 { return 1 } // -z
    if id == 5 { return added5 } // y OR z
    if id == 6 { return added6 } // z
    if id == 7 { return added7 } // empty
    return 0
}

fn clause_len(id: i64) -> i64 {
    if id == 1 { return 2 }
    if id == 2 { return 2 }
    if id == 3 { return 1 }
    if id == 4 { return 1 }
    if id == 5 { return 2 }
    if id == 6 { return 1 }
    if id == 7 { return 0 }
    return 0 - 1
}

fn clause_lit(id: i64, pos: i64) -> i64 {
    if id == 1 {
        if pos == 0 { return 1 }
        if pos == 1 { return 2 }
    }
    if id == 2 {
        if pos == 0 { return 0 - 1 }
        if pos == 1 { return 3 }
    }
    if id == 3 {
        if pos == 0 { return 0 - 2 }
    }
    if id == 4 {
        if pos == 0 { return 0 - 3 }
    }
    if id == 5 {
        if pos == 0 { return 2 }
        if pos == 1 { return 3 }
    }
    if id == 6 {
