struct MatrixData {
    data: [f64; 4096]
    rows: i64
    cols: i64
}

fn matrix_data_new(rows: i64, cols: i64) -> MatrixData with Mut {
    var r = rows
    var c = cols
    if r < 0 { r = 0 }
    if c < 0 { c = 0 }
    if r * c > 4096 { r = 64; c = 64 }
    MatrixData { data: [0.0; 4096], rows: r, cols: c }
}

fn matrix_data_set(m: MatrixData, row: i64, col: i64, val: f64) -> MatrixData with Mut, Panic {
    var out = m
    if row < 0 { return out }
    if col < 0 { return out }
    if row >= out.rows { return out }
    if col >= out.cols { return out }
    out.data[(row * out.cols + col) as usize] = val
    out
}

fn matrix_data_get(m: MatrixData, row: i64, col: i64) -> f64 with Panic {
    if row < 0 { return 0.0 }
    if col < 0 { return 0.0 }
    if row >= m.rows { return 0.0 }
    if col >= m.cols { return 0.0 }
    m.data[(row * m.cols + col) as usize]
}

