fn k7_walk(kk: i64) -> i64 with Mut, Panic, Div {
    var B = [0; 49]
    var bi = 0
    while bi < 7 {
        var bj = 0
        while bj < 7 {
            if bi != bj { B[(bi * 7 + bj) as usize] = 2 }
            bj = bj + 1
        }
        bi = bi + 1
    }
    var row0 = [0; 7]
    var c = 0
    while c < 7 {
        var sb = 0
        var bt = 0
        while bt < 7 {
            sb = sb + B[(0 * 7 + bt) as usize] * B[(bt * 7 + c) as usize]
            bt = bt + 1
        }
        row0[c as usize] = sb
        c = c + 1
    }
    if kk == 2 { return row0[0 as usize] }
    var acc = 0
    var tt = 0
    while tt < 7 {
        acc = acc + row0[tt as usize] * row0[tt as usize]
        tt = tt + 1
    }
    acc
}

