    return (y1 * a1) + (y2 * a2)
}

fn smt_farkas2_rhs_sum(b1: i64, b2: i64, y1: i64, y2: i64) -> i64 {
    if y1 < 0 { return 0 - 9001 }
    if y2 < 0 { return 0 - 9001 }
    return (y1 * b1) + (y2 * b2)
}

fn smt_farkas2_unsat_check(
    a1: i64,
    b1: i64,
    a2: i64,
    b2: i64,
    y1: i64,
    y2: i64) -> i64 {
    if y1 < 0 { return 0 }
    if y2 < 0 { return 0 }
    let lhs = smt_farkas2_lhs_sum(a1, a2, y1, y2)
    if lhs != 0 { return 0 }
    let rhs = smt_farkas2_rhs_sum(b1, b2, y1, y2)
    if rhs < 0 { return 1 }
    return 0
}

fn main() -> i64 {
    let tiny_unsat = smt_farkas2_unsat_check(1, 0, 0 - 1, 0 - 1, 1, 1)
    if tiny_unsat != 1 { return 1 }

    let wrong_multiplier = smt_farkas2_unsat_check(1, 0, 0 - 1, 0 - 1, 1, 0)
    if wrong_multiplier != 0 { return 2 }

    let nonnegative_rhs = smt_farkas2_unsat_check(1, 0, 0 - 1, 1, 1, 1)
    if nonnegative_rhs != 0 { return 3 }

    let negative_multiplier = smt_farkas2_unsat_check(1, 0, 0 - 1, 0 - 1, 1, 0 - 1)
    if negative_multiplier != 0 { return 4 }

    let lhs = smt_farkas2_lhs_sum(1, 0 - 1, 1, 1)
    if lhs != 0 { return 5 }

    let rhs = smt_farkas2_rhs_sum(0, 0 - 1, 1, 1)
    if rhs != 0 - 1 { return 6 }

    let artifact_fp: i64 = 583104927
    let audit_fp: i64 = 719460238
    let instance_fp: i64 = 284916705
    let certificate_fp: i64 = 640271893
    let proof_family_mask: i64 = 3
    let proof_format_mask: i64 = 5
    let imported_runtime_evidence_mask: i64 = 0
    let public_claim_mask: i64 = 0
    let formal_theorem_ready: i64 = 0
    let microkernel_status: i64 = 100
    let ok_mask: i64 = 1023

    if artifact_fp != 583104927 { return 7 }
    if audit_fp != 719460238 { return 8 }
    if instance_fp != 284916705 { return 9 }
    if certificate_fp != 640271893 { return 10 }
    if proof_family_mask != 3 { return 11 }
    if proof_format_mask != 5 { return 12 }
    if imported_runtime_evidence_mask != 0 { return 13 }
    if public_claim_mask != 0 { return 14 }
    if formal_theorem_ready != 0 { return 15 }
    if microkernel_status != 100 { return 16 }
    if ok_mask != 1023 { return 17 }
    return 0
}

//@ run-pass
//@ description: QF_LIA Fourier-Motzkin SMT solver — basic satisfiability tests

// ── Solver inlined (global-array design, avoids struct-in-struct JIT bug) ────

fn fm_result_unknown() -> i64 { 0 }
fn fm_result_sat()     -> i64 { 1 }
fn fm_result_unsat()   -> i64 { 2 }

fn fm_op_gt()    -> i64 { 1 }
fn fm_op_gt_eq() -> i64 { 2 }
fn fm_op_lt()    -> i64 { 3 }
fn fm_op_lt_eq() -> i64 { 4 }
fn fm_op_eq()    -> i64 { 5 }
fn fm_op_neq()   -> i64 { 6 } with Mut

// Flat global constraint store.  Constraint i, var slot j → index i*8+j.
// Variable IDs stored as vid+1; 0 means empty slot.
var FM_COEFFS: [i64; 256] = [0; 256]
var FM_VARIDS: [i64; 256] = [0; 256]
var FM_NVARS:  [i64; 32]  = [0; 32]
var FM_CONSTS: [i64; 32]  = [0; 32]
var FM_STRICT: [i64; 32]  = [0; 32]
var FM_NINEQS: i64         = 0

var FM2_COEFFS: [i64; 256] = [0; 256]
var FM2_VARIDS: [i64; 256] = [0; 256]
var FM2_NVARS:  [i64; 32]  = [0; 32]
var FM2_CONSTS: [i64; 32]  = [0; 32]
var FM2_STRICT: [i64; 32]  = [0; 32]
var FM2_NINEQS: i64         = 0

var FM_VARLIST:  [i64; 8] = [0; 8]
var FM_VARCOUNT: i64 = 0

fn fm_reset() with Mut {
    var i: i64 = 0
    while i < 256 { FM_COEFFS[i as usize] = 0; FM_VARIDS[i as usize] = 0; i = i + 1 }
    i = 0
    while i < 32 { FM_NVARS[i as usize] = 0; FM_CONSTS[i as usize] = 0; FM_STRICT[i as usize] = 0; i = i + 1 }
    FM_NINEQS = 0
}

fn fm2_reset() with Mut {
    var i: i64 = 0
    while i < 256 { FM2_COEFFS[i as usize] = 0; FM2_VARIDS[i as usize] = 0; i = i + 1 }
    i = 0
    while i < 32 { FM2_NVARS[i as usize] = 0; FM2_CONSTS[i as usize] = 0; FM2_STRICT[i as usize] = 0; i = i + 1 }
    FM2_NINEQS = 0
}

// Return coefficient of var_id in row (primary store)
fn fm_coeff(row: i64, var_id: i64) -> i64 with Mut {
    let nvars = FM_NVARS[row as usize]
    var j: i64 = 0
    while j < nvars {
        if FM_VARIDS[(row * 8 + j) as usize] == var_id + 1 {
            return FM_COEFFS[(row * 8 + j) as usize]
        }
        j = j + 1
    }
    0
}

// Add single-variable constraint to primary store
fn fm_add1(var_id: i64, coeff: i64, constant: i64, is_strict: i64) with Mut {
    if FM_NINEQS >= 32 { return }
    let r = FM_NINEQS as usize
    FM_NVARS[r]      = 1
    FM_CONSTS[r]     = constant
    FM_STRICT[r]     = is_strict
    FM_VARIDS[r * 8] = var_id + 1  // encode
    FM_COEFFS[r * 8] = coeff
    FM_NINEQS = FM_NINEQS + 1
}

// Add two-variable constraint to primary store
fn fm_add2(va: i64, ca: i64, vb: i64, cb: i64, constant: i64, is_strict: i64) with Mut {
    if FM_NINEQS >= 32 { return }
    let r = FM_NINEQS as usize
    FM_NVARS[r]          = 2
    FM_CONSTS[r]         = constant
    FM_STRICT[r]         = is_strict
    FM_VARIDS[r * 8 + 0] = va + 1
    FM_COEFFS[r * 8 + 0] = ca
    FM_VARIDS[r * 8 + 1] = vb + 1
    FM_COEFFS[r * 8 + 1] = cb
    FM_NINEQS = FM_NINEQS + 1
}

// Parse "var_id op constant" into canonical form and add to primary store
// Canonical:  coeff*var + constant ≤ 0  (or < 0 if strict)
//   var > c   →  -var + c < 0   (coeff=-1, const=c, strict)
//   var >= c  →  -var + c ≤ 0
//   var < c   →   var - c < 0   (coeff=+1, const=-c, strict)
//   var <= c  →   var - c ≤ 0
fn fm_parse_pred(var_id: i64, op: i64, constant: i64) with Mut {
    if op == fm_op_gt() {
        fm_add1(var_id, -1, constant, 1)
    } else if op == fm_op_gt_eq() {
        fm_add1(var_id, -1, constant, 0)
    } else if op == fm_op_lt() {
        fm_add1(var_id, 1, 0 - constant, 1)
    } else if op == fm_op_lt_eq() {
        fm_add1(var_id, 1, 0 - constant, 0)
    } else if op == fm_op_eq() {
        fm_add1(var_id, -1, constant, 0)
        fm_add1(var_id,  1, 0 - constant, 0)
    }
}

// Add two-variable constraint: coeff_a*var_a + coeff_b*var_b + constant ≤ 0
fn fm_parse_binvar(var_a: i64, coeff_a: i64, var_b: i64, coeff_b: i64,
                   constant: i64, is_strict: i64) with Mut {
    fm_add2(var_a, coeff_a, var_b, coeff_b, constant, is_strict)
}

fn fm_collect_vars() with Mut {
    FM_VARCOUNT = 0
    var i: i64 = 0
    while i < FM_NINEQS {
        var j: i64 = 0
        while j < FM_NVARS[i as usize] {
            let stored = FM_VARIDS[(i * 8 + j) as usize]
            if stored > 0 {
                let vid = stored - 1
                var found = false; var k: i64 = 0
                while k < FM_VARCOUNT {
                    if FM_VARLIST[k as usize] == vid { found = true }
                    k = k + 1
                }
                if !found && FM_VARCOUNT < 8 {
                    FM_VARLIST[FM_VARCOUNT as usize] = vid
                    FM_VARCOUNT = FM_VARCOUNT + 1
                }
            }
            j = j + 1
        }
        i = i + 1
    }
}

fn fm_is_ground_contradiction(row: i64) -> bool {
    if FM_NVARS[row as usize] != 0 { return false }
    let c = FM_CONSTS[row as usize]
    let s = FM_STRICT[row as usize]
    if s == 1 { return c >= 0 }
    c > 0
}

fn fm_eliminate(var_id: i64) -> i64 with Mut {
    var pos_rows: [i64; 32] = [0; 32]; var npos: i64 = 0
    var neg_rows: [i64; 32] = [0; 32]; var nneg: i64 = 0
    var zer_rows: [i64; 32] = [0; 32]; var nzer: i64 = 0

    var i: i64 = 0
    while i < FM_NINEQS {
        let c = fm_coeff(i, var_id)
        if c > 0 { pos_rows[npos as usize] = i; npos = npos + 1 }
        else if c < 0 { neg_rows[nneg as usize] = i; nneg = nneg + 1 }
        else { zer_rows[nzer as usize] = i; nzer = nzer + 1 }
        i = i + 1
    }

    fm2_reset()

    // Copy zero-coeff rows to FM2
    var z: i64 = 0
    while z < nzer {
        let ri = zer_rows[z as usize]
        let dst = FM2_NINEQS
        FM2_NVARS[dst as usize]  = FM_NVARS[ri as usize]
        FM2_CONSTS[dst as usize] = FM_CONSTS[ri as usize]
        FM2_STRICT[dst as usize] = FM_STRICT[ri as usize]
        var j: i64 = 0
        while j < FM_NVARS[ri as usize] {
            FM2_COEFFS[(dst * 8 + j) as usize] = FM_COEFFS[(ri * 8 + j) as usize]
            FM2_VARIDS[(dst * 8 + j) as usize] = FM_VARIDS[(ri * 8 + j) as usize]
            j = j + 1
        }
        FM2_NINEQS = FM2_NINEQS + 1
        z = z + 1
    }

    // Pairwise derivation
    var pi: i64 = 0
    while pi < npos {
        let pr = pos_rows[pi as usize]
        let cp = fm_coeff(pr, var_id)
        var ni: i64 = 0
        while ni < nneg {
            let nr = neg_rows[ni as usize]
            let cn = fm_coeff(nr, var_id)
            let abs_cn = 0 - cn

            let new_const  = abs_cn * FM_CONSTS[pr as usize] + cp * FM_CONSTS[nr as usize]
            let new_strict = if FM_STRICT[pr as usize] == 1 || FM_STRICT[nr as usize] == 1 { 1 } else { 0 }

            var dv_varids: [i64; 8] = [0; 8]
            var dv_coeffs: [i64; 8] = [0; 8]
            var dv_n: i64 = 0

            // Vars from pos row
            var ti: i64 = 0
            while ti < FM_NVARS[pr as usize] {
                let vid_s = FM_VARIDS[(pr * 8 + ti) as usize]
                let vid   = vid_s - 1
                let cef   = FM_COEFFS[(pr * 8 + ti) as usize]
                if vid_s > 0 && vid != var_id && dv_n < 8 {
                    dv_varids[dv_n as usize] = vid_s
                    dv_coeffs[dv_n as usize] = abs_cn * cef
                    dv_n = dv_n + 1
                }
                ti = ti + 1
            }

            // Vars from neg row (merge or append)
            var ti2: i64 = 0
            while ti2 < FM_NVARS[nr as usize] {
                let vid_s = FM_VARIDS[(nr * 8 + ti2) as usize]
                let vid   = vid_s - 1
                let cef   = FM_COEFFS[(nr * 8 + ti2) as usize]
                if vid_s > 0 && vid != var_id {
                    var found_at: i64 = -1
                    var si: i64 = 0
                    while si < dv_n {
                        if dv_varids[si as usize] == vid_s { found_at = si }
                        si = si + 1
                    }
                    if found_at >= 0 {
                        dv_coeffs[found_at as usize] = dv_coeffs[found_at as usize] + cp * cef
                    } else if dv_n < 8 {
                        dv_varids[dv_n as usize] = vid_s
                        dv_coeffs[dv_n as usize] = cp * cef
                        dv_n = dv_n + 1
                    }
                }
                ti2 = ti2 + 1
            }

            // Count active variables
            var active: i64 = 0
            var ai: i64 = 0
            while ai < dv_n {
                if dv_coeffs[ai as usize] != 0 { active = active + 1 }
                ai = ai + 1
            }

            if active == 0 {
                // Ground constraint
                let contradiction = if new_strict == 1 { new_const >= 0 } else { new_const > 0 }
                if contradiction {
                    FM_NINEQS = 0  // Mark system as done
                    return fm_result_unsat()
                }
                // Trivially satisfied — drop
            } else if FM2_NINEQS < 32 {
                let dst = FM2_NINEQS
                FM2_NVARS[dst as usize]  = active
                FM2_CONSTS[dst as usize] = new_const
                FM2_STRICT[dst as usize] = new_strict
                var si2: i64 = 0; var slot2: i64 = 0
                while si2 < dv_n {
                    if dv_coeffs[si2 as usize] != 0 && slot2 < 8 {
                        FM2_COEFFS[(dst * 8 + slot2) as usize] = dv_coeffs[si2 as usize]
                        FM2_VARIDS[(dst * 8 + slot2) as usize] = dv_varids[si2 as usize]
                        slot2 = slot2 + 1
                    }
                    si2 = si2 + 1
                }
                FM2_NINEQS = FM2_NINEQS + 1
            }
            ni = ni + 1
        }
        pi = pi + 1
    }

    // Copy FM2 back to FM
    FM_NINEQS = FM2_NINEQS
    var ci: i64 = 0
    while ci < FM2_NINEQS {
        FM_NVARS[ci as usize]  = FM2_NVARS[ci as usize]
        FM_CONSTS[ci as usize] = FM2_CONSTS[ci as usize]
        FM_STRICT[ci as usize] = FM2_STRICT[ci as usize]
        var cj: i64 = 0
        while cj < FM2_NVARS[ci as usize] {
            FM_COEFFS[(ci * 8 + cj) as usize] = FM2_COEFFS[(ci * 8 + cj) as usize]
            FM_VARIDS[(ci * 8 + cj) as usize] = FM2_VARIDS[(ci * 8 + cj) as usize]
            cj = cj + 1
        }
        ci = ci + 1
    }
    fm_result_unknown()
}

fn fm_check_sat() -> i64 with Mut {
    if FM_NINEQS == 0 { return fm_result_sat() }
    fm_collect_vars()
    if FM_VARCOUNT == 0 {
        var i: i64 = 0
        while i < FM_NINEQS {
            if fm_is_ground_contradiction(i) { return fm_result_unsat() }
            i = i + 1
        }
        return fm_result_sat()
    }
    var vi: i64 = 0
    while vi < FM_VARCOUNT {
        let r = fm_eliminate(FM_VARLIST[vi as usize])
        if r == fm_result_unsat() { return fm_result_unsat() }
        vi = vi + 1
    }
    var i: i64 = 0
    while i < FM_NINEQS {
        if fm_is_ground_contradiction(i) { return fm_result_unsat() }
        i = i + 1
    }
    fm_result_sat()
}

fn print_int(n: i64) with IO { println(n as i32 as string) }

// ── Tests ─────────────────────────────────────────────────────────────────────

fn main() -> i32 with IO, Mut, Panic {
    var pass: i64 = 0
    var fail: i64 = 0

    // T1: x > 0  AND  x < 5  → SAT
    fm_reset()
    fm_parse_pred(0, fm_op_gt(), 0)   // x > 0
    fm_parse_pred(0, fm_op_lt(), 5)   // x < 5
    let r1 = fm_check_sat()
    if r1 == fm_result_sat() { pass = pass + 1 }
    else { print("T1 FAIL: expected SAT, got "); print_int(r1); fail = fail + 1 }

    // T2: x > 0  AND  x < 0  → UNSAT
    fm_reset()
    fm_parse_pred(0, fm_op_gt(), 0)   // x > 0
    fm_parse_pred(0, fm_op_lt(), 0)   // x < 0
    let r2 = fm_check_sat()
    if r2 == fm_result_unsat() { pass = pass + 1 }
    else { print("T2 FAIL: expected UNSAT, got "); print_int(r2); fail = fail + 1 }

    // T3: x >= 3  AND  x <= 2  → UNSAT
    fm_reset()
    fm_parse_pred(0, fm_op_gt_eq(), 3)  // x >= 3
    fm_parse_pred(0, fm_op_lt_eq(), 2)  // x <= 2
    let r3 = fm_check_sat()
    if r3 == fm_result_unsat() { pass = pass + 1 }
    else { print("T3 FAIL: expected UNSAT, got "); print_int(r3); fail = fail + 1 }

    // T4: x > 0  AND  y > 0  AND  x + y <= 10  → SAT
    fm_reset()
    fm_parse_pred(0, fm_op_gt(), 0)             // x > 0
    fm_parse_pred(1, fm_op_gt(), 0)             // y > 0
    fm_parse_binvar(0, 1, 1, 1, -10, 0)         // x + y - 10 <= 0
    let r4 = fm_check_sat()
    if r4 == fm_result_sat() { pass = pass + 1 }
    else { print("T4 FAIL: expected SAT, got "); print_int(r4); fail = fail + 1 }

    // T5: x + y <= 5  AND  x >= 3  AND  y >= 4  → UNSAT  (3+4=7 > 5)
    fm_reset()
    fm_parse_binvar(0, 1, 1, 1, -5, 0)          // x + y - 5 <= 0
    fm_parse_pred(0, fm_op_gt_eq(), 3)           // x >= 3
    fm_parse_pred(1, fm_op_gt_eq(), 4)           // y >= 4
    let r5 = fm_check_sat()
    if r5 == fm_result_unsat() { pass = pass + 1 }
    else { print("T5 FAIL: expected UNSAT, got "); print_int(r5); fail = fail + 1 }

    if fail == 0 {
        print("smt_qflia_basic: PASS (")
        print_int(pass)
        print("/5)\n")
        return 0
    }
    print("smt_qflia_basic: FAIL (")
    print_int(fail)
    print(" failures)\n")
    return 1 as i32
}

//@ run-pass
// Advanced Sobol sensitivity analysis tests
// Validates Saltelli et al. (2008) methods for second-order indices
// and efficient N(2d+2) sampling scheme.
//
// References:
//   Saltelli, A. et al. (2008) "Global Sensitivity Analysis: The Primer"
//   Ishigami, T. & Homma, T. (1990) "An importance quantification technique
//     in uncertainty analysis for computer models"

extern "C" {
    fn sqrt(x: f64) -> f64;
    fn sin(x: f64) -> f64;
    fn cos(x: f64) -> f64;
    fn log(x: f64) -> f64;
    fn exp(x: f64) -> f64;
}

fn sqrt_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 }
    return sqrt(x)
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn max_f64(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

fn min_f64(a: f64, b: f64) -> f64 {
    if a < b { a } else { b }
}

// ============================================================================
// Van der Corput helper (duplicated here for standalone test compilation)
// ============================================================================

fn reverse_bits(n: i64) -> f64 with Mut {
    var result: f64 = 0.0
    var v = n
    var b: f64 = 0.5
    while v > 0 {
        if (v % 2) == 1 {
            result = result + b
        }
        v = v / 2
        b = b / 2.0
    }
    return result
}

// True Halton sequence: digit reversal in the given prime base
fn halton(n: i64, base: i64) -> f64 with Mut {
    var result: f64 = 0.0
    var f: f64 = 1.0
    var i = n
    while i > 0 {
        f = f / (base as f64)
        result = result + f * ((i % base) as f64)
        i = i / base
    }
    return result
}

// ============================================================================
// Saltelli infrastructure (inline for standalone test)
// ============================================================================

struct SaltelliSamples {
    matrix_a: [f64; 5000],
    matrix_b: [f64; 5000],
    n_samples: i32,
    n_dims: i32,
}

// Primes for A matrix dimensions (first 10 primes)
fn saltelli_dim_prime(d: i32) -> i64 {
    if d == 0 { return 2 }
    if d == 1 { return 3 }
    if d == 2 { return 5 }
    if d == 3 { return 7 }
    if d == 4 { return 11 }
    if d == 5 { return 13 }
    if d == 6 { return 17 }
    if d == 7 { return 19 }
    if d == 8 { return 23 }
    return 29
}

// Primes for B matrix dimensions (next 10 primes, independent Halton dimensions)
fn saltelli_dim_prime_b(d: i32) -> i64 {
    if d == 0 { return 31 }
    if d == 1 { return 37 }
    if d == 2 { return 41 }
    if d == 3 { return 43 }
    if d == 4 { return 47 }
    if d == 5 { return 53 }
    if d == 6 { return 59 }
    if d == 7 { return 61 }
    if d == 8 { return 67 }
    return 71
}

fn saltelli_generate(n_samples: i32, n_dims: i32, seed: i64) -> SaltelliSamples with Mut {
    var result = SaltelliSamples {
        matrix_a: [0.0; 5000],
        matrix_b: [0.0; 5000],
        n_samples: n_samples,
        n_dims: n_dims,
    }

    var actual_samples = n_samples
    if n_dims > 0 {
        let max_rows = 5000 / n_dims
        if actual_samples > max_rows {
            actual_samples = max_rows
        }
    }
    result.n_samples = actual_samples

    var i: i32 = 0
    while i < actual_samples {
        let idx: i64 = (i as i64) + 1 + seed
        var d: i32 = 0
        while d < n_dims {
            let flat = i * n_dims + d
            result.matrix_a[flat] = halton(idx, saltelli_dim_prime(d))
            result.matrix_b[flat] = halton(idx, saltelli_dim_prime_b(d))
            d = d + 1
        }
        i = i + 1
    }

    return result
}

fn saltelli_build_ci(samples: &SaltelliSamples, dim_i: i32) -> [f64; 5000] with Mut {
    var ci: [f64; 5000] = [0.0; 5000]
    var i: i32 = 0
    while i < samples.n_samples {
        var d: i32 = 0
        while d < samples.n_dims {
            let flat = i * samples.n_dims + d
            if d == dim_i {
                ci[flat] = samples.matrix_b[flat]
            } else {
                ci[flat] = samples.matrix_a[flat]
            }
            d = d + 1
        }
        i = i + 1
    }
    return ci
}

fn saltelli_build_cij(samples: &SaltelliSamples, dim_i: i32, dim_j: i32) -> [f64; 5000] with Mut {
    var cij: [f64; 5000] = [0.0; 5000]
    var r: i32 = 0
    while r < samples.n_samples {
        var d: i32 = 0
        while d < samples.n_dims {
            let flat = r * samples.n_dims + d
            if d == dim_i || d == dim_j {
                cij[flat] = samples.matrix_b[flat]
            } else {
                cij[flat] = samples.matrix_a[flat]
            }
            d = d + 1
        }
        r = r + 1
    }
    return cij
}

fn saltelli_eval_row(matrix: &[f64; 5000], row: i32, n_dims: i32, model: fn([f64; 10]) -> f64) -> f64 with Mut {
    var input: [f64; 10] = [0.0; 10]
    var d: i32 = 0
    while d < n_dims {
        if d < 10 {
            input[d] = matrix[row * n_dims + d]
        }
        d = d + 1
    }
    return model(input)
}

fn saltelli_first_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_b: &[f64; 1000],
    model_outputs_ci: &[f64; 1000]
) -> f64 with Mut {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_all: f64 = 0.0
    var sum_sq_all: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_all = sum_all + model_outputs_a[k] + model_outputs_b[k]
        sum_sq_all = sum_sq_all + model_outputs_a[k] * model_outputs_a[k]
                                + model_outputs_b[k] * model_outputs_b[k]
        k = k + 1
    }
    let mean_y = sum_all / (2.0 * nf)
    let var_y = sum_sq_all / (2.0 * nf) - mean_y * mean_y
    if var_y < 1.0e-15 { return 0.0 }

    var numerator: f64 = 0.0
    k = 0
    while k < n {
        numerator = numerator + model_outputs_b[k] * (model_outputs_ci[k] - model_outputs_a[k])
        k = k + 1
    }
    numerator = numerator / nf
    let si = numerator / var_y
    return max_f64(0.0, min_f64(1.0, si))
}

fn saltelli_total_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_ci: &[f64; 1000]
) -> f64 with Mut {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_a: f64 = 0.0
    var sum_sq_a: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_a = sum_a + model_outputs_a[k]
        sum_sq_a = sum_sq_a + model_outputs_a[k] * model_outputs_a[k]
        k = k + 1
    }
    let mean_a = sum_a / nf
    let var_y = sum_sq_a / nf - mean_a * mean_a
    if var_y < 1.0e-15 { return 0.0 }

    var numerator: f64 = 0.0
    k = 0
    while k < n {
        let diff = model_outputs_a[k] - model_outputs_ci[k]
        numerator = numerator + diff * diff
        k = k + 1
    }
    numerator = numerator / (2.0 * nf)
    let sti = numerator / var_y
    return max_f64(0.0, min_f64(1.0, sti))
}

fn saltelli_second_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_b: &[f64; 1000],
    model_outputs_ci: &[f64; 1000],
    model_outputs_cj: &[f64; 1000],
    model_outputs_cij: &[f64; 1000],
    s_i: f64,
    s_j: f64
) -> f64 with Mut {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_all: f64 = 0.0
    var sum_sq_all: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_all = sum_all + model_outputs_a[k] + model_outputs_b[k]
        sum_sq_all = sum_sq_all + model_outputs_a[k] * model_outputs_a[k]
                                + model_outputs_b[k] * model_outputs_b[k]
        k = k + 1
    }
    let mean_y = sum_all / (2.0 * nf)
    let var_y = sum_sq_all / (2.0 * nf) - mean_y * mean_y
    if var_y < 1.0e-15 { return 0.0 }

    var numerator_ij: f64 = 0.0
    k = 0
    while k < n {
        numerator_ij = numerator_ij + model_outputs_b[k] * (model_outputs_cij[k] - model_outputs_a[k])
        k = k + 1
    }
    let s_ij_closed = (numerator_ij / nf) / var_y
    let s_ij = s_ij_closed - s_i - s_j
    return max_f64(-0.05, min_f64(1.0, s_ij))
}

fn saltelli_expected_evals(n_samples: i32, n_dims: i32) -> i32 {
    let base = n_samples * (n_dims + 2)
    let n_pairs = n_dims * (n_dims - 1) / 2
    let second = n_samples * n_pairs
    return base + second
}

// ============================================================================
// TEST 1: Linear model  f(x1, x2) = 2*x1 + x2
// ============================================================================
// For uniform inputs on [0,1]:
//   Var(2*x1) = 4 * Var(x1) = 4/12 = 1/3
//   Var(x2)   = 1/12
//   Total Var = 5/12
//   S1 = (1/3) / (5/12) = 4/5 = 0.8
//   S2 = (1/12) / (5/12) = 1/5 = 0.2
//   S12 = 0  (no interaction in a linear model)

fn linear_model(x: [f64; 10]) -> f64 {
    return 2.0 * x[0] + x[1]
}

fn test_linear_model() -> bool with Mut {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 2, 42)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    // Evaluate on A and B
    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 2, linear_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 2, linear_model)
        k = k + 1
    }

    // C_0: A with column 0 from B
    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 2, linear_model)
        k = k + 1
    }

    // C_1: A with column 1 from B
    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 2, linear_model)
        k = k + 1
    }

    // C_01: A with columns 0 and 1 from B (= B itself for 2D)
    let c01 = saltelli_build_cij(&samples, 0, 1)
    var out_c01: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c01[k] = saltelli_eval_row(&c01, k, 2, linear_model)
        k = k + 1
    }

    // Compute indices
    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)

    let s12 = saltelli_second_order(
        &samples, &out_a, &out_b, &out_c0, &out_c1, &out_c01, s1, s2
    )

    // Check S1 ~ 0.8 within 15% tolerance
    let tol: f64 = 0.15
    var ok = true

    if abs_f64(s1 - 0.8) > tol { ok = false }
    if abs_f64(s2 - 0.2) > tol { ok = false }

    // Total order should approximately equal first order for linear model
    if abs_f64(st1 - 0.8) > tol { ok = false }
    if abs_f64(st2 - 0.2) > tol { ok = false }

    // Interaction should be near zero
    if abs_f64(s12) > 0.1 { ok = false }

    return ok
}

// ============================================================================
// TEST 2: Pure interaction model  f(x1, x2) = x1 * x2
// ============================================================================
// For uniform inputs on [0,1]:
//   E[x1*x2] = 1/4, E[(x1*x2)^2] = 1/9
//   Var(x1*x2) = 1/9 - 1/16 = 7/144
//   V1 = Var_x1(E[x1*x2 | x1]) = Var_x1(x1/2) = 1/48
//   V2 = Var_x2(E[x1*x2 | x2]) = Var_x2(x2/2) = 1/48
//   S1 = S2 = (1/48) / (7/144) = 3/7 ~ 0.4286
//   S12 = 1 - S1 - S2 = 1/7 ~ 0.1429
//
// Note: S1 and S2 are NOT zero for x1*x2 on [0,1] -- the analytical values
// are 3/7 each. The total-order indices are S_T1 = S_T2 = S1 + S12 = 4/7.

fn interaction_model(x: [f64; 10]) -> f64 {
    return x[0] * x[1]
}

fn test_interaction_model() -> bool with Mut {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 2, 137)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 2, interaction_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 2, interaction_model)
        k = k + 1
    }

    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 2, interaction_model)
        k = k + 1
    }

    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 2, interaction_model)
        k = k + 1
    }

    let c01 = saltelli_build_cij(&samples, 0, 1)
    var out_c01: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c01[k] = saltelli_eval_row(&c01, k, 2, interaction_model)
        k = k + 1
    }

    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)

    let s12 = saltelli_second_order(
        &samples, &out_a, &out_b, &out_c0, &out_c1, &out_c01, s1, s2
    )

    // Analytical: S1 = S2 = 3/7 ~ 0.4286
    let tol: f64 = 0.15
    var ok = true

    // First-order indices should be moderate (not zero)
    if s1 < 0.15 { ok = false }
    if s2 < 0.15 { ok = false }

    // Total-order should be larger than first-order (interactions present)
    if st1 < s1 - 0.05 { ok = false }
    if st2 < s2 - 0.05 { ok = false }

    // Second-order interaction should be positive (some interaction variance)
    // Analytical S12 = 1/7 ~ 0.143
    // Allow wide tolerance due to quasi-random noise
    if s12 < -0.05 { ok = false }

    return ok
}

// ============================================================================
// TEST 3: Ishigami function (classic sensitivity analysis benchmark)
// ============================================================================
// f(x1, x2, x3) = sin(x1) + 7*sin^2(x2) + 0.1*x3^4*sin(x1)
// where x_i ~ Uniform[-pi, pi]
//
// Analytical Sobol' indices (a=7, b=0.1):
//   S1 ~ 0.3139,  S_T1 ~ 0.5576
//   S2 ~ 0.4424,  S_T2 ~ 0.4424
//   S3 ~ 0.0,     S_T3 ~ 0.2437
//   S13 ~ 0.2437 (only nonzero second-order interaction)

fn ishigami_model(x: [f64; 10]) -> f64 {
    // Map [0,1] -> [-pi, pi]
    let pi = 3.14159265358979323846
    let x1 = x[0] * 2.0 * pi - pi
    let x2 = x[1] * 2.0 * pi - pi
    let x3 = x[2] * 2.0 * pi - pi

    let sin_x1 = sin(x1)
    let sin_x2 = sin(x2)
    let x3_4 = x3 * x3 * x3 * x3

    return sin_x1 + 7.0 * sin_x2 * sin_x2 + 0.1 * x3_4 * sin_x1
}

fn test_ishigami() -> bool with Mut {
    let n_samples: i32 = 800
    let samples = saltelli_generate(n_samples, 3, 271)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    // Evaluate on A and B
    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 3, ishigami_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 3, ishigami_model)
        k = k + 1
    }

    // Build C_i outputs for each dimension
    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 3, ishigami_model)
        k = k + 1
    }

    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 3, ishigami_model)
        k = k + 1
    }

    let c2 = saltelli_build_ci(&samples, 2)
    var out_c2: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c2[k] = saltelli_eval_row(&c2, k, 3, ishigami_model)
        k = k + 1
    }

    // First-order indices
    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let s3 = saltelli_first_order(&samples, &out_a, &out_b, &out_c2)

    // Total-order indices
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)
    let st3 = saltelli_total_order(&samples, &out_a, &out_c2)

    // Validate with 15% tolerance (Monte Carlo variance)
    let tol: f64 = 0.15
    var ok = true

    // S1 ~ 0.314: x1 has moderate first-order influence
    if abs_f64(s1 - 0.314) > tol { ok = false }

    // S2 ~ 0.442: x2 has the largest first-order influence
    if abs_f64(s2 - 0.442) > tol { ok = false }

    // S3 ~ 0.0: x3 has negligible first-order effect
    if s3 > 0.15 { ok = false }

    // S_T1 ~ 0.558: x1 has large total effect (via interaction with x3)
    if abs_f64(st1 - 0.558) > tol { ok = false }

    // S_T2 ~ 0.442: x2 total = first (no interactions)
    if abs_f64(st2 - 0.442) > tol { ok = false }

    // S_T3 ~ 0.244: x3 only acts through interaction with x1
    if abs_f64(st3 - 0.244) > tol { ok = false }

    return ok
}

// ============================================================================
// TEST 4: N(2d+2) efficiency verification
// ============================================================================
// For d=3, the expected evaluations are:
//   Base:   N * (3 + 2)   = 5N   (A, B, C_0, C_1, C_2)
//   Pairs:  N * C(3,2)    = 3N   (C_01, C_02, C_12)
//   Total:  8N
// Canonical formula: N(2d+2) = N * 8 = 8N  (matches for d=3)

fn test_n2d2_efficiency() -> bool {
    let n: i32 = 100
    let d: i32 = 3

    // Expected: N * (d + 2) + N * d*(d-1)/2 = 100*5 + 100*3 = 800
    let expected = saltelli_expected_evals(n, d)

    // N(2d+2) = 100 * 8 = 800
    let canonical = n * (2 * d + 2)

    // For d=3, the exact formula and the N(2d+2) approximation match exactly
    if expected != canonical { return false }

    // Also check d=2: N*(2+2) + N*1 = 5N; N(2*2+2) = 6N
    // These differ because N(2d+2) is an approximation
    let expected_2d = saltelli_expected_evals(n, 2)
    let exact_2d = n * (2 + 2) + n * 1  // = 500
    if expected_2d != exact_2d { return false }

    // Check d=1: N*(1+2) + N*0 = 3N
    let expected_1d = saltelli_expected_evals(n, 1)
    if expected_1d != n * 3 { return false }

    return true
}

// ============================================================================
// TEST 5: Matrix construction correctness
// ============================================================================
// Verify that C_i and C_ij matrices are built correctly from A and B.

fn test_matrix_construction() -> bool with Mut {
    // Small test: 3 samples, 3 dims
    let samples = saltelli_generate(3, 3, 99)

    // Build C_1: should equal A everywhere except column 1
    let c1 = saltelli_build_ci(&samples, 1)

    var ok = true
    var i: i32 = 0
    while i < 3 {
        var d: i32 = 0
        while d < 3 {
            let flat = i * 3 + d
            if d == 1 {
                // Column 1 should come from B
                if abs_f64(c1[flat] - samples.matrix_b[flat]) > 1.0e-12 { ok = false }
            } else {
                // Other columns should come from A
                if abs_f64(c1[flat] - samples.matrix_a[flat]) > 1.0e-12 { ok = false }
            }
            d = d + 1
        }
        i = i + 1
    }

    // Build C_02: should equal A everywhere except columns 0 and 2
    let c02 = saltelli_build_cij(&samples, 0, 2)

    i = 0
    while i < 3 {
        var d: i32 = 0
        while d < 3 {
            let flat = i * 3 + d
            if d == 0 || d == 2 {
                if abs_f64(c02[flat] - samples.matrix_b[flat]) > 1.0e-12 { ok = false }
            } else {
                if abs_f64(c02[flat] - samples.matrix_a[flat]) > 1.0e-12 { ok = false }
            }
            d = d + 1
        }
        i = i + 1
    }

    return ok
}

// ============================================================================
// TEST 6: Samples are in [0, 1] range
// ============================================================================

fn test_sample_range() -> bool with Mut {
    let samples = saltelli_generate(100, 4, 7)

    var ok = true
    var i: i32 = 0
    while i < 100 {
        var d: i32 = 0
        while d < 4 {
            let flat = i * 4 + d
            if samples.matrix_a[flat] < 0.0 || samples.matrix_a[flat] > 1.0 { ok = false }
            if samples.matrix_b[flat] < 0.0 || samples.matrix_b[flat] > 1.0 { ok = false }
            d = d + 1
        }
        i = i + 1
    }

    return ok
}

// ============================================================================
// TEST 7: Additive model (no interactions, indices should sum to 1)
// ============================================================================
// f(x1, x2, x3) = x1 + 2*x2 + 3*x3
// Var = 1/12 + 4/12 + 9/12 = 14/12
// S1 = 1/14, S2 = 4/14, S3 = 9/14
// All S_ij = 0

fn additive_model(x: [f64; 10]) -> f64 {
    return x[0] + 2.0 * x[1] + 3.0 * x[2]
}

fn test_additive_model() -> bool with Mut {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 3, 53)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 3, additive_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 3, additive_model)
        k = k + 1
    }

    // C_i for each dimension
    let c0 = saltelli_build_ci(&samples, 0)
    let c1 = saltelli_build_ci(&samples, 1)
    let c2 = saltelli_build_ci(&samples, 2)

    var out_c0: [f64; 1000] = [0.0; 1000]
    var out_c1: [f64; 1000] = [0.0; 1000]
    var out_c2: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 3, additive_model)
        out_c1[k] = saltelli_eval_row(&c1, k, 3, additive_model)
        out_c2[k] = saltelli_eval_row(&c2, k, 3, additive_model)
        k = k + 1
    }

    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let s3 = saltelli_first_order(&samples, &out_a, &out_b, &out_c2)

    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)
    let st3 = saltelli_total_order(&samples, &out_a, &out_c2)

    let tol: f64 = 0.15
    var ok = true

    // S1 ~ 1/14 ~ 0.071
    if abs_f64(s1 - 0.071) > tol { ok = false }

    // S2 ~ 4/14 ~ 0.286
    if abs_f64(s2 - 0.286) > tol { ok = false }

    // S3 ~ 9/14 ~ 0.643
    if abs_f64(s3 - 0.643) > tol { ok = false }

    // For an additive model, total order should equal first order
    if abs_f64(st1 - s1) > 0.1 { ok = false }
    if abs_f64(st2 - s2) > 0.1 { ok = false }
    if abs_f64(st3 - s3) > 0.1 { ok = false }

    // Sum of first-order indices should be close to 1 (no interactions)
    let s_sum = s1 + s2 + s3
    if abs_f64(s_sum - 1.0) > 0.2 { ok = false }

    return ok
}

// ============================================================================
// MAIN: run all tests
// ============================================================================

fn main() -> i32 with Mut {
    var failures: i32 = 0

    if !test_matrix_construction() { failures = failures + 1 }
    if !test_sample_range() { failures = failures + 1 }
    if !test_n2d2_efficiency() { failures = failures + 1 }
    if !test_linear_model() { failures = failures + 1 }
    if !test_interaction_model() { failures = failures + 1 }
    if !test_additive_model() { failures = failures + 1 }
    if !test_ishigami() { failures = failures + 1 }

    return failures
}

//@ run-pass
//@ requires: madaros
//@ description: Tiny portfolio v30 smoke for Erdős/Hadwiger-Nelson scope audit

fn portfolio_mix(acc: i64, value: i64, salt: i64) -> i64 {
    return ((acc * 16777619) + value + salt) % 1000000007
}

fn portfolio_entry_fingerprint(kind: i64, instance_fp: i64, certificate_fp: i64,
                               result_code: i64, checker_code: i64) -> i64 {
    if kind != 33 { return 0 - 1 }
    if instance_fp != 37553010 { return 0 - 1 }
    if certificate_fp != 180094659 { return 0 - 1 }
    if result_code != 1 { return 0 - 1 }
    if checker_code != 33 { return 0 - 1 }

    var fp: i64 = 101
    fp = portfolio_mix(fp, kind, 1103)
    fp = portfolio_mix(fp, instance_fp, 1103)
