    let idx = AR_COUNT
    AR_TAGS[idx] = 6  // TAG_NEG
    AR_LEFT[idx] = child
    AR_RIGHT[idx] = 0 - 1
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = 0 - 1
