        print(")")
        return
    }
    if tag == 4 {
        print("(")
        expr_print(AR_LEFT[idx])
        print(" * ")
        expr_print(AR_RIGHT[idx])
        print(")")
        return
    }
    if tag == 5 {
        print("(")
        expr_print(AR_LEFT[idx])
        print(" / ")
        expr_print(AR_RIGHT[idx])
        print(")")
        return
    }
    if tag == 6 {
        print("(0-")
        expr_print(AR_LEFT[idx])
        print(")")
        return
    }
    if tag == 7 {
        print("sin(")
        expr_print(AR_LEFT[idx])
        print(")")
        return
    }
    if tag == 8 {
        print("cos(")
        expr_print(AR_LEFT[idx])
        print(")")
        return
    }
    if tag == 9 {
        print("exp(")
        expr_print(AR_LEFT[idx])
        print(")")
        return
    }
    if tag == 10 {
