    var current = h
    var i = idx
    while current.ptr != 0 as *mut FnParamList {
        if i == 0 {
            return (*current.ptr).head
        }
        match (*current.ptr).tail {
            Some(next) => {
                current = FnParamListHandle { ptr: next as *mut FnParamList }
                i = i - 1
            }
            None => break
        }
    }
