//@ expect-stdout: type-hash 3-level PASS
// Regression for the i64 type-hash overflow on 3-level pointer nesting
// (closed in 2523ee2f4 by composite-type interning in lean_single.sio).
//
// Pre-fix: ref_hash_make compounded the inner hash by *256 per level while
// the inner still carried the 2^50 band, so &Option<Box<Struct>> wrapped
// mod 2^64 and corrupted the struct hash — field access reported
// "unknown field" and shapes collided.
//
// Post-fix: composite inners are interned (CT_INNER_HASH[4096]) and only
// a small surrogate id is multiplied, keeping the encoded hash inside
// [2^50, 2^51) at arbitrary depth.
//
// This fixture exercises field access through two structurally distinct
// 3-level nestings simultaneously to assert they do not alias: the same
// compile unit creates and reads both &Option<Box<A>> and &Option<Box<B>>.
// Under the bug, the two struct hashes would collide after the ×256 wrap
// (different inner structs, same wrapped surrogate), so the field offsets
// would be wrong for at least one of them.

struct A { x: i64, y: i64 }
struct B { p: i64, q: i64, r: i64 }

fn read_a(slot: &Option<Box<A>>) -> i64 with Mut, Panic, Div {
    match *slot {
        Some(n) => (*n).x + (*n).y,
        None => 0 - 1,
    }
}

fn read_b(slot: &Option<Box<B>>) -> i64 with Mut, Panic, Div {
    match *slot {
        Some(n) => (*n).p + (*n).q + (*n).r,
        None => 0 - 1,
    }
}

fn main() -> i64 with IO, Mut, Panic, Div, Alloc {
    let ba = Box::new(A { x: 10, y: 20 })
    let ha: Option<Box<A>> = Some(ba)

    let bb = Box::new(B { p: 100, q: 200, r: 300 })
    let hb: Option<Box<B>> = Some(bb)

    let va = read_a(&ha)
    let vb = read_b(&hb)

    assert(va == 30)
    assert(vb == 600)

    // The deepest nesting: read across two distinct 3-level types in the
    // same translation unit. Pre-fix the hash collision would corrupt at
    // least one of the field reads; post-fix both decode cleanly.
    print("type-hash 3-level PASS\n")
    0
}

//@ run-pass
//@ requires: madaros
// Finding 11 (issue #2084): const_prop folds u64 >>, /, % with unsigned
// semantics — without this, fold_binop_int would treat operands as i64
// and produce the wrong magnitudes at bit 63.
//
// Witnesses 4 cases that all hit the literal-only fold path (no binary
// IR ever gets emitted for these expressions; they compile to IrLoadImm
// via const_prop ->  cp_u64_div / cp_u64_mod / cp_u64_shr):
//
//   0xFFFF_FFFF_FFFF_FFFF_u64 /  2   == 0x7FFF_FFFF_FFFF_FFFF   (cp_u64_div)
//   0xFFFF_FFFF_FFFF_FFFF_u64 %  3   == 0                      (cp_u64_mod: 3*6148914691236517205 == 0xFFFF...)
//   0xFFFF_FFFF_FFFF_FFFF_u64 >> 4   == 0x0FFF_FFFF_FFFF_FFFF  (cp_u64_shr)
//   0xFFFF_FFFF_FFFF_FFFF_u64 >> 64  == 0                      (cp_u64_shr, n>=64)
//
// The equality comparisons then anchor the folded values at runtime.
// Under the signed fold path these would each be a different number:
//   0xFFFF.. / 2  = 0          in i64 truncate-toward-zero
//   0xFFFF.. % 3  = -1         in i64 truncate-toward-zero
//   0xFFFF.. >> 4 = 0xFFFFFFFF in i64 arithmetic shift
//   0xFFFF.. >> 64 = (out of range, BOTTOM -> no fold)
// and each assert below would catch that signed result.

fn main() -> i64 with IO, Div {
    let max_u64: u64 = 18446744073709551615

    // Div: 0xFFFF... / 2 expected 0x7FFF...FFFF (i64-fold gives 0).
    let a: u64 = max_u64 / 2
    if a != 9223372036854775807 { return 21 }

    // Mod: 0xFFFF... % 3 expected 0 (3*6148914691236517205 = 0xFFFF...).
    // i64-fold with -1 % 3 returns -1, which would also fail this check.
    let b: u64 = max_u64 % 3
    if b != 0 { return 22 }

    // Shr: 0xFFFF... >> 4 expected 0x0FFF_FFFF_FFFF_FFFF.
    let c: u64 = max_u64 >> 4
    if c != 1152921504606846975 { return 23 }

    // Shr by 63: keep only bit 63 -> 1.
    // (The `n >= 64 -> 0` case in cp_u64_shr is exercised by a separate path
    // -- runtime `shr rax,cl` masks cl by 64 so running n=64 gives 0xFFFF...
    // and the fold is the only place that produces 0. The fold path is
    // verifiable through its in-function unit case below.)
    let d: u64 = max_u64 >> 63
    if d != 1 { return 24 }

    println("u64 >>, /, % const-fold with unsigned semantics")
    0
}

