}

fn count_nonzero_rect(c: &Canvas, x: i64, y: i64, w: i64, h: i64) -> i64 with Mut {
    var count: i64 = 0
    var yy: i64 = y
    while yy < y + h {
        var xx: i64 = x
        while xx < x + w {
            if read_px(c, xx, yy) != 0 {
                count = count + 1
            }
            xx = xx + 1
        }
        yy = yy + 1
    }
    count
}

